INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('acc0bc47-c258-408d-ac42-46a6bf065250', '還丹口訣', '還丹口訣', 'a7c34620-2c22-48dc-b872-8a281bdb3bbb', '唐', '["歎羨巨江月影沈，金之主起見鉛心。","須當努力求仙訣，莫使蹉跎歲月深。"]', '["歎羨巨江月影沈，金之主起见鉛心。","須當努力求仙訣，莫使蹉跎歲月深。"]', '诗', 'shi', '', NULL, '還丹口訣 岑真人 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1371dad1-24e0-4448-b3d8-1d40757e51cc', '還丹歌', '還丹歌', 'a7c34620-2c22-48dc-b872-8a281bdb3bbb', '唐', '["九鍊鉛精大道成，我家何慮不長生？","朝尋弄玉過仙府，暮謁麻姑入太清。","神照本來自靈氣，漢武榮知有俗情。","萬事只今空寂寞，一生飄蕩落浮名。","（《大還丹照鑑》）（按：《茅山志》卷七載唐成延昭號沖虛先生，未知即其人否。","）。"]', '["九鍊鉛精大道成，我家何慮不长生？","朝尋弄玉過仙府，暮謁麻姑入太清。","神照本来自靈氣，漢武榮知有俗情。","万事只今空寂寞，一生飄蕩落浮名。","（《大還丹照鑑》）（按：《茅山志》卷七載唐成延昭號沖虛先生，未知即其人否。","）。"]', '诗', 'shi', '', NULL, '還丹歌 岑真人 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1a837c86-84b8-4fb5-9465-f71408c1b9fb', '還丹口訣', '還丹口訣', '9299c4d9-b9a5-45ad-b007-ba1b7720089e', '唐', '["夫養生之術，非難亦非易。","世人也用鉛，不得修鉛志。","才與脫黑衫，便即露素質。","及池炎火上，刀圭依法律。","鉛白還同此，抽時莫教失。","持入赤色門，點時堅如石。","藥用真水精，八數爲第一。","妙精亦八兩，陽人身上出。","兩般相合和，甑山須秘密。","凡曲烏龍上，數滿經三七。","一兩真龍腦，還要肥蘇膩。","白色真龍腦，蒼色亦不是。","別有方法製，取用在臨時。","二物合爲體，須使真金器。","世人會此語，地仙只這是。","若將非處用，殃禍自立至。","十年暗障日，五載不見明。","若點一粟粒，須臾即抵聖。"]', '["夫養生之術，非难亦非易。","世人也用鉛，不得修鉛志。","才與脫黑衫，便即露素質。","及池炎火上，刀圭依法律。","鉛白還同此，抽时莫教失。","持入赤色门，点时堅如石。","藥用真水精，八數爲第一。","妙精亦八兩，陽人身上出。","兩般相合和，甑山須秘密。","凡曲烏龙上，數满經三七。","一兩真龙腦，還要肥蘇膩。","白色真龙腦，蒼色亦不是。","別有方法製，取用在臨时。","二物合爲體，須使真金器。","世人會此語，地仙只這是。","若將非处用，殃禍自立至。","十年暗障日，五載不见明。","若点一粟粒，須臾即抵聖。"]', '诗', 'shi', '', NULL, '還丹口訣 李玄光 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8eacdbcc-b573-4bd7-babe-e2984cc142e2', '還丹歌 一', '還丹歌 一', '9299c4d9-b9a5-45ad-b007-ba1b7720089e', '唐', '["參同金碧盡藏情，頼有陰君序節明。","學人更遇清霞訣，龍虎從兹識本形。"]', '["參同金碧尽藏情，頼有陰君序節明。","学人更遇清霞訣，龙虎從兹識本形。"]', '诗', 'shi', '', NULL, '還丹歌 一 李玄光 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5e0e6b36-2a4c-4965-bc21-b0ed0da7c29d', '還丹歌 二', '還丹歌 二', '9299c4d9-b9a5-45ad-b007-ba1b7720089e', '唐', '["天生元氣本虛無，紅顏長者體如酥。","火裏變身還火裏，仙人得意號玄珠。","。"]', '["天生元氣本虛無，紅顏长者體如酥。","火裏变身還火裏，仙人得意號玄珠。","。"]', '诗', 'shi', '', NULL, '還丹歌 二 李玄光 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a40024b8-922b-498b-950a-a26965ae45f3', '還丹歌 三', '還丹歌 三', '9299c4d9-b9a5-45ad-b007-ba1b7720089e', '唐', '["世人識柔不識剛，便道黃芽色帶黃。","學來若到盃鉛境，始信黃芽色不黃。","（均見《大還丹照鑑》）。"]', '["世人識柔不識剛，便道黄芽色带黄。","学来若到盃鉛境，始信黄芽色不黄。","（均见《大還丹照鑑》）。"]', '诗', 'shi', '', NULL, '還丹歌 三 李玄光 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('78d83efd-57c1-4497-8f48-680255b867a2', '', '', 'ba1a6062-00d8-4856-87f3-8444a7cc9968', '唐', '["。"]', '["。"]', '诗', 'shi', '', NULL, ' 柳沖用 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c90cd379-13d7-470d-bfd1-63d05feddc3d', '巨勝歌（幷序） 一', '巨勝歌（幷序） 一', 'ba1a6062-00d8-4856-87f3-8444a7cc9968', '唐', '["九鼎何所自，都因一炁生。","銀鉛看得所，龍虎自呑幷。","銖兩相句制，河車辨性情。","循還依節候，還丹應可成。"]', '["九鼎何所自，都因一炁生。","銀鉛看得所，龙虎自呑幷。","銖兩相句制，河车辨性情。","循還依節候，還丹應可成。"]', '诗', 'shi', '', NULL, '巨勝歌（幷序） 一 柳沖用 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cabd68ce-1899-419e-89c0-d81d92cbd258', '巨勝歌（幷序） 二', '巨勝歌（幷序） 二', 'ba1a6062-00d8-4856-87f3-8444a7cc9968', '唐', '["龜蛇體殊異，鉛汞共宗祖。","二女雖同居，良媒分子母。","配合由三花，青龍句白虎。","四象既可憑，五神當有主。"]', '["龟蛇體殊異，鉛汞共宗祖。","二女雖同居，良媒分子母。","配合由三花，青龙句白虎。","四象既可憑，五神當有主。"]', '诗', 'shi', '', NULL, '巨勝歌（幷序） 二 柳沖用 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('df8ad861-138c-4404-b8b6-40ffd4be7a32', '巨勝歌（幷序） 三', '巨勝歌（幷序） 三', 'ba1a6062-00d8-4856-87f3-8444a7cc9968', '唐', '["巍巍尊復高，飄飄何左顧。","世人徒鍊丹，不識神仙路。","衆石屬坎宮，假名皆不悟。","黑白既不知，流年亦虛度。"]', '["巍巍尊复高，飄飄何左顧。","世人徒鍊丹，不識神仙路。","衆石屬坎宮，假名皆不悟。","黑白既不知，流年亦虛度。"]', '诗', 'shi', '', NULL, '巨勝歌（幷序） 三 柳沖用 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('85734995-25c2-4c19-a8a0-d548a46d41dc', '巨勝歌（幷序） 四', '巨勝歌（幷序） 四', 'ba1a6062-00d8-4856-87f3-8444a7cc9968', '唐', '["盡言水土金，三物成大藥。","假氣遞相生，相生復相爍。","黃芽不是鉛，元向鉛中作。","舉東已合西，戊己爲囊橐。"]', '["尽言水土金，三物成大藥。","假氣遞相生，相生复相爍。","黄芽不是鉛，元向鉛中作。","舉东已合西，戊己爲囊橐。"]', '诗', 'shi', '', NULL, '巨勝歌（幷序） 四 柳沖用 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eb9512bc-359e-42fd-9848-127b48007cfe', '巨勝歌（幷序） 五', '巨勝歌（幷序） 五', 'ba1a6062-00d8-4856-87f3-8444a7cc9968', '唐', '["二八成兩家，中弦敵二八。","乃知天地間，陰陽制樞轄。","子因母而生，母因子而殺。","長養嬰孩精，溫顏防利滑。","月滿每成形，抽添還暫歇。","壬子一陽生，循環至玄絕。","若知出世期，神符與白雪。"]', '["二八成兩家，中弦敵二八。","乃知天地间，陰陽制樞轄。","子因母而生，母因子而殺。","长養嬰孩精，溫顏防利滑。","月满每成形，抽添還暫歇。","壬子一陽生，循环至玄絕。","若知出世期，神符與白雪。"]', '诗', 'shi', '', NULL, '巨勝歌（幷序） 五 柳沖用 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ed8bf4ef-9055-4ef3-b6b0-1bdee012de91', '巨勝歌（幷序） 六', '巨勝歌（幷序） 六', 'ba1a6062-00d8-4856-87f3-8444a7cc9968', '唐', '["修真鍊形須守一，參差一二爐間失。","且將壬子制裏蹄，不然更泥扶桑日。","必令有味到無情，方保元和天性質。","不要他處覓良媒，夫妻由來相配匹。","馬牙從此勝琅玕，弦望晦朔候遲疾。","乃知東西定圓方，世人莫謾誇奇術。"]', '["修真鍊形須守一，參差一二爐间失。","且將壬子制裏蹄，不然更泥扶桑日。","必令有味到無情，方保元和天性質。","不要他处覓良媒，夫妻由来相配匹。","马牙從此勝琅玕，弦望晦朔候遲疾。","乃知东西定圓方，世人莫謾誇奇術。"]', '诗', 'shi', '', NULL, '巨勝歌（幷序） 六 柳沖用 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bf5f583c-7b83-49a9-9fbb-9e685f99b6f9', '巨勝歌（幷序） 七', '巨勝歌（幷序） 七', 'ba1a6062-00d8-4856-87f3-8444a7cc9968', '唐', '["水母金父不易識，化他流珠轉輝赩。","假氣若到白雪宮，黃芽從兹實難測。","隄防堅固半浮沉，姹女悲吟寧暫息。"]', '["水母金父不易識，化他流珠轉輝赩。","假氣若到白雪宮，黄芽從兹實难測。","隄防堅固半浮沉，姹女悲吟寧暫息。"]', '诗', 'shi', '', NULL, '巨勝歌（幷序） 七 柳沖用 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3c4b17f8-1c1d-4005-b868-cfb3bf1e9a15', '巨勝歌（幷序） 八', '巨勝歌（幷序） 八', 'ba1a6062-00d8-4856-87f3-8444a7cc9968', '唐', '["古詩歌訣盡分明，只是迷人強穿鑿。","至道猶來不甚煩，妄將砂汞相交錯。","未知赤血與青腰，終日只向鉛中作。","鉛中有物豈易修，失之一氣無斷齶。"]', '["古诗歌訣尽分明，只是迷人強穿鑿。","至道猶来不甚煩，妄將砂汞相交錯。","未知赤血與青腰，終日只向鉛中作。","鉛中有物豈易修，失之一氣無斷齶。"]', '诗', 'shi', '', NULL, '巨勝歌（幷序） 八 柳沖用 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dfdce60e-4d4a-4d83-9973-6dbbb0f619a8', '巨勝歌（幷序） 九', '巨勝歌（幷序） 九', 'ba1a6062-00d8-4856-87f3-8444a7cc9968', '唐', '["黃芽不是鉛，二舞會生丹田。","若求巨勝法，鉛汞須自然。","顧非世間有，不問愚與賢。","日魂與月華，識者皆神仙。"]', '["黄芽不是鉛，二舞會生丹田。","若求巨勝法，鉛汞須自然。","顧非世间有，不问愚與賢。","日魂與月华，識者皆神仙。"]', '诗', 'shi', '', NULL, '巨勝歌（幷序） 九 柳沖用 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8ce03eed-49ab-4cc5-8b13-979c50a65966', '巨勝歌（幷序） 十', '巨勝歌（幷序） 十', 'ba1a6062-00d8-4856-87f3-8444a7cc9968', '唐', '["太元道士本神仙，移名中都學自然。","世人鍊藥迷金水，燒盡黃芽不識鉛。","西蜀水銀人競採，得火須臾變作煙。","若能得一莫執一妙法玄之又更玄。","（《正統道藏》如字號。","）（〖1〗《崇文總目》卷四道書類七著錄：「《巨勝歌》一卷。","」）。"]', '["太元道士本神仙，移名中都学自然。","世人鍊藥迷金水，燒尽黄芽不識鉛。","西蜀水銀人競採，得火須臾变作煙。","若能得一莫執一妙法玄之又更玄。","（《正統道藏》如字號。","）（〖1〗《崇文總目》卷四道书類七著錄：「《巨勝歌》一卷。","」）。"]', '诗', 'shi', '', NULL, '巨勝歌（幷序） 十 柳沖用 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('77280d4d-8e94-4499-8802-1a616694f1e6', '還丹口訣', '還丹口訣', 'eba44399-294c-4a43-8a67-33136fad5a18', '唐', '["捉取東青龍，配與西白虎。","更將南朱雀，會偶北玄武。","四者窮其根，本來同宗祖。","世人不知深，衆石多錯悮。","不解演陰陽，配合爲夫婦。","陰陽氣本變，始得俱相聚。","就中最妙者，須得中央土。","泥鑪不假法，運火心須苦。","一日兩卦候，進退依節度。","細窮日月盈，莫遣失風雨。","十月還丹成，身除貧病苦。","滄海與桑田，變時君治覩。","誰人得吾道，不得輕取與。","容易泄天機，謫罰殃七祖。","（《大還丹照鑑》）。"]', '["捉取东青龙，配與西白虎。","更將南朱雀，會偶北玄武。","四者窮其根，本来同宗祖。","世人不知深，衆石多錯悮。","不解演陰陽，配合爲夫婦。","陰陽氣本变，始得俱相聚。","就中最妙者，須得中央土。","泥鑪不假法，運火心須苦。","一日兩卦候，進退依節度。","細窮日月盈，莫遣失风雨。","十月還丹成，身除貧病苦。","滄海與桑田，变时君治覩。","誰人得吾道，不得轻取與。","容易泄天機，謫罰殃七祖。","（《大還丹照鑑》）。"]', '诗', 'shi', '', NULL, '還丹口訣 曹真人 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c1a44f9c-fff8-411d-96f5-98cbd5a69a9d', '石膽歌', '石膽歌', '049aa738-549d-4a8f-ae9f-7313ada74142', '唐', '["白珠碧水平鐺中，文武微微聲漸雄。","一伏三時成半死，再烹經宿變成銅。","將軍此朝須舞劍，青腰小兒莫相猒。","白霜理石常煞人，黃礬石膽從來艷。","鐵堝土釜各文武，一須五時連夜煮。","開匣見玉須焚香，仙人遇之名長久。","（唐金陵子《龍虎還丹訣》卷下。","原署「天目徐真君」。","）。"]', '["白珠碧水平鐺中，文武微微声漸雄。","一伏三时成半死，再烹經宿变成銅。","將軍此朝須舞劍，青腰小兒莫相猒。","白霜理石常煞人，黄礬石膽從来艷。","鐵堝土釜各文武，一須五时連夜煮。","开匣见玉須焚香，仙人遇之名长久。","（唐金陵子《龙虎還丹訣》卷下。","原署「天目徐真君」。","）。"]', '诗', 'shi', '', NULL, '石膽歌 徐真君 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f0d3fb4f-0fb0-4c39-9733-f47e4883dcb3', '還丹口訣', '還丹口訣', 'd20a855b-97fe-4d3c-8302-c322381abec6', '唐', '["陰陽造化不須傳，只用水銀是黑鉛。","不傷汞，不傷鉛，此物道中玄復玄。","世人識得真龍虎，成道只在片時間。","（《不還丹照鑑》）。"]', '["陰陽造化不須傳，只用水銀是黑鉛。","不傷汞，不傷鉛，此物道中玄复玄。","世人識得真龙虎，成道只在片时间。","（《不還丹照鑑》）。"]', '诗', 'shi', '', NULL, '還丹口訣 彭真君 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('55ba5ed5-2114-480a-bcfa-5562462fa277', '還丹口訣', '還丹口訣', '4e4d4de8-97e5-43c5-8333-0bb0537a7a00', '唐', '["真汞非水銀，還向此中得。","若要真水銀，須求坎裏力。","（《大還丹照鑑》。","）。"]', '["真汞非水銀，還向此中得。","若要真水銀，須求坎裏力。","（《大還丹照鑑》。","）。"]', '诗', 'shi', '', NULL, '還丹口訣 陶埴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('423c6c2d-126b-4721-bb10-932264347788', '還金歌', '還金歌', '4e4d4de8-97e5-43c5-8333-0bb0537a7a00', '唐', '["仙人拍手雪成團，黃花欲入紫河難。","子母一時流作水，變化還同九轉丹。","（《正統道藏》本陶埴《還金述》引）。"]', '["仙人拍手雪成團，黄花欲入紫河难。","子母一时流作水，变化還同九轉丹。","（《正統道藏》本陶埴《還金述》引）。"]', '诗', 'shi', '', NULL, '還金歌 陶埴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0a659ca1-a648-42a7-a681-0104231a665f', '望江南', '望江南', '4e4d4de8-97e5-43c5-8333-0bb0537a7a00', '唐', '["還丹術，切要經手傳。","若信故方終自誤，顛來倒去倒來顛，不得怨神仙。"]', '["還丹術，切要經手傳。","若信故方終自誤，顛来倒去倒来顛，不得怨神仙。"]', '诗', 'shi', '', NULL, '望江南 陶埴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('87a4ee01-060d-43d6-a9a5-b344c9b3ede4', '菩薩蠻', '菩薩蠻', '4e4d4de8-97e5-43c5-8333-0bb0537a7a00', '唐', '["家家盡有長生藥，時人取用皆差錯。","氣候若飛沈，問君何處尋？","眼看猶不識，誤向鉛中覓。","此物沒黃芽，徒勞歲月賒。","（以上二首均見《金液還丹百問訣》。","）。"]', '["家家尽有长生藥，时人取用皆差錯。","氣候若飞沈，问君何处尋？","眼看猶不識，誤向鉛中覓。","此物沒黄芽，徒勞歲月賒。","（以上二首均见《金液還丹百问訣》。","）。"]', '诗', 'shi', '', NULL, '菩薩蠻 陶埴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d90b588a-8eaa-4cfa-b422-6512ccabfa83', '還丹歌', '還丹歌', '96934a3a-d450-4e53-9cda-621dbc1a3001', '唐', '["青龍起，白虎卧，玄武飛，朱雀坐，黃龍中央自結裏。","母憐子，子憐母，爐中結成雲一朵。","（《金液還丹百問訣》。","）。"]', '["青龙起，白虎卧，玄武飞，朱雀坐，黄龙中央自結裏。","母怜子，子怜母，爐中結成云一朵。","（《金液還丹百问訣》。","）。"]', '诗', 'shi', '', NULL, '還丹歌 賀蘭求 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9bc615c9-bc46-4928-ade8-8b933b8488fb', '還丹口訣', '還丹口訣', '95925ee9-0483-41f2-9b59-4a25ffb8dde9', '唐', '["世上人人盡好藥，箇箇元來尋不着。","也道用鉛不用鉛，及至用鉛還是錯。","用鉛不用鉛，不用得長年。","用鉛須用鉛，用鉛住丹田。","無鉛不成丹，還丹生在鉛。","金公能住水，黑鉛有黃芽。","黃芽入汞家，覆載以河車。"]', '["世上人人尽好藥，箇箇元来尋不着。","也道用鉛不用鉛，及至用鉛還是錯。","用鉛不用鉛，不用得长年。","用鉛須用鉛，用鉛住丹田。","無鉛不成丹，還丹生在鉛。","金公能住水，黑鉛有黄芽。","黄芽入汞家，覆載以河车。"]', '诗', 'shi', '', NULL, '還丹口訣 楊玄一 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dbc0a4be-89b7-40f2-a815-93e87aa9e445', '歌', '歌', '95925ee9-0483-41f2-9b59-4a25ffb8dde9', '唐', '["鉛向鉛中出，鉛同色不同。","若能分皂白，日日是仙翁。","（見《正統道藏》本後蜀人著《大還丹照鑑》。","）。"]', '["鉛向鉛中出，鉛同色不同。","若能分皂白，日日是仙翁。","（见《正統道藏》本後蜀人著《大還丹照鑑》。","）。"]', '诗', 'shi', '', NULL, '歌 楊玄一 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0c64e443-640d-4cba-b2df-db75b9d61ed4', '還丹歌 一', '還丹歌 一', '4099fad7-2dc2-44fc-a80a-6be89d6dff12', '唐', '["世上人人緫愛藥，箇箇元來尋不著。","也道用鉛不用鉛，及至用鉛還只錯。","尋不著，莫生嗔，都爲黃芽不得真。","有信有行堪分付，財色不染是真人。","潛拯濟，莫彰露，本覓長生却短祚。","慎勿將身遊貴門，醫卜經求且閑處。","未能隱，沒閑處，且去經求無病藥，長生樂道何憂慮。","鉛爲君，汞爲臣，火爲使者，赤血將軍，守陰守陽，制御伏藥，藥成先用點水銀。","水銀被點堪服餌，鬼官不追人不死。","世世喧喧若得之，閑處經求莫干貴。","心口訣，手眼傳，制伏只在黃芽邊。","心口不決，手眼不傳，耽荒酒色，與道無緣。"]', '["世上人人緫愛藥，箇箇元来尋不著。","也道用鉛不用鉛，及至用鉛還只錯。","尋不著，莫生嗔，都爲黄芽不得真。","有信有行堪分付，財色不染是真人。","潛拯濟，莫彰露，本覓长生却短祚。","慎勿將身游貴门，醫卜經求且闲处。","未能隐，沒闲处，且去經求無病藥，长生乐道何憂慮。","鉛爲君，汞爲臣，火爲使者，赤血將軍，守陰守陽，制御伏藥，藥成先用点水銀。","水銀被点堪服餌，鬼官不追人不死。","世世喧喧若得之，闲处經求莫干貴。","心口訣，手眼傳，制伏只在黄芽邊。","心口不決，手眼不傳，耽荒酒色，與道無緣。"]', '诗', 'shi', '', NULL, '還丹歌 一 楊行真人 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('06c62aad-620b-4872-9eac-da496f1df209', '還丹歌 二', '還丹歌 二', '4099fad7-2dc2-44fc-a80a-6be89d6dff12', '唐', '["丹田水結黃芽起，百日養來伏火矣。","陰居陽鼎是金丹，十月養之堪服餌。","服餌由來駐顏色，容鬢不衰定心力。","賣丹賣藥住人間，壽命千年人不識。"]', '["丹田水結黄芽起，百日養来伏火矣。","陰居陽鼎是金丹，十月養之堪服餌。","服餌由来駐顏色，容鬢不衰定心力。","賣丹賣藥住人间，壽命千年人不識。"]', '诗', 'shi', '', NULL, '還丹歌 二 楊行真人 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6754277b-795b-4adf-a500-4e3727704fe6', '還丹歌 三', '還丹歌 三', '4099fad7-2dc2-44fc-a80a-6be89d6dff12', '唐', '["長生藥，不死丹，世人欲作尋復難。","心猶豫，意遲疑，八丹方法由來有，如何不取一門知。","二人語，共商量，日夜尋思不死方。","若取黑鉛幷姹女，騰身天上自翱翔。","一爲左，一爲右，陰陽具足還丹就。","真須鍊，必長生，逍遙自在紫雲庭。"]', '["长生藥，不死丹，世人欲作尋复难。","心猶豫，意遲疑，八丹方法由来有，如何不取一门知。","二人語，共商量，日夜尋思不死方。","若取黑鉛幷姹女，腾身天上自翱翔。","一爲左，一爲右，陰陽具足還丹就。","真須鍊，必长生，逍遙自在紫云庭。"]', '诗', 'shi', '', NULL, '還丹歌 三 楊行真人 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d68f048e-cdc4-4583-b776-09fb1aead557', '還丹歌 四', '還丹歌 四', '4099fad7-2dc2-44fc-a80a-6be89d6dff12', '唐', '["世上喧喧車馬人，紅顏綠鬢不長春。","藥術相傳萬甲子，學者忙忙尋不真。","若交箇箇識黃芽，世間那得有貧人。"]', '["世上喧喧车马人，紅顏綠鬢不长春。","藥術相傳万甲子，学者忙忙尋不真。","若交箇箇識黄芽，世间那得有貧人。"]', '诗', 'shi', '', NULL, '還丹歌 四 楊行真人 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e3f49bbf-1824-43f9-a318-bad4a619eb5d', '還丹歌 五', '還丹歌 五', '4099fad7-2dc2-44fc-a80a-6be89d6dff12', '唐', '["老翁老婆造大藥，鉛汞二金用不錯。","出湯入火少精神，半生半死相依約。","依約由來一甲子，上陰下陽相伏矣，世上喧喧若得之，鬼官不收免生死。","鉛是鉛，汞是汞，世上人人緫能用。","草黃芽，木黃芽，世上人人緫謾誇。","自古口傳不形紙，燒者徒勞盡破家。","（按：此詩末八句與軒轅集《還丹口訣》中八句相近，見本書卷三十。","）。"]', '["老翁老婆造大藥，鉛汞二金用不錯。","出湯入火少精神，半生半死相依約。","依約由来一甲子，上陰下陽相伏矣，世上喧喧若得之，鬼官不收免生死。","鉛是鉛，汞是汞，世上人人緫能用。","草黄芽，木黄芽，世上人人緫謾誇。","自古口傳不形紙，燒者徒勞尽破家。","（按：此诗末八句與軒轅集《還丹口訣》中八句相近，见本书卷三十。","）。"]', '诗', 'shi', '', NULL, '還丹歌 五 楊行真人 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('40dcf6e1-7879-47a8-92f1-a22dd7e6188d', '還丹歌 六', '還丹歌 六', '4099fad7-2dc2-44fc-a80a-6be89d6dff12', '唐', '["西方白帝居武都，裏有雞冠衆所須。","華池固濟經七日，姹女因媒尋得夫。","看鑪切候四時炁，冷暖寒溫心不寐。","供養仙人禮度周，一點黃金應滿地。"]', '["西方白帝居武都，裏有雞冠衆所須。","华池固濟經七日，姹女因媒尋得夫。","看鑪切候四时炁，冷暖寒溫心不寐。","供養仙人禮度周，一点黄金應满地。"]', '诗', 'shi', '', NULL, '還丹歌 六 楊行真人 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1fc33736-ffa7-48c7-9cdb-57f6113171a7', '還丹歌 七', '還丹歌 七', '4099fad7-2dc2-44fc-a80a-6be89d6dff12', '唐', '["鉛汞二陰，還丹之心。","相制不難，人迷不尋。","學者不見，徒費千金。","堪得指教，作福拯貧。","如斯之用，天人不嗔。","非道破除，天之大怒。","惡病加之，遭官刑獄。"]', '["鉛汞二陰，還丹之心。","相制不难，人迷不尋。","学者不见，徒費千金。","堪得指教，作福拯貧。","如斯之用，天人不嗔。","非道破除，天之大怒。","惡病加之，遭官刑獄。"]', '诗', 'shi', '', NULL, '還丹歌 七 楊行真人 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ce598c0e-bf69-4cec-8aa4-67621a252896', '還丹歌 八', '還丹歌 八', '4099fad7-2dc2-44fc-a80a-6be89d6dff12', '唐', '["黑類不同居，母子相依約。","不得鉛黃芽，制伏還不著。","黃芽陰中伏，白雪陽中作。","將入火中燒，陰陽相繫縛。","母子不能逃，生死不離却。"]', '["黑類不同居，母子相依約。","不得鉛黄芽，制伏還不著。","黄芽陰中伏，白雪陽中作。","將入火中燒，陰陽相繫縛。","母子不能逃，生死不離却。"]', '诗', 'shi', '', NULL, '還丹歌 八 楊行真人 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e080e328-ad0b-4c88-978a-9ff210a47b04', '還丹歌 九', '還丹歌 九', '4099fad7-2dc2-44fc-a80a-6be89d6dff12', '唐', '["丹砂丹砂，濟命濟家。","能濟我命，能濟我家。","能生姹女，嫁與黃芽。","事夫潔素，無喜無怒。","禮樂周旋，晨昏節度。","金亦可作，世亦可度。","作今不成，徒然自悮。"]', '["丹砂丹砂，濟命濟家。","能濟我命，能濟我家。","能生姹女，嫁與黄芽。","事夫潔素，無喜無怒。","禮乐周旋，晨昏節度。","金亦可作，世亦可度。","作今不成，徒然自悮。"]', '诗', 'shi', '', NULL, '還丹歌 九 楊行真人 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b3a13aa4-3b5d-4dd0-b426-fc1f51c9bf91', '還丹歌 十', '還丹歌 十', '4099fad7-2dc2-44fc-a80a-6be89d6dff12', '唐', '["汞結本在丹田中，次居陽鼎炁相通。","和合三朝方始住，還知大藥在鉛中。","先入陰鑪成大白，後居陽鼎變金丹。","世人若達其中理，水銀被制不爲難。"]', '["汞結本在丹田中，次居陽鼎炁相通。","和合三朝方始住，還知大藥在鉛中。","先入陰鑪成大白，後居陽鼎变金丹。","世人若達其中理，水銀被制不爲难。"]', '诗', 'shi', '', NULL, '還丹歌 十 楊行真人 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b6009836-158f-4faf-8a93-648cd5983066', '還丹歌 十一', '還丹歌 十一', '4099fad7-2dc2-44fc-a80a-6be89d6dff12', '唐', '["朱砂水銀入鉛池，收得黃芽人不知。","本是仙人留口訣，有緣而遇還要師。","師須分明傳口訣，世上喧喧少言說。","七十年中付一人，分明還須有仙骨。"]', '["朱砂水銀入鉛池，收得黄芽人不知。","本是仙人留口訣，有緣而遇還要師。","師須分明傳口訣，世上喧喧少言说。","七十年中付一人，分明還須有仙骨。"]', '诗', 'shi', '', NULL, '還丹歌 十一 楊行真人 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('95803491-da2a-4cda-811c-f9e527f6aa1c', '還丹歌 十二', '還丹歌 十二', '4099fad7-2dc2-44fc-a80a-6be89d6dff12', '唐', '["世上求道，酒肉愚癡。","百年欲過，顒顒不知。","金公制伏，還丹一支。","朱砂伏火，治病無疑。","長生有望，堅固無疑。","不衰不老，彭祖同時。"]', '["世上求道，酒肉愚癡。","百年欲過，顒顒不知。","金公制伏，還丹一支。","朱砂伏火，治病無疑。","长生有望，堅固無疑。","不衰不老，彭祖同时。"]', '诗', 'shi', '', NULL, '還丹歌 十二 楊行真人 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ac7d1e67-0a71-4507-a8f7-4b5307db20c7', '還丹歌 十三', '還丹歌 十三', '4099fad7-2dc2-44fc-a80a-6be89d6dff12', '唐', '["古仙取得赤銅精，一兩水銀一兩精。","碙砂半兩漿水煎，從朝至暮體能堅。","入銅入鐵鑄鏡力，鬼神怕懼不能言。","若得至人留口訣，事須保愛始長年。"]', '["古仙取得赤銅精，一兩水銀一兩精。","碙砂半兩漿水煎，從朝至暮體能堅。","入銅入鐵鑄镜力，鬼神怕懼不能言。","若得至人留口訣，事須保愛始长年。"]', '诗', 'shi', '', NULL, '還丹歌 十三 楊行真人 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6197b81a-c957-4ac2-abc7-6c80b099902c', '還丹歌 十四', '還丹歌 十四', '4099fad7-2dc2-44fc-a80a-6be89d6dff12', '唐', '["陽精若堅魂自立，陰精若堅魄自成。","魂魄堅強心有聖，紅鉛朱汞更能靈。","得遇仙公留此術，魂神魄立自長生。"]', '["陽精若堅魂自立，陰精若堅魄自成。","魂魄堅強心有聖，紅鉛朱汞更能靈。","得遇仙公留此術，魂神魄立自长生。"]', '诗', 'shi', '', NULL, '還丹歌 十四 楊行真人 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('513c2b61-6e12-455f-9c69-506ef406c6a3', '還丹歌 十五', '還丹歌 十五', '4099fad7-2dc2-44fc-a80a-6be89d6dff12', '唐', '["能知少女，必定還精。","能伏朱兒，必定堅貞。","金精石髓，是魂之靈。","能修者聖，能伏者靈。","鬼官不追，仙籍有名。","。"]', '["能知少女，必定還精。","能伏朱兒，必定堅貞。","金精石髓，是魂之靈。","能修者聖，能伏者靈。","鬼官不追，仙籍有名。","。"]', '诗', 'shi', '', NULL, '還丹歌 十五 楊行真人 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('23bded27-799d-41e3-ae85-8ccde24f8a6b', '還丹歌 十六', '還丹歌 十六', '4099fad7-2dc2-44fc-a80a-6be89d6dff12', '唐', '["五十六十堪分付，此處由來始堅固。","還須醫卜掩行藏，行住坐卧無憂慮。"]', '["五十六十堪分付，此处由来始堅固。","還須醫卜掩行藏，行住坐卧無憂慮。"]', '诗', 'shi', '', NULL, '還丹歌 十六 楊行真人 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('658e099d-6868-4ae7-b825-c8dc51d542cd', '還丹歌 十七', '還丹歌 十七', '4099fad7-2dc2-44fc-a80a-6be89d6dff12', '唐', '["自古來來多少人，都緣此術損亡身，須學陰陽兼卜相，混俗經求且外貧。"]', '["自古来来多少人，都緣此術損亡身，須学陰陽兼卜相，混俗經求且外貧。"]', '诗', 'shi', '', NULL, '還丹歌 十七 楊行真人 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('80c259f1-fddb-40d5-a4fa-d95ae3f5065b', '還丹歌 十八', '還丹歌 十八', '4099fad7-2dc2-44fc-a80a-6be89d6dff12', '唐', '["堪分付，遞相傳，拯濟元來此道門。","妄傳之者遭殃禍，父子麤踈不合言。"]', '["堪分付，遞相傳，拯濟元来此道门。","妄傳之者遭殃禍，父子麤踈不合言。"]', '诗', 'shi', '', NULL, '還丹歌 十八 楊行真人 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bc84e601-775d-4d35-933b-1cba94f5c18f', '還丹歌 十九', '還丹歌 十九', '4099fad7-2dc2-44fc-a80a-6be89d6dff12', '唐', '["欲覓丹田本是鉛，朱砂被制體能堅。","但得至人傳口訣，紅鉛入水大丹圓。"]', '["欲覓丹田本是鉛，朱砂被制體能堅。","但得至人傳口訣，紅鉛入水大丹圓。"]', '诗', 'shi', '', NULL, '還丹歌 十九 楊行真人 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('942238be-eef3-4814-aa4f-ea78bcd143d4', '還丹歌 二○', '還丹歌 二○', '4099fad7-2dc2-44fc-a80a-6be89d6dff12', '唐', '["一一事須心口記，造作還須手眼傳。","河車覆載丹田裏，伏火緫在黃芽邊。"]', '["一一事須心口記，造作還須手眼傳。","河车覆載丹田裏，伏火緫在黄芽邊。"]', '诗', 'shi', '', NULL, '還丹歌 二○ 楊行真人 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('32b1424f-af79-40cc-9cb7-008ee130543e', '還丹歌 二一', '還丹歌 二一', '4099fad7-2dc2-44fc-a80a-6be89d6dff12', '唐', '["金公能住水，黑鉛有黃芽。","變此黃芽水，用水作河車。"]', '["金公能住水，黑鉛有黄芽。","变此黄芽水，用水作河车。"]', '诗', 'shi', '', NULL, '還丹歌 二一 楊行真人 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('85eae494-0d40-49be-a02c-d3dca82b1732', '還丹歌 二二', '還丹歌 二二', '4099fad7-2dc2-44fc-a80a-6be89d6dff12', '唐', '["南方赤帝髓，本是太陰精。","古仙能奪剝，却取水銀形。"]', '["南方赤帝髓，本是太陰精。","古仙能奪剝，却取水銀形。"]', '诗', 'shi', '', NULL, '還丹歌 二二 楊行真人 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3609696b-2e4a-410c-9e22-494f212bcf7e', '還丹歌 二三', '還丹歌 二三', '4099fad7-2dc2-44fc-a80a-6be89d6dff12', '唐', '["二精合會，還丹之心。","若逢此理，不假遠尋。","黑鉛取陽，朱砂取陰。","（《還丹歌訣》卷上。","）（按：快樂組詩第一首前四句與楊玄一詩幾全同，頗疑二人爲同一人。","姑分列。","俟續考。","）。"]', '["二精合會，還丹之心。","若逢此理，不假远尋。","黑鉛取陽，朱砂取陰。","（《還丹歌訣》卷上。","）（按：快乐組诗第一首前四句與楊玄一诗幾全同，頗疑二人爲同一人。","姑分列。","俟續考。","）。"]', '诗', 'shi', '', NULL, '還丹歌 二三 楊行真人 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8d63e196-77bc-4d56-aac8-790c78cfca4f', '還丹口訣', '還丹口訣', '4908f086-3d11-4ded-ac5f-0954b4d66e78', '唐', '["淮王煉秋石，黃帝美金花。","世人不悟莫咨嗟，神仙之藥徧中華。","不用鉛，不用砂，迷愚之者亦如麻。","修取鉛，煉取砂，頃刻之間見黃芽。","得黃芽，莫謾誇，將此黃芽配女家，夫妻和合歲月賒。","身披紫服駕雲霞，驗之刀圭是河車。","。"]', '["淮王煉秋石，黄帝美金花。","世人不悟莫咨嗟，神仙之藥徧中华。","不用鉛，不用砂，迷愚之者亦如麻。","修取鉛，煉取砂，頃刻之间见黄芽。","得黄芽，莫謾誇，將此黄芽配女家，夫妻和合歲月賒。","身披紫服駕云霞，驗之刀圭是河车。","。"]', '诗', 'shi', '', NULL, '還丹口訣 楊真人 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('76afddd8-ba7c-44f3-bc9d-ba538037661c', '再歌', '再歌', '4908f086-3d11-4ded-ac5f-0954b4d66e78', '唐', '["陰中有陽，陽中有陰。","既識砂中汞，須求鉛裏金。","二味實天地之大寶，日月之至精。","鍊得此者，下鬼不欺。","（《大還丹照鑑》）（按：楊真人有可能爲前二人中之一人，亦可能爲同一人。","因無他據，姑分列。","）。"]', '["陰中有陽，陽中有陰。","既識砂中汞，須求鉛裏金。","二味實天地之大寶，日月之至精。","鍊得此者，下鬼不欺。","（《大還丹照鑑》）（按：楊真人有可能爲前二人中之一人，亦可能爲同一人。","因無他據，姑分列。","）。"]', '诗', 'shi', '', NULL, '再歌 楊真人 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('87f511a9-b8bc-4b0c-b12e-7eb9b323013a', '還丹口訣', '還丹口訣', '72e01bca-2994-4e2d-972d-5d5c87db85d9', '唐', '["日魂月魄無形狀，採得天然太新樣。","契合神仙實難論，雲霄起在黃芽上。","龍騰虎伏變金田，始末須得出世鉛。","爲家爲屋自然居，配儷之時頃刻間。","認得離胎爭欲言，不在文書口訣傳。","（《大還丹照鑑》）。"]', '["日魂月魄無形狀，採得天然太新樣。","契合神仙實难論，云霄起在黄芽上。","龙腾虎伏变金田，始末須得出世鉛。","爲家爲屋自然居，配儷之时頃刻间。","認得離胎爭欲言，不在文书口訣傳。","（《大還丹照鑑》）。"]', '诗', 'shi', '', NULL, '還丹口訣 董大仙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8cf55600-f109-404c-9390-cdc31ecfd03d', '', '', '0857a4a4-e4c8-4256-bc9c-7722d99b4bb0', '唐', '["。"]', '["。"]', '诗', 'shi', '', NULL, ' 韓蘊中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a64ae186-f7f8-47ff-a7d0-40d3bac49b8e', '火記歌（幷序） 一', '火記歌（幷序） 一', '0857a4a4-e4c8-4256-bc9c-7722d99b4bb0', '唐', '["復始纔陽發，循環順節移。","龍潛騰未得，虎伏叫聲希。","二炁相方會，三花兆啟期。","火盈臨九數，虧折却來歸。"]', '["复始纔陽發，循环順節移。","龙潛腾未得，虎伏叫声希。","二炁相方會，三花兆啟期。","火盈臨九數，虧折却来归。"]', '诗', 'shi', '', NULL, '火記歌（幷序） 一 韓蘊中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0cee687b-4e96-4b65-a857-8651688ce565', '火記歌（幷序） 二', '火記歌（幷序） 二', '0857a4a4-e4c8-4256-bc9c-7722d99b4bb0', '唐', '["二九臨鑪日，乾坤氣正交。","金童來剋木，土鎮水胎胞。","感應相吞噉，和同在意調。","進時加刻漏，退即卦依爻。"]', '["二九臨鑪日，乾坤氣正交。","金童来剋木，土鎮水胎胞。","感應相吞噉，和同在意調。","進时加刻漏，退即卦依爻。"]', '诗', 'shi', '', NULL, '火記歌（幷序） 二 韓蘊中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6625e314-d7b8-4ce7-b89c-2b32df0d902d', '火記歌（幷序） 三', '火記歌（幷序） 三', '0857a4a4-e4c8-4256-bc9c-7722d99b4bb0', '唐', '["道泰親承候，陽和始發生。","律移衤孟月，斗建守寅行。","君子心乾惕，陰陽順節萌。","三旬終出戶，擣治再還烹。"]', '["道泰親承候，陽和始發生。","律移衤孟月，斗建守寅行。","君子心乾惕，陰陽順節萌。","三旬終出戶，擣治再還烹。"]', '诗', 'shi', '', NULL, '火記歌（幷序） 三 韓蘊中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9209c9ab-b227-4ddc-ae60-72b179129198', '火記歌（幷序） 四', '火記歌（幷序） 四', '0857a4a4-e4c8-4256-bc9c-7722d99b4bb0', '唐', '["榆死魁臨卯，三無正是時。","日魂和月魄，（此兩精合爲大道也。","）龍虎自相持。","大壯成䂓矩，花開向桂枝。","罷鑪停火候，青色轉光輝。"]', '["榆死魁臨卯，三無正是时。","日魂和月魄，（此兩精合爲大道也。","）龙虎自相持。","大壯成䂓矩，花开向桂枝。","罷鑪停火候，青色轉光輝。"]', '诗', 'shi', '', NULL, '火記歌（幷序） 四 韓蘊中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ca8452b3-b9a7-491f-89a7-972b9fc2bac2', '火記歌（幷序） 五', '火記歌（幷序） 五', '0857a4a4-e4c8-4256-bc9c-7722d99b4bb0', '唐', '["萬木盡含陽，花開滿路香。","金雞乘大火，（朱火精。","）玉兔却虧傷。","（水精。","）至士憂生死，尊卑倐忽亡。","藥成朝大帝，服餌滅災殃。","。"]', '["万木尽含陽，花开满路香。","金雞乘大火，（朱火精。","）玉兔却虧傷。","（水精。","）至士憂生死，尊卑倐忽亡。","藥成朝大帝，服餌滅災殃。","。"]', '诗', 'shi', '', NULL, '火記歌（幷序） 五 韓蘊中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3c5f5ee3-736a-4a7e-a227-2a4cb00b07c6', '火記歌（幷序） 六', '火記歌（幷序） 六', '0857a4a4-e4c8-4256-bc9c-7722d99b4bb0', '唐', '["苦節鍊成乾，修丹在志堅。","虎傷龍帶血，金殺木無煙。","陽盛陰將至，榮來衰自然。","撃聲同磬響，觀視得延年。"]', '["苦節鍊成乾，修丹在志堅。","虎傷龙带血，金殺木無煙。","陽盛陰將至，榮来衰自然。","撃声同磬响，观視得延年。"]', '诗', 'shi', '', NULL, '火記歌（幷序） 六 韓蘊中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2bd98457-e2cd-48d6-b4da-1faa8e3d4681', '火記歌（幷序） 七', '火記歌（幷序） 七', '0857a4a4-e4c8-4256-bc9c-7722d99b4bb0', '唐', '["初六到南宮，陰昇姤啓蒙。","刻頻移律呂，持節遞相攻。","五日纔虧折，三花運數供。","取來臨戶看，血點幾千重。"]', '["初六到南宮，陰昇姤啓蒙。","刻頻移律呂，持節遞相攻。","五日纔虧折，三花運數供。","取来臨戶看，血点幾千重。"]', '诗', 'shi', '', NULL, '火記歌（幷序） 七 韓蘊中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d13cb06b-a107-4558-bc85-fa29cebda14b', '火記歌（幷序） 八', '火記歌（幷序） 八', '0857a4a4-e4c8-4256-bc9c-7722d99b4bb0', '唐', '["小吉柄天符，陰來遁積孚。","金公湊筋髓，朱鳥握機樞。","道體同天地，沖和藥在鑪。","莫將爲變化，服餌死皆蘇。"]', '["小吉柄天符，陰来遁積孚。","金公湊筋髓，朱鸟握機樞。","道體同天地，沖和藥在鑪。","莫將爲变化，服餌死皆蘇。"]', '诗', 'shi', '', NULL, '火記歌（幷序） 八 韓蘊中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4f951e4a-bdfe-4697-ad25-9fe788cdae3b', '火記歌（幷序） 九', '火記歌（幷序） 九', '0857a4a4-e4c8-4256-bc9c-7722d99b4bb0', '唐', '["否閉三陰降，將軍殺炁多。","牽牛星漢會，織女渡天河。","甲乙變傷木，庚辛劎始磨。","令行廵節候，寒暑緫經過。"]', '["否閉三陰降，將軍殺炁多。","牽牛星漢會，织女渡天河。","甲乙变傷木，庚辛劎始磨。","令行廵節候，寒暑緫經過。"]', '诗', 'shi', '', NULL, '火記歌（幷序） 九 韓蘊中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('64ba44ad-2cf1-46e9-8449-9029d0eed27b', '火記歌（幷序） 十', '火記歌（幷序） 十', '0857a4a4-e4c8-4256-bc9c-7722d99b4bb0', '唐', '["月合天剛至，風生薺麥芽。","土公親祭祀，埏埴養金砂。","桂影圓霄漢，曦和韻紫霞。","鴻來玄鳥去，將見水中楂。"]', '["月合天剛至，风生薺麦芽。","土公親祭祀，埏埴養金砂。","桂影圓霄漢，曦和韻紫霞。","鴻来玄鸟去，將见水中楂。"]', '诗', 'shi', '', NULL, '火記歌（幷序） 十 韓蘊中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0c72a376-f4da-4e5c-b810-ddfc30552d34', '火記歌（幷序） 十一', '火記歌（幷序） 十一', '0857a4a4-e4c8-4256-bc9c-7722d99b4bb0', '唐', '["冷炁傷時物，陰來萬木凋。","菊花尋戊已，赤血斬龍腰。","剝爛將爲土，離鉛見即消。","苦心修至道，莫恨路迢迢。"]', '["冷炁傷时物，陰来万木凋。","菊花尋戊已，赤血斬龙腰。","剝爛將爲土，離鉛见即消。","苦心修至道，莫恨路迢迢。"]', '诗', 'shi', '', NULL, '火記歌（幷序） 十一 韓蘊中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2be3bff6-4f67-41fe-9a8c-f2cc2a0e8620', '火記歌（幷序） 十二', '火記歌（幷序） 十二', '0857a4a4-e4c8-4256-bc9c-7722d99b4bb0', '唐', '["上六居坤位，陰陽括始終。","帝男精作髓，離女血殷紅。","二八當交合，三人義不同。","開鑪看至寶，服即變衰翁。"]', '["上六居坤位，陰陽括始終。","帝男精作髓，離女血殷紅。","二八當交合，三人義不同。","开鑪看至寶，服即变衰翁。"]', '诗', 'shi', '', NULL, '火記歌（幷序） 十二 韓蘊中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8edc9aab-08e7-47df-9c20-cfdd9d802285', '火記歌（幷序） 十三', '火記歌（幷序） 十三', '0857a4a4-e4c8-4256-bc9c-7722d99b4bb0', '唐', '["重歷純元地，陽潛造六寒。","三旬攻荐至，六九始成丹。","金牓書名字，仙宮立醮壇。","厭離人世患，羽化去乘鸞。","（鹽膽未左味，煮帝男帝女，三日三夜，左味調黃作匱，養一七日也。","○元陽子《還丹歌訣》卷上。","）（按：元陽子《還丹歌訣》，《郡齋讀書志》〖《文獻通考·經籍考》引〗引《李氏書目》有此書，知爲宋仁宗前著作。","然其中《古神仙身事歌》中提及洞賓、圖南，則又已入宋。","五代後蜀時人著《大還丹照鑑》引韓藴中此歌序爲口訣，因知其應爲唐時人，生活年代待考。","）。"]', '["重歷純元地，陽潛造六寒。","三旬攻荐至，六九始成丹。","金牓书名字，仙宮立醮壇。","厭離人世患，羽化去乘鸾。","（鹽膽未左味，煮帝男帝女，三日三夜，左味調黄作匱，養一七日也。","○元陽子《還丹歌訣》卷上。","）（按：元陽子《還丹歌訣》，《郡斋读书志》〖《文獻通考·經籍考》引〗引《李氏书目》有此书，知爲宋仁宗前著作。","然其中《古神仙身事歌》中提及洞賓、圖南，則又已入宋。","五代後蜀时人著《大還丹照鑑》引韓藴中此歌序爲口訣，因知其應爲唐时人，生活年代待考。","）。"]', '诗', 'shi', '', NULL, '火記歌（幷序） 十三 韓蘊中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aec3d66b-6cdc-4f8c-8ff7-42e95d89a411', '七返砂歌', '七返砂歌', 'cfce85cb-390e-4b1b-878a-504bc538a1de', '唐', '["金公年六十，六十金公老。","姹女年六十，六十姹女少。","金公年三十，姹女還漸少。","老翁得少妻，枯楊自生篠。","夫妻同一處，成道和合了。","根本是黃芽，金公元一家。","姹女入鉛室，須臾地變茶。","覆月合仰月，仰月急須賒。","固濟重固濟，固濟似丹家。","丙丁張下詖，混沌自甜葩。","七八陽數極，九六更須加。","四殻陽既滿，五色似朝霞。","去陽除覆月，上上好黃芽。","黃即黃金色，白即白馬牙。","變化成運載，故號曰河車。","玄明與濱伏，夫婦同一家。","本是王陽術，黃帝羨金花。","智者能隱秘，愚者向人誇。","若達此道者，鶴控白雲涯。","（《大還丹照鑑》）。"]', '["金公年六十，六十金公老。","姹女年六十，六十姹女少。","金公年三十，姹女還漸少。","老翁得少妻，枯楊自生篠。","夫妻同一处，成道和合了。","根本是黄芽，金公元一家。","姹女入鉛室，須臾地变茶。","覆月合仰月，仰月急須賒。","固濟重固濟，固濟似丹家。","丙丁張下詖，混沌自甜葩。","七八陽數極，九六更須加。","四殻陽既满，五色似朝霞。","去陽除覆月，上上好黄芽。","黄即黄金色，白即白马牙。","变化成運載，故號曰河车。","玄明與濱伏，夫婦同一家。","本是王陽術，黄帝羨金花。","智者能隐秘，愚者向人誇。","若達此道者，鹤控白云涯。","（《大還丹照鑑》）。"]', '诗', 'shi', '', NULL, '七返砂歌 竇真君 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b30e5cd2-cd59-4f6f-b775-b3346f5e08c1', '九轉詩 一', '九轉诗 一', 'cfce85cb-390e-4b1b-878a-504bc538a1de', '唐', '["巖叟承恩寵，燒丹在禁闈。","釜中諸藥化，鑪上水銀飛。","璧合秋霜色，光含夜月輝。","緫由明主感，能使道精微。"]', '["巖叟承恩寵，燒丹在禁闈。","釜中諸藥化，鑪上水銀飞。","璧合秋霜色，光含夜月輝。","緫由明主感，能使道精微。"]', '诗', 'shi', '', NULL, '九轉詩 一 竇真君 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f6c892ed-3778-47d6-8e4f-0b52cc38ec6f', '九轉詩 二', '九轉诗 二', 'cfce85cb-390e-4b1b-878a-504bc538a1de', '唐', '["却取抽成汞，還燒遣作砂。","上仙方祕密，中禁藥精華。","紫炁含真色，朱光雜曉霞。","欲將同一體，須更猛三花。","。"]', '["却取抽成汞，還燒遣作砂。","上仙方祕密，中禁藥精华。","紫炁含真色，朱光杂晓霞。","欲將同一體，須更猛三花。","。"]', '诗', 'shi', '', NULL, '九轉詩 二 竇真君 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fb819286-2887-4670-b349-cd140044096e', '九轉詩 三', '九轉诗 三', 'cfce85cb-390e-4b1b-878a-504bc538a1de', '唐', '["轉轉窮微妙，重重入杳杳。","由將藥砂體，却變水銀形。","炁合秋霜靜，朱光夜落星。","自然成姹女，何處不通靈。"]', '["轉轉窮微妙，重重入杳杳。","由將藥砂體，却变水銀形。","炁合秋霜静，朱光夜落星。","自然成姹女，何处不通靈。"]', '诗', 'shi', '', NULL, '九轉詩 三 竇真君 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e7c29e9a-304e-4e4c-b115-dc2e7285b24a', '九轉詩 四', '九轉诗 四', 'cfce85cb-390e-4b1b-878a-504bc538a1de', '唐', '["白錫雖初化，黃芽制已凝。","元如天降雪，映似結池水。","研土乾和炒，羅灰濕拌蒸。","仍須看炁色，更待鹵鹹澄。"]', '["白錫雖初化，黄芽制已凝。","元如天降雪，映似結池水。","研土乾和炒，羅灰濕拌蒸。","仍須看炁色，更待鹵鹹澄。"]', '诗', 'shi', '', NULL, '九轉詩 四 竇真君 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('04c25cfd-85a0-4b0d-a411-163e73d18315', '九轉詩 五', '九轉诗 五', 'cfce85cb-390e-4b1b-878a-504bc538a1de', '唐', '["文武長調火，陰陽鎮作鑪。","釜中看炁過，鍋裏定真虛。","炬石重鐐養，防非六藥塗。"]', '["文武长調火，陰陽鎮作鑪。","釜中看炁過，鍋裏定真虛。","炬石重鐐養，防非六藥塗。"]', '诗', 'shi', '', NULL, '九轉詩 五 竇真君 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('32a1c545-4d73-4dc6-b831-c4a6e9def28a', '九轉詩 六', '九轉诗 六', 'cfce85cb-390e-4b1b-878a-504bc538a1de', '唐', '["硝石臨湯沃，碙砂浸水煎。","鹹麤只是轉，礬細不須研。","舊白初凝硬，新黃色未堅。","欲將持入火，由怯水銀煙。"]', '["硝石臨湯沃，碙砂浸水煎。","鹹麤只是轉，礬細不須研。","旧白初凝硬，新黄色未堅。","欲將持入火，由怯水銀煙。"]', '诗', 'shi', '', NULL, '九轉詩 六 竇真君 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('befda2ea-ea8c-42c1-8143-75141dce2e4b', '九轉詩 七', '九轉诗 七', 'cfce85cb-390e-4b1b-878a-504bc538a1de', '唐', '["罷火開丹竃，成金去藥泥。","瑞光連明月，真氣雜虹蜺。","形勝參金鼎，精華向馬蹄。","由須九轉畢，看取一刀圭。"]', '["罷火开丹竃，成金去藥泥。","瑞光連明月，真氣杂虹蜺。","形勝參金鼎，精华向马蹄。","由須九轉畢，看取一刀圭。"]', '诗', 'shi', '', NULL, '九轉詩 七 竇真君 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2ae924fc-e62f-4b83-9d26-595b339f80e1', '九轉詩 八', '九轉诗 八', 'cfce85cb-390e-4b1b-878a-504bc538a1de', '唐', '["化粉初研鍊，臨鑪定否臧。","似塵驚半紫，如麵訝全黃。","瑞作三莖穗，靈含五色光。","待抽金毒盡，特獻玉階傍。"]', '["化粉初研鍊，臨鑪定否臧。","似塵驚半紫，如麵訝全黄。","瑞作三莖穗，靈含五色光。","待抽金毒尽，特獻玉階傍。"]', '诗', 'shi', '', NULL, '九轉詩 八 竇真君 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5a1f7dd0-592c-4269-8a04-22759949d4b8', '九轉詩 九', '九轉诗 九', 'cfce85cb-390e-4b1b-878a-504bc538a1de', '唐', '["玉律春初至，金丹帝感成。","南山同聖壽，東海比時清。","福是玄元德，功由至道呈。","小臣雖有術，仙士謝茅盈。","（《還丹詩訣》卷上。","原署「峨眉竇真人」，與真君應爲同一人。","）。"]', '["玉律春初至，金丹帝感成。","南山同聖壽，东海比时清。","福是玄元德，功由至道呈。","小臣雖有術，仙士謝茅盈。","（《還丹诗訣》卷上。","原署「峨眉竇真人」，與真君應爲同一人。","）。"]', '诗', 'shi', '', NULL, '九轉詩 九 竇真君 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8b78aca9-007f-468d-bf56-0830fb207627', '注葛仙公氣訣贈友人', '注葛仙公氣訣贈友人', 'efda6c27-c64c-45ee-b3ca-8302fe2b5169', '唐', '["君今遣我注仙經，我乃爲君強釋名。","華嶽峰前霞客喜，天台洞裏隱人驚。","雲翔嶂外緣文就，鶴唳天邊爲氣成。","奉勸仙公除自秘，莫教流俗浪相輕。","（見《四庫珍本初集》本《天台前集別編》。","）（按：詩題下原注：「見《洞天集》。","」《洞天集》爲五代後漢道士王貞範所纂，見《崇文總目》。","）。"]', '["君今遣我注仙經，我乃爲君強釋名。","华嶽峰前霞客喜，天台洞裏隐人驚。","云翔嶂外緣文就，鹤唳天邊爲氣成。","奉勸仙公除自秘，莫教流俗浪相轻。","（见《四庫珍本初集》本《天台前集別編》。","）（按：诗題下原注：「见《洞天集》。","」《洞天集》爲五代後漢道士王貞範所纂，见《崇文總目》。","）。"]', '诗', 'shi', '', NULL, '注葛仙公氣訣贈友人 逸人不顧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('27ea3e8b-96d5-4ef9-bc76-17996af0b54e', '芒鞵詩', '芒鞵诗', '2853a2be-6751-4cae-907a-6f6ecb911b3b', '唐', '["芸鞵織得甚堅牢，萬兩黃金價不高。","當時不聽妻兒語，跟我蓬萊走一遭。","（見《沅湘耆舊集》卷十四。","）。"]', '["芸鞵织得甚堅牢，万兩黄金價不高。","當时不听妻兒語，跟我蓬萊走一遭。","（见《沅湘耆旧集》卷十四。","）。"]', '诗', 'shi', '', NULL, '芒鞵詩 芒鞵道人 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b2220a7f-dbe6-4fce-aaf4-b290a5d9481d', '下鹿苑寺', '下鹿苑寺', 'ab5a8d06-225d-4eb5-aba8-b5d0081e694e', '唐', '["鹿苑重興梵宇寬，天台羅漢逐雲端。","雨花石上成砆坐，瀑布泉邊悟水觀。","四壁無鄰山鳥待，深巖有洞老猿看。","當時婺嶺龍回去，今日還歸護法壇。","（同治《嵊縣志》卷二十五。","此首承陶敏先生告。","）。"]', '["鹿苑重兴梵宇寬，天台羅漢逐云端。","雨花石上成砆坐，瀑布泉邊悟水观。","四壁無鄰山鸟待，深巖有洞老猿看。","當时婺嶺龙回去，今日還归護法壇。","（同治《嵊縣志》卷二十五。","此首承陶敏先生告。","）。"]', '诗', 'shi', '', NULL, '下鹿苑寺 大宗 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ed8dc10e-2076-4e94-8105-ba66320cf9ab', '大還丹口訣', '大還丹口訣', 'ce96407a-5c20-4fbf-bdd9-b5e1a0c63e9d', '唐', '["黃芽砂汞造，陰殻含陽花。","不得黃芽理，還丹應路賒。","世人煉至藥，盡認鉛黃花。","黃花是死物，那得到仙家。","黃芽非外藥，內象取精華。","若到黃芽地，金銀徒爾誇。"]', '["黄芽砂汞造，陰殻含陽花。","不得黄芽理，還丹應路賒。","世人煉至藥，尽認鉛黄花。","黄花是死物，那得到仙家。","黄芽非外藥，內象取精华。","若到黄芽地，金銀徒爾誇。"]', '诗', 'shi', '', NULL, '大還丹口訣 若訥 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e16d7c2e-6b5e-43fa-9c5c-b156d3a28c5e', '歌', '歌', 'ce96407a-5c20-4fbf-bdd9-b5e1a0c63e9d', '唐', '["芽若是鉛，去鉛萬里。","芽若非鉛，從鉛而始。","鉛爲芽母，芽爲鉛子。","既得金花，捨鉛不使。","（見《正統道藏》本後蜀人著《大還丹照鑑》。","）。"]', '["芽若是鉛，去鉛万里。","芽若非鉛，從鉛而始。","鉛爲芽母，芽爲鉛子。","既得金花，捨鉛不使。","（见《正統道藏》本後蜀人著《大還丹照鑑》。","）。"]', '诗', 'shi', '', NULL, '歌 若訥 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('69d6b017-14cc-4e69-a105-d5bd80f67f86', '山居 一', '山居 一', 'a3f05b70-e507-4776-be19-7b7ba3c0da9f', '唐', '["煙暖喬林啼鳥遠，日高方丈落花深。","積香櫉內新茶熟，輕汎松花滿碗金。"]', '["煙暖喬林啼鸟远，日高方丈落花深。","積香櫉內新茶熟，轻汎松花满碗金。"]', '诗', 'shi', '', NULL, '山居 一 法珍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4a3e6e7b-fad9-4be6-a6c3-11c40f5d57ca', '山居 二', '山居 二', 'a3f05b70-e507-4776-be19-7b7ba3c0da9f', '唐', '["風定泉花當澗響，雨餘山色入樓多。","老僧滅却心頭火，一榻松陰養太和。"]', '["风定泉花當澗响，雨餘山色入楼多。","老僧滅却心头火，一榻松陰養太和。"]', '诗', 'shi', '', NULL, '山居 二 法珍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('82ac89fd-d421-49c1-ba5f-07c6d0563347', '山居 三', '山居 三', 'a3f05b70-e507-4776-be19-7b7ba3c0da9f', '唐', '["清風拂處葉欲落，碧蘚堆時人不來。","滿院秋光濃欲滴，禪門閒向白雲開。"]', '["清风拂处葉欲落，碧蘚堆时人不来。","满院秋光濃欲滴，禪门閒向白云开。"]', '诗', 'shi', '', NULL, '山居 三 法珍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3efa1bb7-d660-404b-9114-79964a688896', '山居 四', '山居 四', 'a3f05b70-e507-4776-be19-7b7ba3c0da9f', '唐', '["梅花墻角開新歷，松樹枝頭曝衲衣。","怕冷老僧嫌朔吹，却教童子掩柴扉。","（均見《古今禪藻集》卷七。","）。"]', '["梅花墻角开新歷，松樹枝头曝衲衣。","怕冷老僧嫌朔吹，却教童子掩柴扉。","（均见《古今禪藻集》卷七。","）。"]', '诗', 'shi', '', NULL, '山居 四 法珍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1764b127-0c5d-454e-97d5-7f2063e8c039', '題寶相寺', '題寶相寺', '8f69c226-7d90-4b55-a45e-05ce6ef138ec', '唐', '["松徑行纔盡，香城絕世塵。","倚巖開半殿，鑿石見全身。","鐘鼓中天曉，煙花上界春。","出門重稽首，願值下生晨。","（見《會稽掇英總集》卷九。","《增廣聖宋高僧詩選後集》卷中作南越《石佛寺》詩。","）。"]', '["松徑行纔尽，香城絕世塵。","倚巖开半殿，鑿石见全身。","鐘鼓中天晓，煙花上界春。","出门重稽首，願值下生晨。","（见《會稽掇英總集》卷九。","《增廣聖宋高僧诗選後集》卷中作南越《石佛寺》诗。","）。"]', '诗', 'shi', '', NULL, '題寶相寺 南粤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8bbde3be-2f3c-4b89-8c3d-6b80dcc6f100', '春日題感上人山莊簡法友', '春日題感上人山莊簡法友', 'c60e25f0-390f-44fd-953c-e8d157ebb2d9', '唐', '["吾友幽棲地，今來藝黍南。","階生王子竹，庭結負山菴。","花葉裁新□，樵舟泊小潭。","相傳此爲勝，詩遲坐中探。","（日本藏唐抄本《新撰類林抄》卷四。","）。"]', '["吾友幽棲地，今来藝黍南。","階生王子竹，庭結負山菴。","花葉裁新□，樵舟泊小潭。","相傳此爲勝，诗遲坐中探。","（日本藏唐抄本《新撰類林抄》卷四。","）。"]', '诗', 'shi', '', NULL, '春日題感上人山莊簡法友 惠敏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('12c916cc-1d92-4f47-aeff-2ffaeec7d958', '鄰霄臺', '鄰霄台', 'ac547492-1832-4e15-8c48-15220b916497', '唐', '["平臺屹峰巔，去天不盈尺。","雲來隱巉巖，雲散露形跡。","長嘯視大荒，煩襟盡冰釋。","不知身世遠，但覺乾坤窄。","一勺滄浪浮，萬家煙樹隔。","解衣恣盤礴，謝我山水癖。","極目送斜暉，寥寥海天碧。","（見影印文淵閣《四庫全書》本《福建通志》卷七六。","）。"]', '["平台屹峰巔，去天不盈尺。","云来隐巉巖，云散露形跡。","长嘯視大荒，煩襟尽冰釋。","不知身世远，但覺乾坤窄。","一勺滄浪浮，万家煙樹隔。","解衣恣盤礴，謝我山水癖。","極目送斜暉，寥寥海天碧。","（见影印文淵閣《四庫全书》本《福建通志》卷七六。","）。"]', '诗', 'shi', '', NULL, '鄰霄臺 惠顗 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dd9f3a93-d4f1-476f-9847-113d0736ab4b', '鶴詩', '鹤诗', '6b1db4dc-96e4-4def-b30c-019343b9b4af', '唐', '["紅塵無繫澤（《詩學指南》本作「縛」），碧落自翱翔。","（見《吟窗雜錄》卷十四正字王玄《詩中旨格》。","）。"]', '["紅塵無繫澤（《诗学指南》本作「縛」），碧落自翱翔。","（见《吟窗杂錄》卷十四正字王玄《诗中旨格》。","）。"]', '诗', 'shi', '', NULL, '鶴詩 僧可 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8108c037-9f24-49e9-b7c6-c9c680ab2fd7', '題羅霄洞', '題羅霄洞', '78aab423-12f2-4bbf-955b-c6cc75c55b55', '唐', '["江南二月共無邊，谿行十里花爭妍。","兒童且莫吹羌笛，我欲臨流枕石眠。","（見《古今禪藻集》卷七。","）。"]', '["江南二月共無邊，谿行十里花爭妍。","兒童且莫吹羌笛，我欲臨流枕石眠。","（见《古今禪藻集》卷七。","）。"]', '诗', 'shi', '', NULL, '題羅霄洞 德最 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('20f07035-c2cc-44b3-b176-f2fb76774fbf', '遊雲門寺之一', '游云门寺之一', 'b7eb5222-4bfb-45ac-96b2-061befeff3e8', '唐', '["晉代雲門寺，尋常豈易名。","難關千嶠色，不鎻亂泉聲。","樹石煙中老，香鐙雪後清。","伊余來扣寂，猨鳥共忘情。","（同前書卷四。","）（按：《遊雲門寺》二首，其二已收《全唐詩續補遺》卷二十。","）。"]', '["晉代云门寺，尋常豈易名。","难关千嶠色，不鎻亂泉声。","樹石煙中老，香鐙雪後清。","伊余来扣寂，猨鸟共忘情。","（同前书卷四。","）（按：《游云门寺》二首，其二已收《全唐诗續補遺》卷二十。","）。"]', '诗', 'shi', '', NULL, '遊雲門寺之一 德圓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5ed82e3a-4748-491a-be78-3625d0f50b58', '悟道頌', '悟道頌', 'c9eefca8-5243-49f6-8877-560482b80f44', '唐', '["普光初學道，無邊世界動。","迴天復轉地，併入一毛孔。","（見《宗鏡錄》卷一○○。","）。"]', '["普光初学道，無邊世界动。","迴天复轉地，併入一毛孔。","（见《宗镜錄》卷一○○。","）。"]', '诗', 'shi', '', NULL, '悟道頌 慧集法師 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('400482b2-f2b5-47c4-8bde-02089b22d80b', '敬贈張晧兄', '敬贈張晧兄', '8c5bdd1c-e2dc-4231-9ee2-6a445a45c0f7', '唐', '["昔我背准時，淄庭叨筮仕。","及君飛蓋夕，梁墀擅詩史。","聯文日華上，接絢陽臺裏（此字原殘）。","東閣奉賓遊，西園追宴喜。","謬此梁松筠，相彼歷冬春。","連璧交逾密，斷金情更親。","林中浮淥蟣，濠際躍頳鱗。","自然知管鮑，寧止挹雷陳。","歡娛樂相樂，放曠尋巖壑。","原野縈心神，琴罇諧賞託。","蕭深（周改爲「森」）對風景，顧歩披花藥。","煙霞牙{丿爲丶}縈暎，蔦蘿紛苒弱。","淹留窮[眺]（晀）翫，麗藻方輝煥。","逸唱子爲輕，課拙余成憚。","聯翩限從[役]（伇），雲雨俄分散。","各下澘然淚，共切離羣歡。","長望關河阻，結思徒延佇。","春鶯啼故林，秋鴈誼幽渚。","空悲結霜霰，無由欣晤語。","時閱贈離章，持用寬羈緒。","上善冠前良，弈葉播餘芳。","丹[穴]（宄）摛鸞[鳳]（〖風〗從周校改），玄岫吐珪璋。","墻仞攸倫孔，陂澄固偶黃。","司文踐蓬閣，刊冊染芸香。","咸揖銅墨才，寔資瑚璉器。","簡牘聞尚父，灌壇初歷試。","誰當嗣往哲？君子紹斯位。","感神既不殊，非熊寧有異。","非熊在渭川，佐聖佇光先。","語德雖云類，比迹詎同年？","琱蟲開製錦，乳翟應鳴絃。","何止高無二，終期掩半千。","自揣無庸質，濫爾承朝顧。","本之三（疑當作「王」）生能，遂踐龐公路。","望古承清白，脩今恧尸素。","何以嗣餘基？履冰期歲暮。","索居睽宴語，每恨離筵促。","下車忽相遇，適願於斯足。","言志悅披沙，放情欣倚玉。","豈唯忘鄭恡，復此陳心曲。","重敘舊嬉遊，芳巵幾獻酬。","蟬吟催晚夏，鴻響應新秋。","風氣清幽谷，雲陰澹淺流。","寫懷憑動際，長歌遣四愁。"]', '["昔我背准时，淄庭叨筮仕。","及君飞蓋夕，梁墀擅诗史。","聯文日华上，接絢陽台裏（此字原殘）。","东閣奉賓游，西园追宴喜。","謬此梁松筠，相彼歷冬春。","連璧交逾密，斷金情更親。","林中浮淥蟣，濠際躍頳鱗。","自然知管鲍，寧止挹雷陳。","歡娛乐相乐，放曠尋巖壑。","原野縈心神，琴罇諧賞託。","蕭深（周改爲「森」）对风景，顧歩披花藥。","煙霞牙{丿爲丶}縈暎，蔦蘿紛苒弱。","淹留窮[眺]（晀）翫，丽藻方輝煥。","逸唱子爲轻，課拙余成憚。","聯翩限從[役]（伇），云雨俄分散。","各下澘然泪，共切離羣歡。","长望关河阻，結思徒延佇。","春鶯啼故林，秋鴈誼幽渚。","空悲結霜霰，無由欣晤語。","时閱贈離章，持用寬羈緒。","上善冠前良，弈葉播餘芳。","丹[穴]（宄）摛鸾[鳳]（〖风〗從周校改），玄岫吐珪璋。","墻仞攸倫孔，陂澄固偶黄。","司文踐蓬閣，刊冊染芸香。","咸揖銅墨才，寔資瑚璉器。","簡牘闻尚父，灌壇初歷試。","誰當嗣往哲？君子紹斯位。","感神既不殊，非熊寧有異。","非熊在渭川，佐聖佇光先。","語德雖云類，比迹詎同年？","琱蟲开製錦，乳翟應鳴絃。","何止高無二，終期掩半千。","自揣無庸質，濫爾承朝顧。","本之三（疑當作「王」）生能，遂踐龐公路。","望古承清白，脩今恧尸素。","何以嗣餘基？履冰期歲暮。","索居睽宴語，每恨離筵促。","下车忽相遇，適願於斯足。","言志悅披沙，放情欣倚玉。","豈唯忘鄭恡，复此陳心曲。","重敘旧嬉游，芳巵幾獻酬。","蟬吟催晚夏，鴻响應新秋。","风氣清幽谷，云陰澹淺流。","寫懷憑动際，长歌遣四愁。"]', '诗', 'shi', '', NULL, '敬贈張晧兄 趙志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('baeaf4fe-304f-42b4-809e-5fe9f7c15534', '奉酬劉長史', '奉酬劉长史', '8c5bdd1c-e2dc-4231-9ee2-6a445a45c0f7', '唐', '["晉嶺高無極，汾川清且濬。","誕粹表前脩，資靈光後胤。","澄陂溢萬頃，斷山聳千仞。","淬水曜金芒，陵寒標玉潤。","勵精悅緗素，抗志敦風雅。","書帳燭流螢，辨囿馳非馬。","發藻春葩落，揮毫秋露下。","寧止冠揚班，方見超終賈。","巨鱗初撃浪，迅翮始搏空。","梁園奉脩竹，楚館仰雄風。","才傾《大言賦》，芳溢小山叢。","曳裾參上客，懸藉偶□（此字已無從辨認，周補爲「羣」字）公。","無庸慙薄伎，多幸陪高躅。","接景猨巖陰，追飛鳥渚曲。","交態君無□，□□（二字僅存殘迹）遂自酌。","共悅忘是非，俱欣齊榮辱。","碣石秋風日，長洲麗景時。","名山多爽氣，奇樹有華滋。","絃琴恒共賞，酌□□同嬉。","披襟窮雅論，握管賦新詩。","擾擾勞形役。","棲棲倦時綱。","歡娛不再來，光陰誠易往。","遽嗟雲雨別，行睽風月[□]。","搔首悵勞歌，霑纓獨長想。","宏才惟不噐，出處□多迥。","玉堦表令詞，銅章宣美續。","漁人釋夜綱，孺子𩾧朝翟。","寬刑獄犴虛，富教田疇闢。","鳴峻本周壤，祠仕（此字僅可見下半截）寔秦京。","大藩資變贊，上德荷恩榮。","題輿昭令範，展驥聞喜聲。","惠化移甿俗，仁風被屬誠。","顧惟策蹇姿，還傷雕朽質。","及斯牽墨綬，[□]往謝鉛筆。","方申捧檄心，聊安代耕袟。","問松寧有裕，求轄終無術。","謬兹叨下邑，濫喜永嘉惠。","依仁道不騫，惟舊情無替。","復此論襟抱，於烏追賞栔。","投贈重千金，披文高五際。","文酒重留連，高宴促芳筵。","秋灰移玉管，夏火度金天。","□送銜蘆鴈，風吹醫葉蟬。","徒欣接素賞，空恧繼華篇。","。"]', '["晉嶺高無極，汾川清且濬。","誕粹表前脩，資靈光後胤。","澄陂溢万頃，斷山聳千仞。","淬水曜金芒，陵寒標玉潤。","勵精悅緗素，抗志敦风雅。","书帳燭流螢，辨囿驰非马。","發藻春葩落，揮毫秋露下。","寧止冠揚班，方见超終賈。","巨鱗初撃浪，迅翮始搏空。","梁园奉脩竹，楚館仰雄风。","才傾《大言賦》，芳溢小山叢。","曳裾參上客，懸藉偶□（此字已無從辨認，周補爲「羣」字）公。","無庸慙薄伎，多幸陪高躅。","接景猨巖陰，追飞鸟渚曲。","交態君無□，□□（二字僅存殘迹）遂自酌。","共悅忘是非，俱欣齊榮辱。","碣石秋风日，长洲丽景时。","名山多爽氣，奇樹有华滋。","絃琴恒共賞，酌□□同嬉。","披襟窮雅論，握管賦新诗。","擾擾勞形役。","棲棲倦时綱。","歡娛不再来，光陰誠易往。","遽嗟云雨別，行睽风月[□]。","搔首悵勞歌，霑纓独长想。","宏才惟不噐，出处□多迥。","玉堦表令词，銅章宣美續。","漁人釋夜綱，孺子𩾧朝翟。","寬刑獄犴虛，富教田疇闢。","鳴峻本周壤，祠仕（此字僅可见下半截）寔秦京。","大藩資变贊，上德荷恩榮。","題輿昭令範，展驥闻喜声。","惠化移甿俗，仁风被屬誠。","顧惟策蹇姿，還傷雕朽質。","及斯牽墨綬，[□]往謝鉛笔。","方申捧檄心，聊安代耕袟。","问松寧有裕，求轄終無術。","謬兹叨下邑，濫喜永嘉惠。","依仁道不騫，惟旧情無替。","复此論襟抱，於烏追賞栔。","投贈重千金，披文高五際。","文酒重留連，高宴促芳筵。","秋灰移玉管，夏火度金天。","□送銜蘆鴈，风吹醫葉蟬。","徒欣接素賞，空恧繼华篇。","。"]', '诗', 'shi', '', NULL, '奉酬劉長史 趙志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('53fab5e4-3311-45b8-9c5c-1c007857143c', '秋日在縣望雨仰贈鄭司馬', '秋日在縣望雨仰贈鄭司马', '8c5bdd1c-e2dc-4231-9ee2-6a445a45c0f7', '唐', '["陰雲凝素序，涼雨散秋旻。","望山疑擁霧，[瞻]（贍）野若飄塵。","始飛鳴鳳嶺，還灑飲龍津。","宿草霑逾潤，寒花濯更新。","色黯虛庭夕，聲喧危砌晨。","索居勞望美，離思切依仁。","徒懷[伐]（〖代〗從周改）木唱，獨斂向隅嚬。","方慚灌壇術，空慕潁川巾。"]', '["陰云凝素序，涼雨散秋旻。","望山疑擁霧，[瞻]（贍）野若飄塵。","始飞鳴鳳嶺，還灑饮龙津。","宿草霑逾潤，寒花濯更新。","色黯虛庭夕，声喧危砌晨。","索居勞望美，離思切依仁。","徒懷[伐]（〖代〗從周改）木唱，独斂向隅嚬。","方慚灌壇術，空慕潁川巾。"]', '诗', 'shi', '', NULL, '秋日在縣望雨仰贈鄭司馬 趙志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('43ca8d01-8123-4961-bcc8-6bdaadafb861', '仰酬鄭司馬兄秋日望雨見贈之作', '仰酬鄭司马兄秋日望雨见贈之作', '8c5bdd1c-e2dc-4231-9ee2-6a445a45c0f7', '唐', '["感秋嗟旅思，懷友愴離居。","閑[齋]（齊）倦寂靜，望美空躊躇。","浮雲低峻堞，飛雨散遙墟。","似霧縈丹阜，疑塵颺紫虛。","既汎文通𮞒，還拂子思廬。","別有陶元亮，紛然雅翰攄。","鏗鏘韻金石，輝煥藻璠璵。","欣覿安仁錦，空望景山車。"]', '["感秋嗟旅思，懷友愴離居。","闲[斋]（齊）倦寂静，望美空躊躇。","浮云低峻堞，飞雨散遙墟。","似霧縈丹阜，疑塵颺紫虛。","既汎文通𮞒，還拂子思廬。","別有陶元亮，紛然雅翰攄。","鏗鏘韻金石，輝煥藻璠璵。","欣覿安仁錦，空望景山车。"]', '诗', 'shi', '', NULL, '仰酬鄭司馬兄秋日望雨見贈之作 趙志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('68e80f8c-9d31-4235-9dee-d5418b5b4b5e', '秋晚感時寄裴草然', '秋晚感时寄裴草然', '8c5bdd1c-e2dc-4231-9ee2-6a445a45c0f7', '唐', '["蘭凋夏盡，菊荗秋深。","驚□飋䫻，寒木蕭森。","天高月淨，鳥思蟲吟。","感時懷友，望美霑襟。","情唯丘壑，志在山林。","從兹釋綱，謝病抽簪。","眷言鮑叔，知余此心。"]', '["蘭凋夏尽，菊荗秋深。","驚□飋䫻，寒木蕭森。","天高月淨，鸟思蟲吟。","感时懷友，望美霑襟。","情唯丘壑，志在山林。","從兹釋綱，謝病抽簪。","眷言鲍叔，知余此心。"]', '诗', 'shi', '', NULL, '秋晚感時寄裴草然 趙志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a7531c74-9575-45c1-956c-5366c89c5507', '奉酬裴草然秋晚感見貽之製', '奉酬裴草然秋晚感见貽之製', '8c5bdd1c-e2dc-4231-9ee2-6a445a45c0f7', '唐', '["景澄旻寓，氣從寒葭。","林驚風葉，菊照霜花。","爰有吉士，感物興嗟。","馳魂巖壑，締想煙霞。","展兹逸驥，握此靈虵。","式存匪石，言降披沙。","顧慙璧友，空戢瑤華。"]', '["景澄旻寓，氣從寒葭。","林驚风葉，菊照霜花。","爰有吉士，感物兴嗟。","驰魂巖壑，締想煙霞。","展兹逸驥，握此靈虵。","式存匪石，言降披沙。","顧慙璧友，空戢瑤华。"]', '诗', 'shi', '', NULL, '奉酬裴草然秋晚感見貽之製 趙志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c3a117eb-3b3c-46ec-ad19-c8960d3d1375', '敬和裴草然秋晚感時寄張結之作', '敬和裴草然秋晚感时寄張結之作', '8c5bdd1c-e2dc-4231-9ee2-6a445a45c0f7', '唐', '["朱明從律，白藏御時，草腓寒露，木落涼颸。","有斐君子，感物陳詩。","義深潘興，詞均宋悲。","方追逸跡，乃論心期。","粵惟不敏，濫吹連司。","庶陪高躅，共採靈芝。","（按：疑張結、張晧爲一人而抄訛爲二人。","）。"]', '["朱明從律，白藏御时，草腓寒露，木落涼颸。","有斐君子，感物陳诗。","義深潘兴，词均宋悲。","方追逸跡，乃論心期。","粵惟不敏，濫吹連司。","庶陪高躅，共採靈芝。","（按：疑張結、張晧爲一人而抄訛爲二人。","）。"]', '诗', 'shi', '', NULL, '敬和裴草然秋晚感時寄張結之作 趙志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('753d5211-8bff-4086-bcf5-ad5e139cad10', '閑廳晚景敬呈徐長史', '闲廳晚景敬呈徐长史', '8c5bdd1c-e2dc-4231-9ee2-6a445a45c0f7', '唐', '["落日下桒榆，暝煙起林薄。","砌閑來狎鳥，簷空多噪雀。","旅思獨棲遑，心事兩睽索。","寂寞無興晤，徘徊何託。"]', '["落日下桒榆，暝煙起林薄。","砌闲来狎鸟，簷空多噪雀。","旅思独棲遑，心事兩睽索。","寂寞無兴晤，徘徊何託。"]', '诗', 'shi', '', NULL, '閑廳晚景敬呈徐長史 趙志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f6f38752-af9e-43dc-9fe2-9bdd498b2da3', '敬和徐司馬閑廳晚景之贈', '敬和徐司马闲廳晚景之贈', '8c5bdd1c-e2dc-4231-9ee2-6a445a45c0f7', '唐', '["俄景曖餘暉，寒村歸棲翼。","吏休案牘斂，庭閑誼訟息。","顧脩杇鈍姿，多慙弼諧力。","不能庶知止，方歸事耕植。"]', '["俄景曖餘暉，寒村归棲翼。","吏休案牘斂，庭闲誼訟息。","顧脩杇鈍姿，多慙弼諧力。","不能庶知止，方归事耕植。"]', '诗', 'shi', '', NULL, '敬和徐司馬閑廳晚景之贈 趙志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a1c93ee2-b1a1-4bf5-a777-ad4ba430d7fc', '奉和閑廳晚景司戶薩照', '奉和闲廳晚景司戶薩照', '8c5bdd1c-e2dc-4231-9ee2-6a445a45c0f7', '唐', '["薄晚閑無事，澹然休簡牘，寥寥館宇虛，苒苒寒光速。","輕霜遍衰草，高風斷羣木。","別有滄[洲]（州）人，棲遑也干祿。","（均見日本《無理圖書館善本叢書》漢籍之部二影印古抄本《趙志集》。","）（〖1〗《趙志集》末附花房英樹《解題》謂《趙志集》一卷，卷首第一行題「趙志集一卷」，下小字注：「十七張。","」實存六張。","第二首與第三首〖引者注：以下只稱第某首，不錄詩題，以省篇幅〗之間有缺脫，第十首以後缺。","）（〖2〗關於諸詩作者，花房英樹認爲：「然十首非皆趙志之作。","第十首即署爲『司戶薩照』。","蓋其始趙志作第八首呈徐長史，應此徐長史即徐司馬有酬詩至，趙志乃更作第九首和之，而同時司戶薩照亦有鬼徐司馬之作。","古人於己集中附載他人酬和之，是常見的，又此前各篇，第五首題中『裴草然』上空一格，恐非表明裴草然而爲詩作者，由裴寄趙志。","空格當係趙志對裴草然之表敬形式，詩爲趙志寄裴。","第六首，爲裴草然有詩答雲貴高原志後，趙志復作酬篇。","第七篇，裴草然以答趙志之詩並寄張結，趙志另作和篇，亦寄張結。","由是觀之則悉爲寄贈酬鬼之作。","」〖3〗關於諸詩產生的時代，花房英樹認爲當在唐初。","主要證據是：各篇修辭頗爲洗練，風格近乎《文選》。","如第一首「聯文日華上」以下四句，可謂《文選》體措辭。","如第二首以「秋灰」、「夏火」爲對即是。","在盧照鄰、劉允濟詩中始見此二語。","以二語相對應使用，則見於駱賓王《初秋登王司馬樓宴序》。","同篇以「題輿」、「展驥」爲對語，始見於陳子昂《爲鄭資州讓官表》。","另外可認爲諸篇爲入唐所作的證據有四：一、第二首聯云：「晉嶺高無極，汾川清且濬。","」「晉嶺」、「汾川」非南朝地，而「晉山」、「汾水」廣見於唐代詩文。","二、第一首云：「非熊在渭川」，語出《史記·齊太公世家》：「所獲非龍非彲，非虎非羆。","」「非熊」代「非虎」，與避唐諱有關。","三、第十首作者「司戶薩照」，「司戶」應爲官名。","司戶一職隋文帝時曾置，旋廢。","據《舊唐書》載，在腐曰戶曹參軍，在州曰司戶參軍，在縣曰司戶。","薩照係州縣官員，故此「司戶」爲唐代官職。","四、集中有三篇四言詩。","自六朝至隋，除郊廟歌辭外，四言詩未見廣泛運用於一般主題。","至唐初，始有王勃《倬彼我系》及崔知賢、陳子昂等六人《三月三日宴王明府山亭》的寫作。","《趙志集》中的三首四言詩，似乎可以認爲是對陳子昂等人寫作四言詩活動極爲關心的結果。","因此諸詩之寫作時代，當在六朝文學風氣衰今明兩年之前，律詩意識尚未確立之際，很可能在初唐末期。","〖4〗關於作者的身份，花房英樹認爲：司戶薩照是州縣的屬官，雲貴高原志也應是地方官。","詩中可得到證明。","如第三首題言「在縣」，詩中說到「方慚灌壇術」。","第一首亦云：「謬茲叨下邑」，可以參證。","他對上級，本州的劉長史、鄭司馬極其鄭重地冠以敬、奉、仰等文字，亦與其身份相合。","趙志等所在的州縣，可能在京師的北面。","十首所詠都是秋景，其中「寒樹」、「寒光」、「寒露」、「寒葭」、「寒木」之類辭匯再三出現。","北地的地名也時有所見，如前面提及的「晉嶺」、「汾川」等。","作爲一種意見，可以這樣認爲：《趙志集》的作者，是初唐末期、京師北面某地的縣令趙志。","今存的十首詩，是以趙志爲主的寄贈酬和之作。","〖5〗花房英樹還對鈔本的年代作了推測。","他認爲，這本書於唐代中期傳入日本。","現在所見，是其轉鈔本的一軸。","其中有不少別字，恐怕是因襲原鈔的，作爲表敬的書寫形式，也應該是唐代原鈔的舊貌。","其書法可斷定爲日本的古書法。","從避唐諱、保存空格及書寫格式來推測，這個鈔本當是平安中期以前之物，至少不遲於背紙所抄《唯識章》所注明的「長元參年」〖一○三○〗。","〖駱玉明摘譯〗〖6〗《藝文志》第一輯刊周紹良《〈趙志集〉跋》云：「日本漢學家都認爲這是『趙志』的詩集，是他的作品。","實際這是值得商榷的。","仔細審查此十首詩中，至多可能只有趙志詩三首，甚或此詩集只是趙志抄錄者，內中連他的作品一首也沒有，也屬可能。","現在根據卷中他標詩題，我們可以知道，第一首《敬贈》是張皓給劉長史者，其詩題應作《敬贈劉長史》，蓋其題下『張皓兄』三字力抄錄者所記作者姓名，由於同屬友人，因加『兄』字。","其第二首當是劉長史和章，詩題應作《奉酬張皓兄》，其『劉長史』三字乃抄錄者所標識。","第三首是鄭司馬所作，詩題應是《秋日在縣望雨仰贈□□□》，『鄭司馬』三字亦抄錄者所記。","第四首是鄭司馬仰酬之作〖引者按：此句似應爲『是仰酬鄭司馬之作』〗，如果鄭司馬所贈之人即趙志，則此首即趙志之作，否則當另有其人，而是由趙志抄錄者。","不過有一點可以知道，作此詩者其地位應視司馬爲高，所以原題用『仰贈』，而此詩則以禮貌答之作『仰酬』也。","第五首詩題應作《秋晚感時寄張結》，而作者乃『裴草然』。","第六首則是張結奉酬裴草然之作。","第七首或者是趙志之作，但也可能爲他人所作而由趙志錄之於此者？","第八首詩題應是《閑庭晚景敬呈□□□》，題下所署『徐長區亦作者官職與姓也。","第九首爲被贈詩者和章，其人或即趙志，亦無法確指。","第十首則爲司戶蘇然之作。","從整個十首詩的詩題與內容總起來看，它與卷題《趙志集》之名是不相符的，因其中明顯大部非趙志作品。","但此書何以題作《趙志集》？實爲不解。","」今按：以上二家對諸詩作者的考證，均持之有故，言之成理可各成一說，但均不足以論定。","除第十首二家均斷定）（爲「司戶薩照」〖周紹良錄作「蘇照」、「蘇然」，皆誤〗之作外，其餘九首尚難遽定歸屬。","爲慎重起見，今仍以「趙志集」列目各詩詩題及次第仍照原卷面貌編排，以便進一歩研究。","）。"]', '["薄晚闲無事，澹然休簡牘，寥寥館宇虛，苒苒寒光速。","轻霜遍衰草，高风斷羣木。","別有滄[洲]（州）人，棲遑也干祿。","（均见日本《無理圖书館善本叢书》漢籍之部二影印古抄本《趙志集》。","）（〖1〗《趙志集》末附花房英樹《解題》謂《趙志集》一卷，卷首第一行題「趙志集一卷」，下小字注：「十七張。","」實存六張。","第二首與第三首〖引者注：以下只稱第某首，不錄诗題，以省篇幅〗之间有缺脫，第十首以後缺。","）（〖2〗关於諸诗作者，花房英樹認爲：「然十首非皆趙志之作。","第十首即署爲『司戶薩照』。","蓋其始趙志作第八首呈徐长史，應此徐长史即徐司马有酬诗至，趙志乃更作第九首和之，而同时司戶薩照亦有鬼徐司马之作。","古人於己集中附載他人酬和之，是常见的，又此前各篇，第五首題中『裴草然』上空一格，恐非表明裴草然而爲诗作者，由裴寄趙志。","空格當係趙志对裴草然之表敬形式，诗爲趙志寄裴。","第六首，爲裴草然有诗答云貴高原志後，趙志复作酬篇。","第七篇，裴草然以答趙志之诗並寄張結，趙志另作和篇，亦寄張結。","由是观之則悉爲寄贈酬鬼之作。","」〖3〗关於諸诗產生的时代，花房英樹認爲當在唐初。","主要證據是：各篇修辞頗爲洗練，风格近乎《文選》。","如第一首「聯文日华上」以下四句，可謂《文選》體措辞。","如第二首以「秋灰」、「夏火」爲对即是。","在盧照鄰、劉允濟诗中始见此二語。","以二語相对應使用，則见於駱賓王《初秋登王司马楼宴序》。","同篇以「題輿」、「展驥」爲对語，始见於陳子昂《爲鄭資州讓官表》。","另外可認爲諸篇爲入唐所作的證據有四：一、第二首聯云：「晉嶺高無極，汾川清且濬。","」「晉嶺」、「汾川」非南朝地，而「晉山」、「汾水」廣见於唐代诗文。","二、第一首云：「非熊在渭川」，語出《史記·齊太公世家》：「所獲非龙非彲，非虎非羆。","」「非熊」代「非虎」，與避唐諱有关。","三、第十首作者「司戶薩照」，「司戶」應爲官名。","司戶一職隋文帝时曾置，旋廢。","據《旧唐书》載，在腐曰戶曹參軍，在州曰司戶參軍，在縣曰司戶。","薩照係州縣官員，故此「司戶」爲唐代官職。","四、集中有三篇四言诗。","自六朝至隋，除郊廟歌辞外，四言诗未见廣泛運用於一般主題。","至唐初，始有王勃《倬彼我系》及崔知賢、陳子昂等六人《三月三日宴王明府山亭》的寫作。","《趙志集》中的三首四言诗，似乎可以認爲是对陳子昂等人寫作四言诗活动極爲关心的結果。","因此諸诗之寫作时代，當在六朝文学风氣衰今明兩年之前，律诗意識尚未確立之際，很可能在初唐末期。","〖4〗关於作者的身份，花房英樹認爲：司戶薩照是州縣的屬官，云貴高原志也應是地方官。","诗中可得到證明。","如第三首題言「在縣」，诗中说到「方慚灌壇術」。","第一首亦云：「謬茲叨下邑」，可以參證。","他对上級，本州的劉长史、鄭司马極其鄭重地冠以敬、奉、仰等文字，亦與其身份相合。","趙志等所在的州縣，可能在京師的北面。","十首所詠都是秋景，其中「寒樹」、「寒光」、「寒露」、「寒葭」、「寒木」之類辞匯再三出現。","北地的地名也时有所见，如前面提及的「晉嶺」、「汾川」等。","作爲一種意见，可以這樣認爲：《趙志集》的作者，是初唐末期、京師北面某地的縣令趙志。","今存的十首诗，是以趙志爲主的寄贈酬和之作。","〖5〗花房英樹還对鈔本的年代作了推測。","他認爲，這本书於唐代中期傳入日本。","現在所见，是其轉鈔本的一軸。","其中有不少別字，恐怕是因襲原鈔的，作爲表敬的书寫形式，也應該是唐代原鈔的旧貌。","其书法可斷定爲日本的古书法。","從避唐諱、保存空格及书寫格式来推測，這個鈔本當是平安中期以前之物，至少不遲於背紙所抄《唯識章》所注明的「长元參年」〖一○三○〗。","〖駱玉明摘譯〗〖6〗《藝文志》第一輯刊周紹良《〈趙志集〉跋》云：「日本漢学家都認爲這是『趙志』的诗集，是他的作品。","實際這是值得商榷的。","仔細審查此十首诗中，至多可能只有趙志诗三首，甚或此诗集只是趙志抄錄者，內中連他的作品一首也沒有，也屬可能。","現在根據卷中他標诗題，我們可以知道，第一首《敬贈》是張皓給劉长史者，其诗題應作《敬贈劉长史》，蓋其題下『張皓兄』三字力抄錄者所記作者姓名，由於同屬友人，因加『兄』字。","其第二首當是劉长史和章，诗題應作《奉酬張皓兄》，其『劉长史』三字乃抄錄者所標識。","第三首是鄭司马所作，诗題應是《秋日在縣望雨仰贈□□□》，『鄭司马』三字亦抄錄者所記。","第四首是鄭司马仰酬之作〖引者按：此句似應爲『是仰酬鄭司马之作』〗，如果鄭司马所贈之人即趙志，則此首即趙志之作，否則當另有其人，而是由趙志抄錄者。","不過有一点可以知道，作此诗者其地位應視司马爲高，所以原題用『仰贈』，而此诗則以禮貌答之作『仰酬』也。","第五首诗題應作《秋晚感时寄張結》，而作者乃『裴草然』。","第六首則是張結奉酬裴草然之作。","第七首或者是趙志之作，但也可能爲他人所作而由趙志錄之於此者？","第八首诗題應是《闲庭晚景敬呈□□□》，題下所署『徐长區亦作者官職與姓也。","第九首爲被贈诗者和章，其人或即趙志，亦無法確指。","第十首則爲司戶蘇然之作。","從整個十首诗的诗題與內容總起来看，它與卷題《趙志集》之名是不相符的，因其中明显大部非趙志作品。","但此书何以題作《趙志集》？實爲不解。","」今按：以上二家对諸诗作者的考證，均持之有故，言之成理可各成一说，但均不足以論定。","除第十首二家均斷定）（爲「司戶薩照」〖周紹良錄作「蘇照」、「蘇然」，皆誤〗之作外，其餘九首尚难遽定归屬。","爲慎重起见，今仍以「趙志集」列目各诗诗題及次第仍照原卷面貌編排，以便進一歩研究。","）。"]', '诗', 'shi', '', NULL, '奉和閑廳晚景司戶薩照 趙志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('50b663c9-ff20-4def-9f68-2f5a457c47f5', '青峰詩', '青峰诗', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["野人不相識，偶坐爲林泉。","莫漫愁沽酒，囊中自有錢。","迴瞻林下路，已在翠微間。","時見雲林外，青峰一點圓。","（見宋岳珂《寶真齋法書贊》卷八。","）（按：原帖爲草書八行。","詩末有云：「近見崔法曹此詩，愛之不覺下筆也。","」岳珂跋云：「右唐無名人青峰詩帖真跡一卷。","帖亦與《奉禮》、《不倦》二帖相似，意皆出於習書之勤者，有小璽表焉。","」同卷跋《奉禮帖》，謂有貞觀初年風度。","）。"]', '["野人不相識，偶坐爲林泉。","莫漫愁沽酒，囊中自有錢。","迴瞻林下路，已在翠微间。","时见云林外，青峰一点圓。","（见宋岳珂《寶真斋法书贊》卷八。","）（按：原帖爲草书八行。","诗末有云：「近见崔法曹此诗，愛之不覺下笔也。","」岳珂跋云：「右唐無名人青峰诗帖真跡一卷。","帖亦與《奉禮》、《不倦》二帖相似，意皆出於習书之勤者，有小璽表焉。","」同卷跋《奉禮帖》，謂有貞观初年风度。","）。"]', '诗', 'shi', '', NULL, '青峰詩 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a979ff55-4703-4568-bd60-40f3ed307d44', '詩', '诗', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["時人有酒送張八，惟我無酒送張八。","君有（疑當作「看」）陌上梅花紅，盡是離人眼中血。","（見《艇齋詩話》。","）（按：《螢雪叢書》卷下收杜甫二句云：「君看墻頭桃樹花，盡是行人眼中血。","」《全唐詩續補遺》卷四收入。","二句即出自本詩後二句。","《螢雪叢說》錯舛甚多，《四庫總目提要》已指出。","若即依其說定此了杜甫佚詩，證據尚不足。","今仍收歸無名氏。","另《全唐詩》卷三○九收李約《贈韋況》有「明月照張八」句，《唐詩紀事》卷三一謂張八爲張諗。","疑與本詩中張八爲一人。","）。"]', '["时人有酒送張八，惟我無酒送張八。","君有（疑當作「看」）陌上梅花紅，尽是離人眼中血。","（见《艇斋诗話》。","）（按：《螢雪叢书》卷下收杜甫二句云：「君看墻头桃樹花，尽是行人眼中血。","」《全唐诗續補遺》卷四收入。","二句即出自本诗後二句。","《螢雪叢说》錯舛甚多，《四庫總目提要》已指出。","若即依其说定此了杜甫佚诗，證據尚不足。","今仍收归無名氏。","另《全唐诗》卷三○九收李約《贈韋況》有「明月照張八」句，《唐诗紀事》卷三一謂張八爲張諗。","疑與本诗中張八爲一人。","）。"]', '诗', 'shi', '', NULL, '詩 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bc7dcf4a-db5f-4bd2-a06e-cbfab804dfec', '泉月之歌', '泉月之歌', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["月照泉兮泉涵月，泉潺湲兮月皎潔。","波無魚兮清澄，月有蟾兮澄澈。","（見《文苑英華》卷六缺名《月照寒泉賦》附。","）。"]', '["月照泉兮泉涵月，泉潺湲兮月皎潔。","波無鱼兮清澄，月有蟾兮澄澈。","（见《文苑英华》卷六缺名《月照寒泉賦》附。","）。"]', '诗', 'shi', '', NULL, '泉月之歌 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('185ac34f-f49a-454d-a271-ee892f7e417e', '七夕歌（題擬）', '七夕歌（題擬）', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["悲莫悲兮離別長，怨莫怨兮私自傷。","斂橫波而向秋野，垂玉筯兮沾羅裳。","（見同書卷二三缺名《七夕賦》附。","）。"]', '["悲莫悲兮離別长，怨莫怨兮私自傷。","斂橫波而向秋野，垂玉筯兮沾羅裳。","（见同书卷二三缺名《七夕賦》附。","）。"]', '诗', 'shi', '', NULL, '七夕歌（題擬） 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d818c872-cfed-4f07-a085-189e5af3b5dc', '冰賦附詩', '冰賦附诗', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["深山窮谷[凌]（陵）人鑿，頒賜從來天下聞。","別有川池捐棄者，終思采斵獻明君。","（見同書卷三八缺名《冰賦》附。","）。"]', '["深山窮谷[凌]（陵）人鑿，頒賜從来天下闻。","別有川池捐棄者，終思采斵獻明君。","（见同书卷三八缺名《冰賦》附。","）。"]', '诗', 'shi', '', NULL, '冰賦附詩 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f535627b-d9ee-4cba-89a4-22786e6aad4d', '君臣同德賦附歌', '君臣同德賦附歌', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["元良明哉！股肱良哉！盛德至矣，大業廣矣！我一人兮化無窮，臨萬國兮道既融。","同心同德，君聖臣忠，子子孫孫，永代克隆。","（見同前卷四三缺名《君臣同德賦》附。","）。"]', '["元良明哉！股肱良哉！盛德至矣，大業廣矣！我一人兮化無窮，臨万国兮道既融。","同心同德，君聖臣忠，子子孫孫，永代克隆。","（见同前卷四三缺名《君臣同德賦》附。","）。"]', '诗', 'shi', '', NULL, '君臣同德賦附歌 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f2e59236-4358-4d56-adb1-95cedce58430', '籍田賦附田父歌', '籍田賦附田父歌', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["畇畇千畝兮理有疆，濟濟千耦兮稷既良。","躬三推兮供神蒼，分九鳸兮應農祥。","栥盛普淖兮潔敬斯皇，神之昕之兮將登穰穰。","（見同書卷七○缺名《籍田賦》附。","）。"]', '["畇畇千畝兮理有疆，濟濟千耦兮稷既良。","躬三推兮供神蒼，分九鳸兮應農祥。","栥盛普淖兮潔敬斯皇，神之昕之兮將登穰穰。","（见同书卷七○缺名《籍田賦》附。","）。"]', '诗', 'shi', '', NULL, '籍田賦附田父歌 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9b0ccbee-bfe3-48fa-8d68-36ab104bca09', '桔槹賦附歌', '桔槹賦附歌', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["大道隱兮世人薄，無爲守拙空寂寞。","老圃之道可行，何耻見機而作。","（見同書卷一一○缺名《桔槹賦》附。","）。"]', '["大道隐兮世人薄，無爲守拙空寂寞。","老圃之道可行，何耻见機而作。","（见同书卷一一○缺名《桔槹賦》附。","）。"]', '诗', 'shi', '', NULL, '桔槹賦附歌 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('81f6766c-ce61-4b07-b86d-0109e3a085c6', '唐伯牙彈琴鏡銘', '唐伯牙彈琴镜銘', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["獨有幽棲地，山亭隨女蘿。","澗清長低篠，池開半卷荷。","野花朝暝落，盤根歲月多。","停杯無嘗慰，峽鳥自經過。","。"]', '["独有幽棲地，山亭隨女蘿。","澗清长低篠，池开半卷荷。","野花朝暝落，盤根歲月多。","停杯無嘗慰，峽鸟自經過。","。"]', '诗', 'shi', '', NULL, '唐伯牙彈琴鏡銘 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4daaa80c-595a-4f45-bab6-762ee238390e', '唐八棱貼銀鍍金海上仙真八卦花鳥鏡銘', '唐八棱貼銀鍍金海上仙真八卦花鸟镜銘', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["舞鳳歸林近，盤龍渡海新。","緘封待還歸，披拂鑒情親。","隻影若爲客，孤鳴復幾春。","初成照瞻鏡，遙憶畫眉人。","（以上二首見沈從文《唐宋銅鏡》，中國古典藝術出版社一九五八年出版。","）。"]', '["舞鳳归林近，盤龙渡海新。","緘封待還归，披拂鑒情親。","隻影若爲客，孤鳴复幾春。","初成照瞻镜，遙憶畫眉人。","（以上二首见沈從文《唐宋銅镜》，中国古典藝術出版社一九五八年出版。","）。"]', '诗', 'shi', '', NULL, '唐八棱貼銀鍍金海上仙真八卦花鳥鏡銘 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cbc4967e-eda4-4b51-98fd-dc5522b8704f', '八卦十二生肖鏡銘', '八卦十二生肖镜銘', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["水銀呈陰精，百煉得爲鏡。","八卦壽像備，衛神永保命。"]', '["水銀呈陰精，百煉得爲镜。","八卦壽像備，衛神永保命。"]', '诗', 'shi', '', NULL, '八卦十二生肖鏡銘 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('180f7cb4-ed64-41e9-843a-ed761321e56c', '唐鏡銘', '唐镜銘', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["賞得秦王鏡，判（《金石索》一作「浙」）不惜千金。","非關欲照膽，特是自明心。","（以上二首見一九七九年《中國考古學會第一次年會論文集》刊孔祥星《隋唐銅鏡的類型與分期》引。","後一首又見《金石索·金索六》有二件，又見民國十五年錢祥保纂《續修江都縣志》卷十五《金石》，云爲邑人程青岳所藏。","）。"]', '["賞得秦王镜，判（《金石索》一作「浙」）不惜千金。","非关欲照膽，特是自明心。","（以上二首见一九七九年《中国考古学會第一次年會論文集》刊孔祥星《隋唐銅镜的類型與分期》引。","後一首又见《金石索·金索六》有二件，又见民国十五年錢祥保纂《續修江都縣志》卷十五《金石》，云爲邑人程青岳所藏。","）。"]', '诗', 'shi', '', NULL, '唐鏡銘 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ca481a26-8c02-414c-8dc1-3332d3a97e85', '唐鏡銘 一', '唐镜銘 一', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["別日菱花出，臨池滿月生。","官看巾帽整，妾映點（一作「美」）妝成。","（見同治己巳廣州刊林昌彞《海天琴思續錄》卷二，云鏡爲周南卿明經藏，「河東君物也。","」此條承黃霖同志錄示。","又見王士倫編《浙江出土銅鏡選集》序引，異文注出。","）。"]', '["別日菱花出，臨池满月生。","官看巾帽整，妾映点（一作「美」）妝成。","（见同治己巳廣州刊林昌彞《海天琴思續錄》卷二，云镜爲周南卿明經藏，「河东君物也。","」此條承黄霖同志錄示。","又见王士倫編《浙江出土銅镜選集》序引，異文注出。","）。"]', '诗', 'shi', '', NULL, '唐鏡銘 一 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('67751d6a-2420-452b-94d4-edf530a944dd', '唐鏡銘 二', '唐镜銘 二', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["冬朝日照梁，含怨下前床。","帷寒以葉帶，鏡轉菱花光。","會是無人覺，何用早紅妝。","（同前。","見王士倫《浙江出土銅鏡選集》序引。","）。"]', '["冬朝日照梁，含怨下前床。","帷寒以葉带，镜轉菱花光。","會是無人覺，何用早紅妝。","（同前。","见王士倫《浙江出土銅镜選集》序引。","）。"]', '诗', 'shi', '', NULL, '唐鏡銘 二 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b94f070e-0e1b-4aac-973b-ccd2b1466450', '水星鏡銘', '水星镜銘', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["永保命，水銀星，陰精百鍊得爲鏡，八卦壽象備衛神。","（見《全唐文》卷九八八。","）。"]', '["永保命，水銀星，陰精百鍊得爲镜，八卦壽象備衛神。","（见《全唐文》卷九八八。","）。"]', '诗', 'shi', '', NULL, '水星鏡銘 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('479741a5-8cb1-48f5-8268-d092189d2fc3', '唐武德禱雨辟邪鑌鐵鏡銘', '唐武德禱雨辟邪鑌鐵镜銘', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["鑌鐵作鏡辟大旱，清泉虔祀甘霖感，魅孽當前驚破膽，服之疫癘莫能犯。","雙龍嚄略垂長頷，回祿睢盱威早斂。","（見《唐文拾遺》卷六二引《湘煙錄》。","銘末署：「武德壬午，造辟邪花鑌鐵鏡。","」）。"]', '["鑌鐵作镜辟大旱，清泉虔祀甘霖感，魅孽當前驚破膽，服之疫癘莫能犯。","雙龙嚄略垂长頷，回祿睢盱威早斂。","（见《唐文拾遺》卷六二引《湘煙錄》。","銘末署：「武德壬午，造辟邪花鑌鐵镜。","」）。"]', '诗', 'shi', '', NULL, '唐武德禱雨辟邪鑌鐵鏡銘 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f22089c7-38f5-4806-8194-82544b036082', '唐鳳皇鏡銘', '唐鳳皇镜銘', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["對鳳皇舞，鑄黃金蔕。","（《金石索》首句作「鳳凰雙鏡南金裝」。","）陰陽各有合（《金石索》作「爲配」），日月恒相會。","白玉芙蓉匣，翠羽瓊瑤帶。","同心人，心（《金石索》無「心」字）相親，照心照膽保千春。","（見《西溪叢語》。","《金石索·金索六》有鳳凰雙鏡銘，文字稍異。","）。"]', '["对鳳皇舞，鑄黄金蔕。","（《金石索》首句作「鳳凰雙镜南金裝」。","）陰陽各有合（《金石索》作「爲配」），日月恒相會。","白玉芙蓉匣，翠羽瓊瑤带。","同心人，心（《金石索》無「心」字）相親，照心照膽保千春。","（见《西溪叢語》。","《金石索·金索六》有鳳凰雙镜銘，文字稍異。","）。"]', '诗', 'shi', '', NULL, '唐鳳皇鏡銘 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9b69e520-7faf-42ec-926a-732da64d6c95', '芙蓉鏡詩', '芙蓉镜诗', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["鸞鏡曉勻粧，慢把花鈿飾。","真如淥水中，一朵芙蓉出。","（《金石索·金索六》。","首有「詩云」二字。","）。"]', '["鸾镜晓勻粧，慢把花鈿飾。","真如淥水中，一朵芙蓉出。","（《金石索·金索六》。","首有「诗云」二字。","）。"]', '诗', 'shi', '', NULL, '芙蓉鏡詩 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('da0e6079-f7ee-4c3e-8e63-22aa16ac4d38', '鏡銘', '镜銘', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["偏識秦樓意，能照玉[妝]（庄）成。","花發無冬夏，臨臺曉夜明。","（《銅鏡圖案·湖南出土歷代銅鏡》）。"]', '["偏識秦楼意，能照玉[妝]（庄）成。","花發無冬夏，臨台晓夜明。","（《銅镜圖案·湖南出土歷代銅镜》）。"]', '诗', 'shi', '', NULL, '鏡銘 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5aebe00c-52ca-45fd-86b2-dfd67ca5c44a', '李德裕相公貶崖州三首 一', '李德裕相公貶崖州三首 一', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["樂天嘗任蘇州日，要勒須教（《苕》作「煩文」）用禮儀。","從此結成千萬恨。","今朝果中白家詩。"]', '["乐天嘗任蘇州日，要勒須教（《苕》作「煩文」）用禮儀。","從此結成千万恨。","今朝果中白家诗。"]', '诗', 'shi', '', NULL, '李德裕相公貶崖州三首 一 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4c988bac-009e-46fb-8e97-ac550f43a257', '李德裕相公貶崖州三首 二', '李德裕相公貶崖州三首 二', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["昨夜新生黃雀兒，飛來直上紫藤枝。","擺頭撼腦花園裏，將謂（《苕》作「爲」）春光總屬伊。"]', '["昨夜新生黄雀兒，飞来直上紫藤枝。","擺头撼腦花园裏，將謂（《苕》作「爲」）春光總屬伊。"]', '诗', 'shi', '', NULL, '李德裕相公貶崖州三首 二 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a61fef68-15a9-4cb7-b26b-45dd4074cdcb', '李德裕相公貶崖州三首 三', '李德裕相公貶崖州三首 三', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["閑（《塵史》作「田」、《苕》作「開」）園不解栽桃李，滿地唯聞種蒺藜。","萬里崖州君自去，臨行惆（《塵史》作「怊」）悵欲怨誰？","（見《四部叢刊》影印那波道圓本《白氏文集》卷二十，以《塵史》卷中、《苕溪漁隱叢話後集》卷十三參校。","）（〖1〗蘇轍《欒城後集》卷規模十一《書白樂天集後二首》云：「會昌之初，李文饒用事，樂天適已七十，不一二年而沒。","嗟夫，文饒尚不能置一樂天於分司中耶？","然樂天每閑冷衰病，發於詠歎，輒以公卿投荒僇死、不獲其終者自解，余亦鄙之。","至其《聞文饒謫朱崖三絕句》，刻核尤甚，樂天雖陋，蓋不至此也。","且樂天死於會昌之初，而文饒之竄，在會昌末年，此決非樂天之詩。","豈樂天廿徒淺陋不學者陋益之邪？樂天之賢，當爲辨之。","」〖2〗王得臣《塵史》卷中云：「令狐先生曰：『唐白傅以丞相李德裕貶崖州爲三絕句，便不負世人訾毀。","』予以爲詩三百皆出聖賢發憤而爲，又何傷哉。","後嘗語於客，會安陸令李楚老翹叟在坐上，曰：『非白公之詩也。","白公卒於李貶之前。","』予因按《唐史》，會昌六年白公卒，是歲宣宗即位，明年改元大中，又明年李貶，蓋當時疾李者托名爲之附於集。","詩曰〖略〗。","予觀其詞意鄙淺，白爲雜律詩譏世人，故人得以輕效之。","」〖3〗胡仔《苕溪漁隱叢話後集》卷十三云：「余以《元和錄》考之，居易年長於德裕，視德裕爲晚進。","方德裕任浙西觀察使，居易爲蘇州刺史，德裕以使職自居，不少假借，居易不得以卑禮見，及其貶也，故爲詩云〖略〗。","然《醉吟先生傳》及《實錄》皆謂居易會昌六年卒，而德裕貶於大中二年，或謂此詩爲僞。","余又以《新唐書》二人本傳考之，會昌初，白居易以刑部侍郎致仕，六年卒。","李德裕大中二年貶崖州司戶參軍。","會昌盡六年，距大中二年，正隔三年則此三詩非樂天所作明甚。","但蘇子由以謂樂天死於會昌之初，而文饒竄於會昌之末，偶一時所記之誤耳。","」按：今參諸家之說，收三詩爲無名氏作。","）。"]', '["闲（《塵史》作「田」、《苕》作「开」）园不解栽桃李，满地唯闻種蒺藜。","万里崖州君自去，臨行惆（《塵史》作「怊」）悵欲怨誰？","（见《四部叢刊》影印那波道圓本《白氏文集》卷二十，以《塵史》卷中、《苕溪漁隐叢話後集》卷十三參校。","）（〖1〗蘇轍《欒城後集》卷規模十一《书白乐天集後二首》云：「會昌之初，李文饒用事，乐天適已七十，不一二年而沒。","嗟夫，文饒尚不能置一乐天於分司中耶？","然乐天每闲冷衰病，發於詠歎，輒以公卿投荒僇死、不獲其終者自解，余亦鄙之。","至其《闻文饒謫朱崖三絕句》，刻核尤甚，乐天雖陋，蓋不至此也。","且乐天死於會昌之初，而文饒之竄，在會昌末年，此決非乐天之诗。","豈乐天廿徒淺陋不学者陋益之邪？乐天之賢，當爲辨之。","」〖2〗王得臣《塵史》卷中云：「令狐先生曰：『唐白傅以丞相李德裕貶崖州爲三絕句，便不負世人訾毀。","』予以爲诗三百皆出聖賢發憤而爲，又何傷哉。","後嘗語於客，會安陸令李楚老翹叟在坐上，曰：『非白公之诗也。","白公卒於李貶之前。","』予因按《唐史》，會昌六年白公卒，是歲宣宗即位，明年改元大中，又明年李貶，蓋當时疾李者托名爲之附於集。","诗曰〖略〗。","予观其词意鄙淺，白爲杂律诗譏世人，故人得以轻效之。","」〖3〗胡仔《苕溪漁隐叢話後集》卷十三云：「余以《元和錄》考之，居易年长於德裕，視德裕爲晚進。","方德裕任浙西观察使，居易爲蘇州刺史，德裕以使職自居，不少假借，居易不得以卑禮见，及其貶也，故爲诗云〖略〗。","然《醉吟先生傳》及《實錄》皆謂居易會昌六年卒，而德裕貶於大中二年，或謂此诗爲僞。","余又以《新唐书》二人本傳考之，會昌初，白居易以刑部侍郎致仕，六年卒。","李德裕大中二年貶崖州司戶參軍。","會昌尽六年，距大中二年，正隔三年則此三诗非乐天所作明甚。","但蘇子由以謂乐天死於會昌之初，而文饒竄於會昌之末，偶一时所記之誤耳。","」按：今參諸家之说，收三诗爲無名氏作。","）。"]', '诗', 'shi', '', NULL, '李德裕相公貶崖州三首 三 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b5d03e4c-ab87-4e13-a901-23d4fa24b8b6', '望嶽（題擬）', '望嶽（題擬）', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["（前缺）霜雪唯惜許，讓王遁時澨。","千乘不迴慮，萬金寧易節。","美物忌芳堅，達人諱明哲。","孤高霞月上，杳與氛埃絕。","（見《分門纂類唐歌詩》卷二十二。","）。"]', '["（前缺）霜雪唯惜許，讓王遁时澨。","千乘不迴慮，万金寧易節。","美物忌芳堅，達人諱明哲。","孤高霞月上，杳與氛埃絕。","（见《分门纂類唐歌诗》卷二十二。","）。"]', '诗', 'shi', '', NULL, '望嶽（題擬） 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0e5fc525-4d0c-4947-a600-cd58bb11aa9a', '山榴（題擬）', '山榴（題擬）', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["（前缺）病隨支遁偶行行，正見榴花獨滿庭。","瘦竹成林人不看，却應羞得強青青。","（見同書卷九十三。","）。"]', '["（前缺）病隨支遁偶行行，正见榴花独满庭。","瘦竹成林人不看，却應羞得強青青。","（见同书卷九十三。","）。"]', '诗', 'shi', '', NULL, '山榴（題擬） 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fbfec805-2ad8-4822-b3b8-a4a886417d4a', '甘州樂', '甘州乐', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["燕路霸山遠，胡關易水寒。","茫茫風藻動，澮澮陽隻閑。","殘月蘆江白，老花菊岸[丹]（舟）。","竹驚暖露冷，落葉寒飈闌。","（見日本《古事類苑》「唐樂樂曲甘州第四帖」辭。","）。"]', '["燕路霸山远，胡关易水寒。","茫茫风藻动，澮澮陽隻闲。","殘月蘆江白，老花菊岸[丹]（舟）。","竹驚暖露冷，落葉寒飈闌。","（见日本《古事類苑》「唐乐乐曲甘州第四帖」辞。","）。"]', '诗', 'shi', '', NULL, '甘州樂 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6ab9a7e9-c2f1-479b-98d1-f52015593133', '醉公子', '醉公子', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["門外猧兒吠，知是蕭郎至。","剗襪下芳（《詞品》作「香」）階，冤家今夜醉。","扶得入羅幃，不肯脫羅衣。","醉則從他醉，猶勝獨眠（《詞品》作「睡」）時。","（見宋陳模《懷古錄》卷上。","）。"]', '["门外猧兒吠，知是蕭郎至。","剗襪下芳（《词品》作「香」）階，冤家今夜醉。","扶得入羅幃，不肯脫羅衣。","醉則從他醉，猶勝独眠（《词品》作「睡」）时。","（见宋陳模《懷古錄》卷上。","）。"]', '诗', 'shi', '', NULL, '醉公子 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ce8779a5-5ce6-43bc-8349-a6ece8f89387', '小秦王', '小秦王', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["柳條金嫩不勝雅（《詞品》作「鴉」），青粉牆頭道韞家。","燕子不來春寂寂，小窗和雨夢梨花。","（見楊慎《百琲明珠》及《詞品》卷一。","）。"]', '["柳條金嫩不勝雅（《词品》作「鴉」），青粉牆头道韞家。","燕子不来春寂寂，小窗和雨梦梨花。","（见楊慎《百琲明珠》及《词品》卷一。","）。"]', '诗', 'shi', '', NULL, '小秦王 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6457e12a-433a-457c-a0f1-1205b8a64ae9', '輪臺', '輪台', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["燕子山裏食散。","莫賀鹽聲平回。","共酌葡萄美酒，相抱聚蹈輪臺。","（見日本源光圀《大日本史·禮樂志》。","以上四首，皆轉自任半塘先生《唐聲詩》下編。","）。"]', '["燕子山裏食散。","莫賀鹽声平回。","共酌葡萄美酒，相抱聚蹈輪台。","（见日本源光圀《大日本史·禮乐志》。","以上四首，皆轉自任半塘先生《唐声诗》下編。","）。"]', '诗', 'shi', '', NULL, '輪臺 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3f78e9fa-06e9-427c-8ab7-1859e449ec50', '花', '花', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["小隱園中百本花，各隨紅紫發新芽。","東君見借陽和力，盡在公候富貴家。","（見《分門纂類唐宋時賢千家詩選》卷七。","）。"]', '["小隐园中百本花，各隨紅紫發新芽。","东君见借陽和力，尽在公候富貴家。","（见《分门纂類唐宋时賢千家诗選》卷七。","）。"]', '诗', 'shi', '', NULL, '花 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('08b06470-4e20-40b3-a969-004d77f0ec32', '繼古韻一百十二字贈穆先生', '繼古韻一百十二字贈穆先生', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["大華山陰穆老仙。","專持清靜探幽玄。","修補祇陀無漏園，常流慧水溉心田。","擒猿縛馬翠峯巔，定觀不用買山錢。","捨俗投玄心契悟，善惡之由夙世緣。","心香福炷起靈源，杳杳冥冥達上天。","秋日碧潭真了了，野花啼鳥謾喧喧。","鼎中火滅開金蘂，木上無煙結玉蓮，壘功積行滿三千，性圓丹結去朝元。","（影印本《詩淵》第一冊第四一八頁。","）。"]', '["大华山陰穆老仙。","專持清静探幽玄。","修補祇陀無漏园，常流慧水溉心田。","擒猿縛马翠峯巔，定观不用買山錢。","捨俗投玄心契悟，善惡之由夙世緣。","心香福炷起靈源，杳杳冥冥達上天。","秋日碧潭真了了，野花啼鸟謾喧喧。","鼎中火滅开金蘂，木上無煙結玉蓮，壘功積行满三千，性圓丹結去朝元。","（影印本《诗淵》第一冊第四一八頁。","）。"]', '诗', 'shi', '', NULL, '繼古韻一百十二字贈穆先生 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d11fa6cb-8a9b-42d9-9dbe-4d4d9e83d95c', '贈韓家郎君在家修行', '贈韓家郎君在家修行', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["崇真起善立玄堂，謹奉朝昏兩炷香。","內侍孀親行孝道，外持貞正合三光。","常行矜憫提貧困，每施慈悲挈下殃。","他日聰明如省悟，也應歸去到仙鄉。","（同前第五六二頁。","）。"]', '["崇真起善立玄堂，謹奉朝昏兩炷香。","內侍孀親行孝道，外持貞正合三光。","常行矜憫提貧困，每施慈悲挈下殃。","他日聰明如省悟，也應归去到仙乡。","（同前第五六二頁。","）。"]', '诗', 'shi', '', NULL, '贈韓家郎君在家修行 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1b5f8709-f86a-4a6e-93ce-52824339680d', '贈別畢道士', '贈別畢道士', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["夜夢海上羣仙山。","旦逢瀛洲道士還。","憑風倚景長歎息，彌憐昨夜雲峰邑。","霓裳羽旆惜分飛，方外人間此日違。","君不見遼東華表柱，但有空歌丁令威。","（同前第五六二頁。","）。"]', '["夜梦海上羣仙山。","旦逢瀛洲道士還。","憑风倚景长歎息，彌怜昨夜云峰邑。","霓裳羽旆惜分飞，方外人间此日違。","君不见遼东华表柱，但有空歌丁令威。","（同前第五六二頁。","）。"]', '诗', 'shi', '', NULL, '贈別畢道士 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9a88b896-0a8d-4708-b709-2706dde9d9da', '五代時人爲至聰禪師頌（題擬）', '五代时人爲至聰禪師頌（題擬）', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["有道山僧號至聰，十年不下祝融峰。","腰間所積菩提水，瀉向紅蓮一葉中。","（見《侍兒小名錄拾遺》引《古今詩話》。","）。"]', '["有道山僧號至聰，十年不下祝融峰。","腰间所積菩提水，瀉向紅蓮一葉中。","（见《侍兒小名錄拾遺》引《古今诗話》。","）。"]', '诗', 'shi', '', NULL, '五代時人爲至聰禪師頌（題擬） 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('78dc2bd1-6ac6-41f2-a8a8-f0d144d4c1d2', '題閑處士隱居', '題闲处士隐居', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["野老南湖上，茅簷向水低。","應門仲躬子，舉[案]（按）伯鸞妻。","籬下山花笑，窗前穀鳥啼。","猶言近人境，不似武陵溪。","（《新撰類林鈔》卷四，據小川環樹本。","）。"]', '["野老南湖上，茅簷向水低。","應门仲躬子，舉[案]（按）伯鸾妻。","籬下山花笑，窗前穀鸟啼。","猶言近人境，不似武陵溪。","（《新撰類林鈔》卷四，據小川环樹本。","）。"]', '诗', 'shi', '', NULL, '題閑處士隱居 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('231edbaa-2d4e-4d78-875f-78e5b61b4881', '古琴袋織成詩', '古琴袋织成诗', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["自來行止賦驕奢，更有何人力可加。","分得御溝新鑿址，占他農地別種花。","樓臺夜宴停紅燭，妓女春梢俵絳紗。","大醉不知光景去，難迹雙髩染霜華。","（宋俞文豹《吹劍三錄》，云「疑是孟蜀藩國宗戚所作」。","）。"]', '["自来行止賦驕奢，更有何人力可加。","分得御溝新鑿址，占他農地別種花。","楼台夜宴停紅燭，妓女春梢俵絳紗。","大醉不知光景去，难迹雙髩染霜华。","（宋俞文豹《吹劍三錄》，云「疑是孟蜀藩国宗戚所作」。","）。"]', '诗', 'shi', '', NULL, '古琴袋織成詩 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ab511d81-9b61-4103-a39e-a37db3a0ff37', '白牡丹 一', '白牡丹 一', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["漫山桃李占春光，始見檀心吐異芳。","花骨不禁寒料峭，多煩曉日爲催妝。"]', '["漫山桃李占春光，始见檀心吐異芳。","花骨不禁寒料峭，多煩晓日爲催妝。"]', '诗', 'shi', '', NULL, '白牡丹 一 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('16f60eba-55d9-4b09-b262-98afbc548508', '白牡丹 二', '白牡丹 二', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["既全國色與天香，底用家人紫共黃。","却喜騷人稱第一，至今喚作百花王。","（《分門纂類唐宋時賢千家詩選》卷九。","）。"]', '["既全国色與天香，底用家人紫共黄。","却喜騷人稱第一，至今喚作百花王。","（《分门纂類唐宋时賢千家诗選》卷九。","）。"]', '诗', 'shi', '', NULL, '白牡丹 二 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8a276e9c-0571-4005-88c9-9edce8098328', '箜篌謠', '箜篌謠', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["結交在相得，骨肉何必親。","甘言無忠實，世薄多蘇秦。","從風暫靡草，富貴上昇人（一作「真」）。","不見高顛樹，摧杌下爲薪。","豈甘（一作「目覩」）井中泥，時至出作塵。","（見《文苑英華》卷二一○。","）。"]', '["結交在相得，骨肉何必親。","甘言無忠實，世薄多蘇秦。","從风暫靡草，富貴上昇人（一作「真」）。","不见高顛樹，摧杌下爲薪。","豈甘（一作「目覩」）井中泥，时至出作塵。","（见《文苑英华》卷二一○。","）。"]', '诗', 'shi', '', NULL, '箜篌謠 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d0fa472b-323c-4220-9235-53153b806537', '贈段文昌', '贈段文昌', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["昔日騎驢學忍饑，今朝忽著錦衣歸。","等閑畫虎驅紅旆，可畏登龍入紫微。","富貴不由翁祖（一作「簪組」）解，文章生得羽毛飛。","廣都再去應惆悵，猶有江邊舊釣磯。","（見蜀何光遠《鑑戒錄》卷八「衣錦歸」條。","）（〖1〗《鑑戒錄》云：「段相國文昌本廣都人，父以油柞爲業。","生而有致，長亦多才，物業蕩空，文章迴振。","洎跨衛行卷，鄉里笑之歷三十年間，衣錦還蜀，蜀人有詩贈曰〖略〗。","」）。"]', '["昔日騎驢学忍饑，今朝忽著錦衣归。","等闲畫虎驱紅旆，可畏登龙入紫微。","富貴不由翁祖（一作「簪組」）解，文章生得羽毛飞。","廣都再去應惆悵，猶有江邊旧釣磯。","（见蜀何光远《鑑戒錄》卷八「衣錦归」條。","）（〖1〗《鑑戒錄》云：「段相国文昌本廣都人，父以油柞爲業。","生而有致，长亦多才，物業蕩空，文章迴振。","洎跨衛行卷，乡里笑之歷三十年间，衣錦還蜀，蜀人有诗贈曰〖略〗。","」）。"]', '诗', 'shi', '', NULL, '贈段文昌 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('04ed901a-33fc-426b-907a-427e37590a2a', '五言詩 一', '五言诗 一', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["夜夜掛長鉤，朝朝望楚樓。","可憐孤月夜，滄照客心愁。","。"]', '["夜夜掛长鉤，朝朝望楚楼。","可怜孤月夜，滄照客心愁。","。"]', '诗', 'shi', '', NULL, '五言詩 一 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8ef0ba28-d713-4ff0-a8e1-76a077ec9552', '五言詩 二', '五言诗 二', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["聖水出溫泉，新陽萬里傳。","常居安樂國，多報未來緣。"]', '["聖水出溫泉，新陽万里傳。","常居安乐国，多報未来緣。"]', '诗', 'shi', '', NULL, '五言詩 二 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a3b98a6c-0d68-4869-a39d-aed0def2bc5f', '五言詩 三', '五言诗 三', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["日日思前路，朝朝別主人。","行行山水上，處處鳥啼新。"]', '["日日思前路，朝朝別主人。","行行山水上，处处鸟啼新。"]', '诗', 'shi', '', NULL, '五言詩 三 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('72449d21-bccb-43dd-9ed1-d7ca29e4f57e', '五言詩 四', '五言诗 四', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["祇愁啼鳥別，恨送古人多。","去後看明月，風光處處過。"]', '["祇愁啼鸟別，恨送古人多。","去後看明月，风光处处過。"]', '诗', 'shi', '', NULL, '五言詩 四 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b9d970b1-40b0-49ee-a616-57e82cbc2f99', '五言詩 五', '五言诗 五', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["一別行萬里，來時未有期。","月中三十日，無夜不相思。"]', '["一別行万里，来时未有期。","月中三十日，無夜不相思。"]', '诗', 'shi', '', NULL, '五言詩 五 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ae6c225c-1ed9-4154-a9d7-b52d27e3ed8d', '五言詩 六', '五言诗 六', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["千里人歸去，心畫（疑爲盡字）一盃中。","莫慮前途遠，開坑（疑爲帆字）逐便風。"]', '["千里人归去，心畫（疑爲尽字）一盃中。","莫慮前途远，开坑（疑爲帆字）逐便风。"]', '诗', 'shi', '', NULL, '五言詩 六 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e5ea0f4d-34e0-4bcc-8260-d58117e8528d', '五言詩 七', '五言诗 七', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["小水通大河，山深鳥宿多。","主人看客好，曲路亦相過。"]', '["小水通大河，山深鸟宿多。","主人看客好，曲路亦相過。"]', '诗', 'shi', '', NULL, '五言詩 七 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6c392e66-e559-456a-a61c-5d511868f224', '五言詩 八', '五言诗 八', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["道別即須分，何勞說苦[辛]（新）。","牽牛石上過，不見有[蹄痕]（啼恨）。"]', '["道別即須分，何勞说苦[辛]（新）。","牽牛石上過，不见有[蹄痕]（啼恨）。"]', '诗', 'shi', '', NULL, '五言詩 八 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('197dbab5-877e-4c86-9106-430fccdfe69b', '五言詩 九', '五言诗 九', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["一月三場戰，曾無賞罰爲。","將軍馬上坐，將士雪上眠。","（眠字不韻，疑有誤，原校改作「歸」字，尚難確定。","）。"]', '["一月三場戰，曾無賞罰爲。","將軍马上坐，將士雪上眠。","（眠字不韻，疑有誤，原校改作「归」字，尚难確定。","）。"]', '诗', 'shi', '', NULL, '五言詩 九 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cc02096e-86f3-440d-aae1-b8fb0133ae62', '五言詩 十', '五言诗 十', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["自入新[豐]（峰）市，唯聞舊酒香。","抱琴酤一醉，盡日卧彎湯。"]', '["自入新[豐]（峰）市，唯闻旧酒香。","抱琴酤一醉，尽日卧彎湯。"]', '诗', 'shi', '', NULL, '五言詩 十 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5b86d8d4-51a5-4bfa-b5df-5d72e75c3f18', '五言詩 十一', '五言诗 十一', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["我有方寸心，無人堪共說。","遣風吹却雲，言向天邊月。"]', '["我有方寸心，無人堪共说。","遣风吹却云，言向天邊月。"]', '诗', 'shi', '', NULL, '五言詩 十一 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1074a589-a0c7-4597-a1c6-9c0ae00b94cf', '五言詩 十二', '五言诗 十二', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["男兒大丈夫，何用本鄉居。","明月家家有，黃金何處無。"]', '["男兒大丈夫，何用本乡居。","明月家家有，黄金何处無。"]', '诗', 'shi', '', NULL, '五言詩 十二 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8f84dcdb-e92c-47bf-add3-26cc7f5a5b38', '五言詩 十三', '五言诗 十三', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["客人莫直入，直入主人[嗔]（宴）。","扣門三五下，自有出來人。"]', '["客人莫直入，直入主人[嗔]（宴）。","扣门三五下，自有出来人。"]', '诗', 'shi', '', NULL, '五言詩 十三 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9dc5abe4-569c-4fca-bfbf-811181c5b5c6', '五言詩 十四', '五言诗 十四', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["君生我未生，我生君已老。","君恨我生遲，我恨君生早。"]', '["君生我未生，我生君已老。","君恨我生遲，我恨君生早。"]', '诗', 'shi', '', NULL, '五言詩 十四 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fd4e48ff-a052-431a-bf66-c28d5c3ec9c0', '五言詩 十五', '五言诗 十五', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["天地平如水，王道自然開。","家中無學子，官從何處來。"]', '["天地平如水，王道自然开。","家中無学子，官從何处来。"]', '诗', 'shi', '', NULL, '五言詩 十五 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f5a0b1fa-d836-464a-9dd7-34add94d928c', '五言詩 十六', '五言诗 十六', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["龍門多貴客，出戶是賢賓。","今日歸家去，將與貴人看。"]', '["龙门多貴客，出戶是賢賓。","今日归家去，將與貴人看。"]', '诗', 'shi', '', NULL, '五言詩 十六 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('548152e4-4d84-4e76-a872-86dbc7ce0020', '五言詩 十七', '五言诗 十七', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["天明日月奣，五月已三龍。","言身一寸謝，千里重金偅。","（末字疑應爲「鍾」字。","）。"]', '["天明日月奣，五月已三龙。","言身一寸謝，千里重金偅。","（末字疑應爲「鍾」字。","）。"]', '诗', 'shi', '', NULL, '五言詩 十七 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8df0e416-6c6e-490a-8bd5-8268625b2d7c', '五言詩 十八', '五言诗 十八', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["上有東流水，下有好山林。","主人居此宅，可以斗量金。"]', '["上有东流水，下有好山林。","主人居此宅，可以斗量金。"]', '诗', 'shi', '', NULL, '五言詩 十八 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('01eace0a-8279-4776-b1f2-751b9a87b215', '五言詩 十九', '五言诗 十九', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["買人心惆悵，賣人心不安。","題詩安瓶上，將與賣人看。"]', '["買人心惆悵，賣人心不安。","題诗安瓶上，將與賣人看。"]', '诗', 'shi', '', NULL, '五言詩 十九 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7a0217f6-f689-4a84-9c07-e35fd04d9c28', '五言詩 二○', '五言诗 二○', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["自從君別後，常守舊時心。","洛陽來路遠，還用幾黃金。"]', '["自從君別後，常守旧时心。","洛陽来路远，還用幾黄金。"]', '诗', 'shi', '', NULL, '五言詩 二○ 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('606b0ccd-5a32-45c3-9665-efc78b73834a', '五言詩 二一', '五言诗 二一', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["念念催年促，由如少水如。","勸諸行過衆，修學香無餘。"]', '["念念催年促，由如少水如。","勸諸行過衆，修学香無餘。"]', '诗', 'shi', '', NULL, '五言詩 二一 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('df5b045f-18fe-4c19-ab78-c68662acc2c9', '句 一', '句 一', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["富從[升]（昇）合起，貧從不計來。"]', '["富從[升]（昇）合起，貧從不計来。"]', '诗', 'shi', '', NULL, '句 一 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f49e5838-7161-4936-8f21-14d695ef6be4', '句 二', '句 二', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["不知何處在？惆悵望東西。"]', '["不知何处在？惆悵望东西。"]', '诗', 'shi', '', NULL, '句 二 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('791a3050-08f3-4bef-b852-7d816cc9a87c', '句 三', '句 三', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["爲君報此訓，世上求名利。"]', '["爲君報此訓，世上求名利。"]', '诗', 'shi', '', NULL, '句 三 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3143a38b-2859-401d-acd8-c9e75e828066', '句 四', '句 四', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["上有千年樹，下有百年人。"]', '["上有千年樹，下有百年人。"]', '诗', 'shi', '', NULL, '句 四 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b66dfe75-b66d-434c-8cf0-59b9241f21c2', '句 五', '句 五', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["流水何年盡，青山卷幾□。"]', '["流水何年尽，青山卷幾□。"]', '诗', 'shi', '', NULL, '句 五 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9524453a-aa37-4a5e-947d-c677576eacde', '句 六', '句 六', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["言滿天下無口過。"]', '["言满天下無口過。"]', '诗', 'shi', '', NULL, '句 六 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a8426eae-1ad3-4ee8-aa2a-4809feb6b97b', '句 七', '句 七', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["羅綱之鳥，悔不高飛。"]', '["羅綱之鸟，悔不高飞。"]', '诗', 'shi', '', NULL, '句 七 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bdc29b6a-7505-471f-94b4-12863f1ad68e', '句 八', '句 八', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["人生壹世，草生壹時。","（以上均錄自《考古學報》一九八○年第一期刊長沙巿文化局文物組撰《唐代長沙銅官窰址調查》。","）（按：唐代長沙銅窰窰址，在今長沙市望城縣銅官鎮至石渚湖一帶。","長沙市文化局於一九七四年至一九七八年間加以發掘調查，得器物二千餘件。","以上所錄各詩，均題於器物之上，多寫於壸嘴或盤碗內底。","其中六言詩一首，爲劉長卿《苕溪酬梁耿別後見寄》中四句，即韋承慶《南行別弟》詩。","二詩已收入《全唐詩》。","）（另有俗語若干條，未錄。","同時所出有紀年之器物凡三件，錄如次：「元和三年四月卅日造印子由子宰記。","」「大中玖年正月廿八日書記。","」「大中拾年拾日參造鼓價。","」）。"]', '["人生壹世，草生壹时。","（以上均錄自《考古学報》一九八○年第一期刊长沙巿文化局文物組撰《唐代长沙銅官窰址調查》。","）（按：唐代长沙銅窰窰址，在今长沙市望城縣銅官鎮至石渚湖一带。","长沙市文化局於一九七四年至一九七八年间加以發掘調查，得器物二千餘件。","以上所錄各诗，均題於器物之上，多寫於壸嘴或盤碗內底。","其中六言诗一首，爲劉长卿《苕溪酬梁耿別後见寄》中四句，即韋承慶《南行別弟》诗。","二诗已收入《全唐诗》。","）（另有俗語若干條，未錄。","同时所出有紀年之器物凡三件，錄如次：「元和三年四月卅日造印子由子宰記。","」「大中玖年正月廿八日书記。","」「大中拾年拾日參造鼓價。","」）。"]', '诗', 'shi', '', NULL, '句 八 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cdfc7c10-69e7-41ae-ad99-99344f3c3d9f', '五言詩 一', '五言诗 一', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["春水春池滿，春時春草生。","春人飲春酒，春鳥哢春聲。","（見《文物》一九七二年第三期刊李知宴《唐代瓷窰概況與唐瓷的分期》引，係「無產階級文化大革命中出土文物展覽」在湖南展出的一件長沙窰壸腹部所題詩。","伯三五九七卷收此詩，前二句作「春日春風動，春來春草生」。","）。"]', '["春水春池满，春时春草生。","春人饮春酒，春鸟哢春声。","（见《文物》一九七二年第三期刊李知宴《唐代瓷窰概況與唐瓷的分期》引，係「無產階級文化大革命中出土文物展覽」在湖南展出的一件长沙窰壸腹部所題诗。","伯三五九七卷收此诗，前二句作「春日春风动，春来春草生」。","）。"]', '诗', 'shi', '', NULL, '五言詩 一 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('46aefac7-128e-42c2-8103-6cc37d3dcc92', '五言詩 二', '五言诗 二', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["日紅衫子合羅裙，盡日看花不厭春。","更向妝臺重注口，無那蕭郎恍煞人。"]', '["日紅衫子合羅裙，尽日看花不厭春。","更向妝台重注口，無那蕭郎恍煞人。"]', '诗', 'shi', '', NULL, '五言詩 二 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('35ee3661-3fe5-4eb8-8a5c-05f8115733d5', '五言詩 三', '五言诗 三', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["白玉非爲寶，千金我不須，憶念千張紙，心藏萬卷書。"]', '["白玉非爲寶，千金我不須，憶念千張紙，心藏万卷书。"]', '诗', 'shi', '', NULL, '五言詩 三 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('db17114a-88a2-4d1b-ba42-7f87beb04d35', '五言詩 四', '五言诗 四', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["主人不相識，獨坐對林[泉]（全）。","莫慢愁酤酒，懷中自有錢。","（以上三詩皆見長沙銅官窰唐代瓷器題詩，錄自香港《大公報》一九八五年十月二十六日刊傳舉有《長沙窰新發現的唐詩》一文。","該文承任半塘先生錄示。","）。"]', '["主人不相識，独坐对林[泉]（全）。","莫慢愁酤酒，懷中自有錢。","（以上三诗皆见长沙銅官窰唐代瓷器題诗，錄自香港《大公報》一九八五年十月二十六日刊傳舉有《长沙窰新發現的唐诗》一文。","該文承任半塘先生錄示。","）。"]', '诗', 'shi', '', NULL, '五言詩 四 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e0af86e4-ecea-4797-b875-0f2613cbc84c', '靈叟吟', '靈叟吟', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["我欲學菩提，輸他釋迦先。","我欲學闡提，落他調達後。","不涉二家風，未免中途走。","設使總不是，憑何而開口。","開口不開口，切忌犯靈叟。","著會箇中意，望南觀北斗。","（見延壽《宗鏡錄》卷四十一。","）。"]', '["我欲学菩提，輸他釋迦先。","我欲学闡提，落他調達後。","不涉二家风，未免中途走。","設使總不是，憑何而开口。","开口不开口，切忌犯靈叟。","著會箇中意，望南观北斗。","（见延壽《宗镜錄》卷四十一。","）。"]', '诗', 'shi', '', NULL, '靈叟吟 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9faec0f8-85c2-4fb4-9861-394437da4e26', '偈', '偈', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["得之不得天魔得，玄之又玄外道玄。","拋却父孃村草裏，認他黃葉作金錢。","百丈竿頭快撒手，不須觀後復觀前。","（見同書卷一○○引先德偈。","）。"]', '["得之不得天魔得，玄之又玄外道玄。","拋却父孃村草裏，認他黄葉作金錢。","百丈竿头快撒手，不須观後复观前。","（见同书卷一○○引先德偈。","）。"]', '诗', 'shi', '', NULL, '偈 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('842c29d9-fa6c-4289-8153-1e05ac15d003', '簡（一作「揀」）金頌', '簡（一作「揀」）金頌', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["君不見，澄清麗水出黃金，逐浪隨波永被沈。","有幸得逢良鑒者，披砂細揀暫知音。","因此遂蒙皇上寵，直入瓊樓寶篋中。","一練（一作「鍊」）一明光照耀，一迴掌上一迴欽。","以此塵沙含妙寶，故喻衆生覺照心。","衆生無此濃三有，元來流浪被境侵。","對塵恰似真如慧，離境元無照體心。","迷即一真名二體，只爲羣生不照心。","若能對境常真照，隨塵離境一般心。","如來今日除分別，意遣衆生妄習心。","但除妄習存終始，真照何妄不真心。","（見《宗鏡錄》卷八五。","）。"]', '["君不见，澄清丽水出黄金，逐浪隨波永被沈。","有幸得逢良鑒者，披砂細揀暫知音。","因此遂蒙皇上寵，直入瓊楼寶篋中。","一練（一作「鍊」）一明光照耀，一迴掌上一迴欽。","以此塵沙含妙寶，故喻衆生覺照心。","衆生無此濃三有，元来流浪被境侵。","对塵恰似真如慧，離境元無照體心。","迷即一真名二體，只爲羣生不照心。","若能对境常真照，隨塵離境一般心。","如来今日除分別，意遣衆生妄習心。","但除妄習存終始，真照何妄不真心。","（见《宗镜錄》卷八五。","）。"]', '诗', 'shi', '', NULL, '簡（一作「揀」）金頌 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('93ffa542-6e09-496f-a1bc-dd30da80aaf8', '紀彌勒菩薩上生變贊', '紀彌勒菩薩上生变贊', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["上越參羅第四天，三柢道滿實難宣。","補□慈尊光□□，誰蒙□聖□三千。","寶樹常能說妙然，八功池內鎖門蓮，鐵綱玲瓏嚴寶柱，無住競奏□諸天。","盈盈玉女憑珠檻，兩兩玉童弄綠波。","報□□分隨器變，修因六行更無過。","（見《山右石刻叢編》卷八。","）。"]', '["上越參羅第四天，三柢道满實难宣。","補□慈尊光□□，誰蒙□聖□三千。","寶樹常能说妙然，八功池內鎖门蓮，鐵綱玲瓏嚴寶柱，無住競奏□諸天。","盈盈玉女憑珠檻，兩兩玉童弄綠波。","報□□分隨器变，修因六行更無過。","（见《山右石刻叢編》卷八。","）。"]', '诗', 'shi', '', NULL, '紀彌勒菩薩上生變贊 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('95a4d19b-6f43-4853-8b02-5b2bc8c88e02', '興文塔銘', '兴文塔銘', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["東西南北總銅山，萬萬千千彌億千。","錢坊日鑄百萬算，功匠千人若神仙。","天寶三載置此塔，不朽不壞與天連。","（見光緒元年刊劉榮等纂《廣昌縣志》卷十二。","）（按：《興文塔銘》石刻，正書，天寶三載建，在東嶽行祠。","署「渤海郡常選上柱國高澄書」。","作者不祥。","）。"]', '["东西南北總銅山，万万千千彌億千。","錢坊日鑄百万算，功匠千人若神仙。","天寶三載置此塔，不朽不壞與天連。","（见光緒元年刊劉榮等纂《廣昌縣志》卷十二。","）（按：《兴文塔銘》石刻，正书，天寶三載建，在东嶽行祠。","署「渤海郡常選上柱国高澄书」。","作者不祥。","）。"]', '诗', 'shi', '', NULL, '興文塔銘 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('802fb4f3-ebf3-4b68-b7fa-06689e0dd790', '刺裴度詩', '刺裴度诗', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["不栽桃李種薔薇，荆棘滿庭君始知。","（見《演繁露續集》卷四。","）。"]', '["不栽桃李種薔薇，荆棘满庭君始知。","（见《演繁露續集》卷四。","）。"]', '诗', 'shi', '', NULL, '刺裴度詩 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('20c4939b-4974-4b08-b82f-820cb5d584e8', '獻錢鏐詩', '獻錢鏐诗', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["一條江水檻前流。","（見《續世說》卷三。","）（〖1〗《續世說》：「有人獻詩於〖錢〗鏐者云〖略〗。","鏐以爲譏己，殺之。","」）。"]', '["一條江水檻前流。","（见《續世说》卷三。","）（〖1〗《續世说》：「有人獻诗於〖錢〗鏐者云〖略〗。","鏐以爲譏己，殺之。","」）。"]', '诗', 'shi', '', NULL, '獻錢鏐詩 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('509a6042-6bba-40ad-a032-abd0063b7860', '贄高駢歌（題擬）', '贄高駢歌（題擬）', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["五色真龍上漢時，願把霓旌引煙策。","（見《南部新書》卷癸。","）（〖1〗《南部新書》：「高駢在淮南，有贄歌者，末章云〖略〗。","公說，乃辟爲從事。","及公遇害，有識者多嗤其言過也。","」）。"]', '["五色真龙上漢时，願把霓旌引煙策。","（见《南部新书》卷癸。","）（〖1〗《南部新书》：「高駢在淮南，有贄歌者，末章云〖略〗。","公说，乃辟爲從事。","及公遇害，有識者多嗤其言過也。","」）。"]', '诗', 'shi', '', NULL, '贄高駢歌（題擬） 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0633751f-f6eb-41f2-b34d-c9c54832fe1d', '五代幽薊人詩', '五代幽薊人诗', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["月明星稀夜，皆欲向南飛。","（見《古今詩話》，《增修詩話總龜前集》卷二十引。","《全五代詩話》卷十二錄此詩前有後人附加之「要識塗鴉意，栖遲未得歸」二句。","）。"]', '["月明星稀夜，皆欲向南飞。","（见《古今诗話》，《增修诗話總龟前集》卷二十引。","《全五代诗話》卷十二錄此诗前有後人附加之「要識塗鴉意，栖遲未得归」二句。","）。"]', '诗', 'shi', '', NULL, '五代幽薊人詩 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('58e17651-68b8-4454-895a-752e930a28d3', '無雙歌 一', '無雙歌 一', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["庭下梨花雪四垂。","（見宋陳元龍《片玉集注》卷二《浪淘沙》注引。","）。"]', '["庭下梨花雪四垂。","（见宋陳元龙《片玉集注》卷二《浪淘沙》注引。","）。"]', '诗', 'shi', '', NULL, '無雙歌 一 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3e970aad-db02-457c-951b-1e0d58faa2fb', '無雙歌 二', '無雙歌 二', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["紅簾如水隔神仙，月清露冷隔茶煙。","茶煙未滅簾中語，一寸深心暗與傳。","（同前書卷六《訴衷情》注引。","）（〖1〗《文史》十一輯刊程毅中《麗情集考》云：「這首《无雙歌》作者不詳，不知是薛調同時人所作，還是宋代人所附加的。","」）。"]', '["紅簾如水隔神仙，月清露冷隔茶煙。","茶煙未滅簾中語，一寸深心暗與傳。","（同前书卷六《訴衷情》注引。","）（〖1〗《文史》十一輯刊程毅中《丽情集考》云：「這首《无雙歌》作者不詳，不知是薛調同时人所作，還是宋代人所附加的。","」）。"]', '诗', 'shi', '', NULL, '無雙歌 二 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f4cd607d-febc-4ddc-aeeb-ef677947d518', '真真歌 一', '真真歌 一', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["紅玉枕高冰簟滑，凝煙戞水春雲闊。","重重翠被紅雲錦，枕肱不枕相思枕。"]', '["紅玉枕高冰簟滑，凝煙戞水春云闊。","重重翠被紅云錦，枕肱不枕相思枕。"]', '诗', 'shi', '', NULL, '真真歌 一 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2fd8fd80-7c49-4140-b6e5-9e7254d5e939', '真真歌 二', '真真歌 二', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["蛺蝶雙飛芍藥前，鴛鴦對浴芙蓉水。","（均見《錦鏽萬花谷前集》卷十七。","）（按：鄭還古戀沈真真故事，見《侍兒小名錄》及《綠窗新話》卷上，《太平廣記》卷一六八所載缺名氏。","）。"]', '["蛺蝶雙飞芍藥前，鴛鴦对浴芙蓉水。","（均见《錦鏽万花谷前集》卷十七。","）（按：鄭還古戀沈真真故事，见《侍兒小名錄》及《綠窗新話》卷上，《太平廣記》卷一六八所載缺名氏。","）。"]', '诗', 'shi', '', NULL, '真真歌 二 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('410ff725-bc31-47e2-90bb-469b079bff2a', '棗', '棗', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["雨顆青璣密，風香白雪翻。","（見《剡錄》卷十。","）。"]', '["雨顆青璣密，风香白雪翻。","（见《剡錄》卷十。","）。"]', '诗', 'shi', '', NULL, '棗 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('775b1530-4a6f-417d-bc21-6f3dc1660618', '牡丹', '牡丹', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["紅開西子粧樓曉，翠揭麻姑水殿春。","（見《苕溪漁隱叢話前集》卷二七引《陳輔之詩話》。","）。"]', '["紅开西子粧楼晓，翠揭麻姑水殿春。","（见《苕溪漁隐叢話前集》卷二七引《陳輔之诗話》。","）。"]', '诗', 'shi', '', NULL, '牡丹 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e8a9541c-5e1f-4fe1-af32-97eba2504437', '十二月三臺詞（新） 一', '十二月三台词（新） 一', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["正月年首初春，[□□]（郭沫若補「萬戶」二字）改故迎新。","李玄（郭改「理絃」，非是）附靈（郭改「撫琴」，非是）求學，樹[下]（夏）乃[逢子]（二字原模糊，從龍晦、任半塘說寫定）珍（郭沫若補以上三字爲「調銀箏」）。","項託七歲知事（郭沫若定爲「書」字），其羅十二[相]（〖想〗從郭沫若說改）。","[若]（從郭說增）無良妻解夢，馮唐寧得忠[臣]（（辰）從郭說改）。"]', '["正月年首初春，[□□]（郭沫若補「万戶」二字）改故迎新。","李玄（郭改「理絃」，非是）附靈（郭改「撫琴」，非是）求学，樹[下]（夏）乃[逢子]（二字原模糊，從龙晦、任半塘说寫定）珍（郭沫若補以上三字爲「調銀箏」）。","項託七歲知事（郭沫若定爲「书」字），其羅十二[相]（〖想〗從郭沫若说改）。","[若]（從郭说增）無良妻解梦，馮唐寧得忠[臣]（（辰）從郭说改）。"]', '诗', 'shi', '', NULL, '十二月三臺詞（新） 一 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e7523840-591e-463b-acfe-a9a229af7765', '十二月三臺詞（新） 二', '十二月三台词（新） 二', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["二月遙望梅林，青條吐葉（下缺）。","以上均錄自郭沫若《出土文物二三事》卷首附一九六九年吐魯番阿斯塔那唐墓出土卜天壽抄本《論語鄭氏注》卷末詩詞照片。","原詩有缺訛，從郭沫若《卜天壽〈論語〉抄本後的詩詞雜錄》、龍晦《卜天壽〈論語〉抄本後的詩詞雜錄研究和校釋》、任半塘《唐聲詩》下編校改。"]', '["二月遙望梅林，青條吐葉（下缺）。","以上均錄自郭沫若《出土文物二三事》卷首附一九六九年吐魯番阿斯塔那唐墓出土卜天壽抄本《論語鄭氏注》卷末诗词照片。","原诗有缺訛，從郭沫若《卜天壽〈論語〉抄本後的诗词杂錄》、龙晦《卜天壽〈論語〉抄本後的诗词杂錄研究和校釋》、任半塘《唐声诗》下編校改。"]', '诗', 'shi', '', NULL, '十二月三臺詞（新） 二 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('50c4453d-7b8b-413a-a6dd-058158f3e483', '五言詩四首 一', '五言诗四首 一', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["[百]（伯）鳥[投]（頭）林宿，各各覓高[枝]（支）。","[五]更分散去，苦[樂]（落）不[相]（想）知。"]', '["[百]（伯）鸟[投]（头）林宿，各各覓高[枝]（支）。","[五]更分散去，苦[乐]（落）不[相]（想）知。"]', '诗', 'shi', '', NULL, '五言詩四首 一 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4f39d8d8-2d00-41e6-b007-84ecd2d14183', '五言詩四首 二', '五言诗四首 二', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["日落西山[下]（夏），[黃]（潢）河東海流。","人[生]不滿百，恒作萬年[憂]（優）。","（以上二首均從郭沫若說校改。","）。"]', '["日落西山[下]（夏），[黄]（潢）河东海流。","人[生]不满百，恒作万年[憂]（優）。","（以上二首均從郭沫若说校改。","）。"]', '诗', 'shi', '', NULL, '五言詩四首 二 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0842c8f2-383e-4d04-ae85-a7c7eb048e79', '五言詩四首 三', '五言诗四首 三', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["高門出己子（郭沫若謂當作「傑子」，龍晦懷疑應爲「舉子」，《考古》曾刊一短文謂當作「杞梓」，作者及刊期皆失記），好木出良[材]（才）。","交□學[問]（敏）去，三公[何]（河）處來？","（後三處皆從郭沫若說改。","）。"]', '["高门出己子（郭沫若謂當作「傑子」，龙晦懷疑應爲「舉子」，《考古》曾刊一短文謂當作「杞梓」，作者及刊期皆失記），好木出良[材]（才）。","交□学[问]（敏）去，三公[何]（河）处来？","（後三处皆從郭沫若说改。","）。"]', '诗', 'shi', '', NULL, '五言詩四首 三 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f6fd86c2-2a28-4f80-9745-c43aaa1b3596', '五言詩四首 四', '五言诗四首 四', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["學問非今日，[唯]（〖維〗從龍晦說改）須[積]（迹）年多。","[□]（郭沫若補「請」字）看[千澗]（阡蕳）水，萬合始[成]（城）河。","（後四字均從翮沫若說改。","以上四首，出處均同前。","）（按：卜天壽《論語》抄本後附抄五絕六首，郭沫若以爲僅第一首爲卜無法壽自作，龍晦則以爲第一、第五首皆出其自作。","除其自作之一二首外，餘皆係抄錄舊作，二家意見大致相同。","今收第一、第五兩首入本書卷四卜天壽，餘皆收於此。","）。"]', '["学问非今日，[唯]（〖維〗從龙晦说改）須[積]（迹）年多。","[□]（郭沫若補「請」字）看[千澗]（阡蕳）水，万合始[成]（城）河。","（後四字均從翮沫若说改。","以上四首，出处均同前。","）（按：卜天壽《論語》抄本後附抄五絕六首，郭沫若以爲僅第一首爲卜無法壽自作，龙晦則以爲第一、第五首皆出其自作。","除其自作之一二首外，餘皆係抄錄旧作，二家意见大致相同。","今收第一、第五兩首入本书卷四卜天壽，餘皆收於此。","）。"]', '诗', 'shi', '', NULL, '五言詩四首 四 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('38f535fe-157e-437e-b0c7-20619414bc40', '題三危聖王寺（題擬）（□因從台駕隨侍□政道舍□道真等七人就三危聖王寺安下霸道場記。維天福十五年五月八日遊記之耳。）', '題三危聖王寺（題擬）（□因從台駕隨侍□政道舍□道真等七人就三危聖王寺安下霸道場記。維天福十五年五月八日游記之耳。）', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["三危山內枲世賢，結此道場下停閑。","侍送門人往不絕，層是山谷水未寬。","一旬之間僧久住，感動山神賜霜樹。","□值牟尼威力重，此山本□住僧田。","（見敦煌莫高窟第一○八窟窟檐南壁外側題壁，據《敦煌莫高窟供養人題記》。","）。"]', '["三危山內枲世賢，結此道場下停闲。","侍送门人往不絕，層是山谷水未寬。","一旬之间僧久住，感动山神賜霜樹。","□值牟尼威力重，此山本□住僧田。","（见敦煌莫高窟第一○八窟窟檐南壁外側題壁，據《敦煌莫高窟供養人題記》。","）。"]', '诗', 'shi', '', NULL, '題三危聖王寺（題擬）（□因從台駕隨侍□政道舍□道真等七人就三危聖王寺安下霸道場記。維天福十五年五月八日遊記之耳。） 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0484ca2d-4e2f-403e-8f08-358d31f58a71', '裴公亭', '裴公亭', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["裴相亭成未退身，空煩舞袖與歌塵。","至今亭下蕭蕭竹，似對西風怨主人。","（見乾隆二十四年刊蕭應植纂《濟源縣志》卷十六。","）。"]', '["裴相亭成未退身，空煩舞袖與歌塵。","至今亭下蕭蕭竹，似对西风怨主人。","（见乾隆二十四年刊蕭應植纂《濟源縣志》卷十六。","）。"]', '诗', 'shi', '', NULL, '裴公亭 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('59007243-b8d8-4132-963e-8ca1c7234d06', '題王將軍', '題王將軍', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["東下王師勢若翔，吳人設險爲非常。","橫江鐵鎖成何用，反引將軍入武昌。","（見民國廿一年韓嘉會纂《閿鄉縣志·詩徵》。","）。"]', '["东下王師勢若翔，吳人設險爲非常。","橫江鐵鎖成何用，反引將軍入武昌。","（见民国廿一年韓嘉會纂《閿乡縣志·诗徵》。","）。"]', '诗', 'shi', '', NULL, '題王將軍 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cc0f1bee-8d4d-4816-8790-ca29683ae808', '宜城懷古', '宜城懷古', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["巍峨朱軒甲第稠，纓簪文武盡名流。","而今印纍千官塚，瓜圃何曾有故侯。"]', '["巍峨朱軒甲第稠，纓簪文武尽名流。","而今印纍千官塚，瓜圃何曾有故侯。"]', '诗', 'shi', '', NULL, '宜城懷古 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2394591e-ff44-4c8f-bc7a-12c3d8dea07f', '杜康臺 一', '杜康台 一', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["勒馬問樵夫，前村酒有无？","「杜康家在此，一任君來沽。","」。"]', '["勒马问樵夫，前村酒有无？","「杜康家在此，一任君来沽。","」。"]', '诗', 'shi', '', NULL, '杜康臺 一 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('79b73c12-e25f-443b-b74c-fcd134fdc71c', '杜康臺 二', '杜康台 二', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["逐鹿羣雄姓幾埋，杜君何得尚存臺。","醉鄉另有乾坤在，那見糟丘付劫灰。","（以上三首均見同治五年刊張炳鐘纂《宜城縣志》卷九。","）。"]', '["逐鹿羣雄姓幾埋，杜君何得尚存台。","醉乡另有乾坤在，那见糟丘付劫灰。","（以上三首均见同治五年刊張炳鐘纂《宜城縣志》卷九。","）。"]', '诗', 'shi', '', NULL, '杜康臺 二 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a63fe0a0-7e65-46a8-a2d9-466c2357decd', '筠山虎', '筠山虎', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["筠山高極入穹蒼，人道虎爲殃。","人行過此不曾傷。","咸陽宮闕在平地，高鹿食人無所計，吁嗟苛政猛於虎，斯言垂萬古。","（見同治三年刊文良等修《嘉定府志》卷四十。","）。"]', '["筠山高極入穹蒼，人道虎爲殃。","人行過此不曾傷。","咸陽宮闕在平地，高鹿食人無所計，吁嗟苛政猛於虎，斯言垂万古。","（见同治三年刊文良等修《嘉定府志》卷四十。","）。"]', '诗', 'shi', '', NULL, '筠山虎 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c143b4c9-837e-4f16-a401-d3e39a9604a3', '題上高香山院', '題上高香山院', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["誰將萬斛旃檀子，撒向千春古道場。","萬壑曉風吹不斷，至今猶自滿山香。","（見《豫章詩話》卷二）。"]', '["誰將万斛旃檀子，撒向千春古道場。","万壑晓风吹不斷，至今猶自满山香。","（见《豫章诗話》卷二）。"]', '诗', 'shi', '', NULL, '題上高香山院 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a54b62a0-ef76-40dc-8f3d-b2f26817d24e', '劍津（題擬）', '劍津（題擬）', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["雙劍分二峽，萬古水溶溶。","邪氣夜常動，精靈日少逢。","（《輿地紀勝》卷一三三《南劍州》。","）。"]', '["雙劍分二峽，万古水溶溶。","邪氣夜常动，精靈日少逢。","（《輿地紀勝》卷一三三《南劍州》。","）。"]', '诗', 'shi', '', NULL, '劍津（題擬） 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('63be5eb1-d8d0-4a6f-82f6-a3bf306e86c8', '詠劍池', '詠劍池', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["劍去池空一水寒，遊人來此憑欄干。","世間萬事消息盡，只有青山好靜觀。","（見元蔡正孫《詩林廣記後集》卷三。","）。"]', '["劍去池空一水寒，游人来此憑欄干。","世间万事消息尽，只有青山好静观。","（见元蔡正孫《诗林廣記後集》卷三。","）。"]', '诗', 'shi', '', NULL, '詠劍池 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9984e345-4739-4d04-aa90-48d2f392302d', '桐廬金雞石', '桐廬金雞石', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["天上金雞石，何時墜此山。","祇因鳴有信，流落在人間。","（見清陶元藻《全浙詩話》卷六引《嚴州府志》。","）。"]', '["天上金雞石，何时墜此山。","祇因鳴有信，流落在人间。","（见清陶元藻《全浙诗話》卷六引《嚴州府志》。","）。"]', '诗', 'shi', '', NULL, '桐廬金雞石 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6d0c5889-2860-49e3-8f34-cb399bad79dd', '題大庾嶺（題擬）', '題大庾嶺（題擬）', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["大庾嶺上梅，南枝落，北枝開。","（見影印本京都大學人文科舉研究藏《永樂大典》卷六六五引《元一統志》引《白氏六帖》。","）。"]', '["大庾嶺上梅，南枝落，北枝开。","（见影印本京都大学人文科舉研究藏《永乐大典》卷六六五引《元一統志》引《白氏六帖》。","）。"]', '诗', 'shi', '', NULL, '題大庾嶺（題擬） 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('efe4a19e-22f8-4d34-a4f0-88939cb04ced', '題斷石源', '題斷石源', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["一酌丹華享萬齡，遊人競訪只聞聲。","那知坎井埋砂久，猶得全家壽幾生。"]', '["一酌丹华享万齡，游人競訪只闻声。","那知坎井埋砂久，猶得全家壽幾生。"]', '诗', 'shi', '', NULL, '題斷石源 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('46d26b93-3427-40da-b016-3e985f2c0952', '靈麓峰（題擬）', '靈麓峰（題擬）', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["玉洞仙壇長冷落，真墟巖竇色常新。","可憐城裏悠悠者，不識瀟湘四季春。"]', '["玉洞仙壇长冷落，真墟巖竇色常新。","可怜城裏悠悠者，不識瀟湘四季春。"]', '诗', 'shi', '', NULL, '靈麓峰（題擬） 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1573d41f-0835-4276-8831-e23f11383a46', '鳳凰峰', '鳳凰峰', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["文鳳集南嶽，徘徊竹孤根。","於心有不厭，奮翅凌紫雲。","豈不曾辛苦，羞與黃雀羣。","何時嘗來儀，順於聖明君。","（以上四首均見宋陳田夫《南嶽總勝集》卷上。","）。"]', '["文鳳集南嶽，徘徊竹孤根。","於心有不厭，奮翅凌紫云。","豈不曾辛苦，羞與黄雀羣。","何时嘗来儀，順於聖明君。","（以上四首均见宋陳田夫《南嶽總勝集》卷上。","）。"]', '诗', 'shi', '', NULL, '鳳凰峰 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('98120a58-1aa0-4902-ac01-88538f8be1c9', '洞靈宮（題擬）', '洞靈宮（題擬）', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["洞靈源接洞陽天，瘦（《沅湘耆舊集》卷十三作「疲」）壑危峰吐絳煙。","曾踏落花聽玉籟（《沅湘耆舊集》作「笛」），赤松壇畔鶴鳴泉。"]', '["洞靈源接洞陽天，瘦（《沅湘耆旧集》卷十三作「疲」）壑危峰吐絳煙。","曾踏落花听玉籟（《沅湘耆旧集》作「笛」），赤松壇畔鹤鳴泉。"]', '诗', 'shi', '', NULL, '洞靈宮（題擬） 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b5582544-7cb6-41ed-9693-beba5d5a6aa7', '詠九仙宮', '詠九仙宮', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["一峰鱗次開一觀，片石朋來會九仙。","寶牌尚記明皇篆，靈臺嘗聞御史傳。","（以上二首均見同書卷中。","）。"]', '["一峰鱗次开一观，片石朋来會九仙。","寶牌尚記明皇篆，靈台嘗闻御史傳。","（以上二首均见同书卷中。","）。"]', '诗', 'shi', '', NULL, '詠九仙宮 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e05cb0d5-3db3-4dcb-bf8d-06ce0f83d925', '鈷鉧潭', '鈷鉧潭', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["常聞南郭智，未識北山愚。","試問溪中水，潺潺只自如。","（見道光《永州府志》卷十八《金石略》、同治《湖南通志》卷二六四《金石》六。","）（按：詩後署「癸酉中冬既望日□□□□過永州□□」。","〖1〗《湖南通志》附引錢邦芑《遊記》疑爲柳子厚作，《嘉慶通志》以爲非柳作，「殆後人所題也」。","《金石補正》謂「以筆意審之，當是宋人所題」。","「詩句頗似邢恕，疑是元佑癸酉，然無可證，姑繫諸宋末，俟考。","」）。"]', '["常闻南郭智，未識北山愚。","試问溪中水，潺潺只自如。","（见道光《永州府志》卷十八《金石略》、同治《湖南通志》卷二六四《金石》六。","）（按：诗後署「癸酉中冬既望日□□□□過永州□□」。","〖1〗《湖南通志》附引錢邦芑《游記》疑爲柳子厚作，《嘉慶通志》以爲非柳作，「殆後人所題也」。","《金石補正》謂「以笔意審之，當是宋人所題」。","「诗句頗似邢恕，疑是元佑癸酉，然無可證，姑繫諸宋末，俟考。","」）。"]', '诗', 'shi', '', NULL, '鈷鉧潭 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c81a85f1-27e2-4a91-82ff-f857d06619cd', '福州烏石嶺無字碑古偈', '福州烏石嶺無字碑古偈', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["一片如屏紫翠間，風吹日炙蘚花斑。","莫言箇裏無文字，爲待高人著眼看。","（見《淳熙三山志》卷三四、《閩都記》卷二十二。","）。"]', '["一片如屏紫翠间，风吹日炙蘚花斑。","莫言箇裏無文字，爲待高人著眼看。","（见《淳熙三山志》卷三四、《閩都記》卷二十二。","）。"]', '诗', 'shi', '', NULL, '福州烏石嶺無字碑古偈 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('933524ea-0b17-46a8-8f3e-3afa29e3b56d', '羅浮山 一', '羅浮山 一', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["千徑嵐光濕不開，洞中樓閣鎖瓊瑰。","羅山萬仞雲中起，浮島一峰天外來。","五嶽神仙多往復，九霄鸞鶴自徘徊。","葛洪舊隱丹爐畔，掩映麻姑錦繍臺。"]', '["千徑嵐光濕不开，洞中楼閣鎖瓊瑰。","羅山万仞云中起，浮島一峰天外来。","五嶽神仙多往复，九霄鸾鹤自徘徊。","葛洪旧隐丹爐畔，掩映麻姑錦繍台。"]', '诗', 'shi', '', NULL, '羅浮山 一 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('076c8179-56f8-45b1-9769-4ab86550d8a7', '羅浮山 二', '羅浮山 二', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["玉殿朝元夜已深，二舌世界靜沉沉。","霏微紫氣通蓬島，浩蕩江風下寶林。","雲彩散爲天上綺，日華浮動水中金。","步虛聲斷一迴首，十二樓臺何處尋。","（見康熙乙酉刊李嗣珏纂《羅浮山志》卷一。","）。"]', '["玉殿朝元夜已深，二舌世界静沉沉。","霏微紫氣通蓬島，浩蕩江风下寶林。","云彩散爲天上綺，日华浮动水中金。","步虛声斷一迴首，十二楼台何处尋。","（见康熙乙酉刊李嗣珏纂《羅浮山志》卷一。","）。"]', '诗', 'shi', '', NULL, '羅浮山 二 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bb0bdf07-c8f5-46cf-ad47-8e05014dbe77', '題華嚴洞石壁', '題华嚴洞石壁', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["巖前流水無人渡，洞口碧桃花自開。","東望蓬萊三萬里，等閒歸去等閒來。","（錄自清汪森纂《粵西詩裁》卷二十二。","）。"]', '["巖前流水無人渡，洞口碧桃花自开。","东望蓬萊三万里，等閒归去等閒来。","（錄自清汪森纂《粵西诗裁》卷二十二。","）。"]', '诗', 'shi', '', NULL, '題華嚴洞石壁 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('36e5fbae-b745-49e5-b62f-6820db95346a', '謁聖林（題擬）', '謁聖林（題擬）', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["靈光殿古生秋草，曲阜城荒噪晚鵶。","惟有孔林殘照裏，至今猶屬仲尼家。","（見宋孔傳《東家雜記》卷下。","）（〖1〗《東家雜記》謂有唐以來謁林者必一一賦詩，而以此詩最爲絕唱。","孔宗翰幼時已聞人誦此詩，或云一詩僧留題，竟不知誰氏之作。","今按：此詩在蒱初既已流傳則當爲唐五代人作。","從詩意看，不會晚於宋初崇儒之際。","故敢入。","）。"]', '["靈光殿古生秋草，曲阜城荒噪晚鵶。","惟有孔林殘照裏，至今猶屬仲尼家。","（见宋孔傳《东家杂記》卷下。","）（〖1〗《东家杂記》謂有唐以来謁林者必一一賦诗，而以此诗最爲絕唱。","孔宗翰幼时已闻人誦此诗，或云一诗僧留題，竟不知誰氏之作。","今按：此诗在蒱初既已流傳則當爲唐五代人作。","從诗意看，不會晚於宋初崇儒之際。","故敢入。","）。"]', '诗', 'shi', '', NULL, '謁聖林（題擬） 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('00b46580-525d-4037-809c-968d596c1689', '南劍州古詩', '南劍州古诗', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["雙溪分二峽，萬古水溶溶。","彩氣衣常動，精靈日夕逢。","（《記纂淵海》卷十。","）。"]', '["雙溪分二峽，万古水溶溶。","彩氣衣常动，精靈日夕逢。","（《記纂淵海》卷十。","）。"]', '诗', 'shi', '', NULL, '南劍州古詩 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8500f7b1-8d00-4b91-9d7b-7b7ef2d67e8d', '化州郡守詩', '化州郡守诗', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["羅川帶郭古南州，陵水環城小庾州。","雲淡青山無過雁，雨涵丹荔集鳴鳩。","（同前卷十五。","云「郡守不知名氏」。","）。"]', '["羅川带郭古南州，陵水环城小庾州。","云淡青山無過雁，雨涵丹荔集鳴鳩。","（同前卷十五。","云「郡守不知名氏」。","）。"]', '诗', 'shi', '', NULL, '化州郡守詩 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6c22ed44-5556-467b-85d5-b7c02ee7c99a', '題合水縣玉泉詩 一', '題合水縣玉泉诗 一', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["山股逗飛泉，泓澄傍巖石。","亂垂寒玉條，碎灑珍珠滴。","（同前卷二四。","）。"]', '["山股逗飞泉，泓澄傍巖石。","亂垂寒玉條，碎灑珍珠滴。","（同前卷二四。","）。"]', '诗', 'shi', '', NULL, '題合水縣玉泉詩 一 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b6783b4c-b08f-4122-94ef-e8120efc1f9b', '題合水縣玉泉詩 二', '題合水縣玉泉诗 二', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["山川澗水河南流，邑治因名幾百秋。","（同前。","）。"]', '["山川澗水河南流，邑治因名幾百秋。","（同前。","）。"]', '诗', 'shi', '', NULL, '題合水縣玉泉詩 二 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5283bff0-e6b4-4418-93c2-7044c7793783', '題寧州泉', '題寧州泉', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["澄波涵萬象，明鏡瀉天色。","有時乘月來，賞詠還自適。","（同前）。"]', '["澄波涵万象，明镜瀉天色。","有时乘月来，賞詠還自適。","（同前）。"]', '诗', 'shi', '', NULL, '題寧州泉 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f4cc9412-58c7-49a1-8cb9-1f55a3c94668', '七言不全詩句石刻', '七言不全诗句石刻', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["一瓶寒水背書囊。","（見《安陽縣金石錄》卷四。","）（〖1〗《安陽縣金石錄》：「案《禹璜題名》上有不全詩句，第一行存『往』字，第二行存『石』字，存『』字，三行存『一瓶寒水）-（背書囊』七字，另行存『七言』字，蓋後人磨治。","書類歐陽率更，亦唐人佳刻也。","」按：《禹璜題名》在靈泉寺佛殿前西塔，咸通八年刻。","）。"]', '["一瓶寒水背书囊。","（见《安陽縣金石錄》卷四。","）（〖1〗《安陽縣金石錄》：「案《禹璜題名》上有不全诗句，第一行存『往』字，第二行存『石』字，存『』字，三行存『一瓶寒水）-（背书囊』七字，另行存『七言』字，蓋後人磨治。","书類歐陽率更，亦唐人佳刻也。","」按：《禹璜題名》在靈泉寺佛殿前西塔，咸通八年刻。","）。"]', '诗', 'shi', '', NULL, '七言不全詩句石刻 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0f068340-694f-4d71-834d-4fcb8aec8df5', '題狼山慈航院（題擬）', '題狼山慈航院（題擬）', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["飛來靈鷲嶺，化作寶陀山。","（見宋王闢之《澠水燕談錄》卷七。","）（〖1〗《澠水燕談錄》：「通州狼山廣教寺，在唐爲慈航院，在江中山上，昔人有詩云：〖略〗。","前後乃江海相接處，舟出二山間，水湍礙石，率多覆溺。","昔有僧率其徒，操楫以獲之，舟無觸石之患，故有慈航之名。","近年江水南徙，山之前後皆陸田，後人又有詩云：『昔年船底浪，今日馬蹄痕。","』皆紀實也。","」）。"]', '["飞来靈鷲嶺，化作寶陀山。","（见宋王闢之《澠水燕談錄》卷七。","）（〖1〗《澠水燕談錄》：「通州狼山廣教寺，在唐爲慈航院，在江中山上，昔人有诗云：〖略〗。","前後乃江海相接处，舟出二山间，水湍礙石，率多覆溺。","昔有僧率其徒，操楫以獲之，舟無觸石之患，故有慈航之名。","近年江水南徙，山之前後皆陸田，後人又有诗云：『昔年船底浪，今日马蹄痕。","』皆紀實也。","」）。"]', '诗', 'shi', '', NULL, '題狼山慈航院（題擬） 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('37c8e633-a1c2-4bc1-b093-397419db2781', '廬山詩', '廬山诗', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["簡寂觀中甜苦筍，歸宗寺裏淡鹹齏。","（見《廬山記》卷二。","）。"]', '["簡寂观中甜苦筍，归宗寺裏淡鹹齏。","（见《廬山記》卷二。","）。"]', '诗', 'shi', '', NULL, '廬山詩 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2e872745-2476-4223-a112-41add0aea643', '袁山', '袁山', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["袁山大小雙螺並，秀水東西一帶橫。","（見正德《袁州府志》卷一《山川》。","）。"]', '["袁山大小雙螺並，秀水东西一带橫。","（见正德《袁州府志》卷一《山川》。","）。"]', '诗', 'shi', '', NULL, '袁山 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cd3e55b0-a8ab-42b7-be21-cd6e3f4cc4cd', '題水簾洞', '題水簾洞', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["今古長垂地，晨昏不上鉤。","（見《嘉定赤城志》卷二十二。","）。"]', '["今古长垂地，晨昏不上鉤。","（见《嘉定赤城志》卷二十二。","）。"]', '诗', 'shi', '', NULL, '題水簾洞 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6c2ebf24-84d9-42d9-8f75-ed59cca182a0', '早行', '早行', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["主人燈下別，羸馬月中行。","（見《增修詩話總龜前集》卷八引《青瑣集》。","）。"]', '["主人灯下別，羸马月中行。","（见《增修诗話總龟前集》卷八引《青瑣集》。","）。"]', '诗', 'shi', '', NULL, '早行 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d4f5a81a-ee6f-41c6-9acd-2df2f99701b9', '題圓超寺俯山堂', '題圓超寺俯山堂', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["近離城市不多地，高壓樓臺無限家。","（見《輿地紀勝》卷十《紹興府》引昔人詩，列錢倧前。","）。"]', '["近離城市不多地，高壓楼台無限家。","（见《輿地紀勝》卷十《紹兴府》引昔人诗，列錢倧前。","）。"]', '诗', 'shi', '', NULL, '題圓超寺俯山堂 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('79c2fee2-930b-445f-8da6-b4b6eab625b5', '池州（題擬）', '池州（題擬）', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["閑行池口江邊路，看盡江南岸上山。","（同前書卷二十二引古詩。","）。"]', '["闲行池口江邊路，看尽江南岸上山。","（同前书卷二十二引古诗。","）。"]', '诗', 'shi', '', NULL, '池州（題擬） 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('82b5a04b-210e-481e-bb5c-c3806cbbbc5e', '直瀆（題擬）', '直瀆（題擬）', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["虛開直瀆三千里，青蓋何曾到洛陽。","（時前書卷十九《宣城》引《宣城志》。","）。"]', '["虛开直瀆三千里，青蓋何曾到洛陽。","（时前书卷十九《宣城》引《宣城志》。","）。"]', '诗', 'shi', '', NULL, '直瀆（題擬） 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3a487a21-0ac3-49fa-b44c-1fc30bd06723', '潛皖二水（題擬）', '潛皖二水（題擬）', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["玉光白橘香爭秀，金翠嘉蓮蘂鬬開。","（同前書卷四世六《安慶府》引古詩。","）。"]', '["玉光白橘香爭秀，金翠嘉蓮蘂鬬开。","（同前书卷四世六《安慶府》引古诗。","）。"]', '诗', 'shi', '', NULL, '潛皖二水（題擬） 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('47daa6db-3965-4790-a24b-b06b65fc7b47', '玉鏡山（題擬）', '玉镜山（題擬）', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["主簿山高難見日，玉鏡峰前易曉人。","（見同書同卷引唐僧詩。","）。"]', '["主簿山高难见日，玉镜峰前易晓人。","（见同书同卷引唐僧诗。","）。"]', '诗', 'shi', '', NULL, '玉鏡山（題擬） 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5a759031-d06a-45ac-ad20-51f136c1780d', '天柱峰（題擬）', '天柱峰（題擬）', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["三十六峰藏好景，更於何處覓瀛洲？（同前）。"]', '["三十六峰藏好景，更於何处覓瀛洲？（同前）。"]', '诗', 'shi', '', NULL, '天柱峰（題擬） 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bd8074e8-c78e-4c49-98cf-5751091ac6c4', '岳陽樓（題擬）', '岳陽楼（題擬）', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["洞庭八百里，幕阜三千尋。","（見同書卷六九《岳州》引古詩，原列唐人間。","岳陽樓始建於唐時。","）。"]', '["洞庭八百里，幕阜三千尋。","（见同书卷六九《岳州》引古诗，原列唐人间。","岳陽楼始建於唐时。","）。"]', '诗', 'shi', '', NULL, '岳陽樓（題擬） 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5a58b2ee-9cf2-4c58-8517-8b16086ec363', '白洞灘（題擬）', '白洞灘（題擬）', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["灘頭白洞空相待。","（見同書卷七四《歸州》引《晏公類要》引古詩。","）。"]', '["灘头白洞空相待。","（见同书卷七四《归州》引《晏公類要》引古诗。","）。"]', '诗', 'shi', '', NULL, '白洞灘（題擬） 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fe96c0a9-bac4-444a-89ac-9da9cdc22b94', '小酉洞（題擬）', '小酉洞（題擬）', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["山留盤瓠亦（此字疑爲「迹」字之誤），洞有秦人書。","（見同書卷七五《辰州》引《晏公類要》引。","）。"]', '["山留盤瓠亦（此字疑爲「迹」字之誤），洞有秦人书。","（见同书卷七五《辰州》引《晏公類要》引。","）。"]', '诗', 'shi', '', NULL, '小酉洞（題擬） 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6b4b8274-7679-4061-84d6-38bf0558039a', '犍爲（題擬）', '犍爲（題擬）', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["犍爲古佳郡，山水宜不惡。","（見同書卷一四六《嘉定府》引。","）。"]', '["犍爲古佳郡，山水宜不惡。","（见同书卷一四六《嘉定府》引。","）。"]', '诗', 'shi', '', NULL, '犍爲（題擬） 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('883d8879-c1eb-478e-948f-e95bf4217072', '黔州（題擬）', '黔州（題擬）', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["不到施黔不見山。","（見同書卷一七六《黔州》引《澧州圖經》詩。","《澧州圖經》爲宋初修。","）。"]', '["不到施黔不见山。","（见同书卷一七六《黔州》引《澧州圖經》诗。","《澧州圖經》爲宋初修。","）。"]', '诗', 'shi', '', NULL, '黔州（題擬） 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('533d1336-e617-4494-ae94-da11fef7847c', '過壁山', '過壁山', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["今日壁山山下路，依前馬上看梨花。","（同前書卷一八七《也州》。","）。"]', '["今日壁山山下路，依前马上看梨花。","（同前书卷一八七《也州》。","）。"]', '诗', 'shi', '', NULL, '過壁山 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0b32eec7-4335-4fcb-b1c9-ccf91caea37d', '牓詩', '牓诗', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["員外欲題銓裏牓，尚書不得數中分。","（見《唐會要》卷七四。","）。"]', '["員外欲題銓裏牓，尚书不得數中分。","（见《唐會要》卷七四。","）。"]', '诗', 'shi', '', NULL, '牓詩 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('89b973d1-2a77-4f2b-ad87-15833d8f8352', '食筍詩', '食筍诗', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["稚子脫錦䙀，駢頭玉香滑。","（見《甕牖閑評》卷五、《孔氏談苑》卷五、《五總志》。","）。"]', '["稚子脫錦䙀，駢头玉香滑。","（见《甕牖闲評》卷五、《孔氏談苑》卷五、《五總志》。","）。"]', '诗', 'shi', '', NULL, '食筍詩 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7f16b112-2006-4c85-ae63-5f5cf0c7b609', '弔子美', '弔子美', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["賦出《三都》上，詩須二雅求。","（見《苕溪漁隱叢話前集》卷十四引《西清詩話》。","）。"]', '["賦出《三都》上，诗須二雅求。","（见《苕溪漁隐叢話前集》卷十四引《西清诗話》。","）。"]', '诗', 'shi', '', NULL, '弔子美 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('204cfe70-985d-45ad-9fec-4577aaafbcb7', '句 一', '句 一', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["相識滿天下，知心能幾人？","（見《宗鏡錄》卷二六引昔人詩。","）。"]', '["相識满天下，知心能幾人？","（见《宗镜錄》卷二六引昔人诗。","）。"]', '诗', 'shi', '', NULL, '句 一 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('319f6030-1ad3-4523-b7e1-aad087731405', '句 二', '句 二', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["書空翹足睡，路險側身行。","（見《桂苑叢談》引先達詩。","）。"]', '["书空翹足睡，路險側身行。","（见《桂苑叢談》引先達诗。","）。"]', '诗', 'shi', '', NULL, '句 二 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('846345d3-12f4-4640-a1d5-423d20c2ad56', '句 三', '句 三', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["山僧不解數甲子，一葉落知天下秋。","（見《唐子西文錄》引。","）。"]', '["山僧不解數甲子，一葉落知天下秋。","（见《唐子西文錄》引。","）。"]', '诗', 'shi', '', NULL, '句 三 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ba925592-7d8f-4cc8-80e1-e713a7ba8567', '句 四', '句 四', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["隔簾歌已俊，對坐貌彌精。","（見《東坡題跋》卷二、《仇池筆記》卷上。","）（按：此二句見於蘇子美家藏張長史書，蘇軾以爲亞棲之流作。","）。"]', '["隔簾歌已俊，对坐貌彌精。","（见《东坡題跋》卷二、《仇池笔記》卷上。","）（按：此二句见於蘇子美家藏張长史书，蘇軾以爲亞棲之流作。","）。"]', '诗', 'shi', '', NULL, '句 四 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f369bcb1-31be-4ee1-a7b5-0a3010a28bc5', '秋分夜夕月樂章 降神奏元和之舞六變', '秋分夜夕月乐章 降神奏元和之舞六变', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["月以陰德，自西而生。","積水之氣，作金之精。","麗天成像，配日爲明。","三光顯耀，萬古作成。","（《大唐郊祀錄》卷六。","）。"]', '["月以陰德，自西而生。","積水之氣，作金之精。","丽天成像，配日爲明。","三光显耀，万古作成。","（《大唐郊祀錄》卷六。","）。"]', '诗', 'shi', '', NULL, '秋分夜夕月樂章 降神奏元和之舞六變 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d9d6ea1b-f3ce-48d6-8f9d-0711ed09c3fd', '秋分夜夕月樂章 登歌奏肅和', '秋分夜夕月乐章 登歌奏肅和', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["測妙爲神，通微曰聖。","坎祀貽則，郊禮展敬。","璧薦登光，金枝動映。","以載佳德，以流曾慶。","（同前。","）。"]', '["測妙爲神，通微曰聖。","坎祀貽則，郊禮展敬。","璧薦登光，金枝动映。","以載佳德，以流曾慶。","（同前。","）。"]', '诗', 'shi', '', NULL, '秋分夜夕月樂章 登歌奏肅和 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d1b286cd-a3d5-4477-ae35-ff9897d2e65f', '葉法善掘地得古曲几上十八字歌（題擬）', '葉法善掘地得古曲几上十八字歌（題擬）', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["歲年永悲，羽翼殆歸，哀哉罹殃苦，令我不得飛。","（見《太平廣記》卷七十七引佚名《廣德神異錄》）。"]', '["歲年永悲，羽翼殆归，哀哉罹殃苦，令我不得飞。","（见《太平廣記》卷七十七引佚名《廣德神異錄》）。"]', '诗', 'shi', '', NULL, '葉法善掘地得古曲几上十八字歌（題擬） 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2dcc7d9d-561b-4567-8e84-46364eaf47e7', '有神降於鄭繹（《說郛》作「浠」、《古今說海》作「洚」）家吟詩', '有神降於鄭繹（《说郛》作「浠」、《古今说海》作「洚」）家吟诗', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["忽然湖上片雲飛，不覺舟中雨濕衣。","折得蓮花渾忘却，空將荷葉蓋頭歸。","（見《類說》卷八、《說郛》卷四及《古今說海》本戴孚《廣異記》）。"]', '["忽然湖上片云飞，不覺舟中雨濕衣。","折得蓮花渾忘却，空將荷葉蓋头归。","（见《類说》卷八、《说郛》卷四及《古今说海》本戴孚《廣異記》）。"]', '诗', 'shi', '', NULL, '有神降於鄭繹（《說郛》作「浠」、《古今說海》作「洚」）家吟詩 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('389411e6-aa5a-4b49-a399-803191d60373', '任昇之五代祖仕梁於鐘山懸岸圮壙中得古銘', '任昇之五代祖仕梁於鐘山懸岸圮壙中得古銘', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["龜言土，蓍言水，甸服黃鐘啓靈趾。","瘞在三上庚，墮遇七中巳。","六千三百浹辰交，二九重三四百圮。","（見《太平廣記》卷三九一引李吉甫《梁大同古銘記》）（按：《全唐詩》卷八七五收《京西市放生池墓銘》，與此首二句同，「土」作「市」。","李吉甫書名，從程毅中《古小說簡目》說。","）。"]', '["龟言土，蓍言水，甸服黄鐘啓靈趾。","瘞在三上庚，墮遇七中巳。","六千三百浹辰交，二九重三四百圮。","（见《太平廣記》卷三九一引李吉甫《梁大同古銘記》）（按：《全唐诗》卷八七五收《京西市放生池墓銘》，與此首二句同，「土」作「市」。","李吉甫书名，從程毅中《古小说簡目》说。","）。"]', '诗', 'shi', '', NULL, '任昇之五代祖仕梁於鐘山懸岸圮壙中得古銘 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('837f6bca-0d5c-46a3-90c4-99e9207af1df', '壸隱仙人吟詩', '壸隐仙人吟诗', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["杯賢與杓聖，與我萬戶封。","（見《說郛》{冫弓}三二引佚名《樹萱錄》）。"]', '["杯賢與杓聖，與我万戶封。","（见《说郛》{冫弓}三二引佚名《樹萱錄》）。"]', '诗', 'shi', '', NULL, '壸隱仙人吟詩 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5871da3f-fc57-4091-a666-7ce708f4b8eb', '陳蔡女鬼與長孫紹祖歌（題擬） 一', '陳蔡女鬼與长孫紹祖歌（題擬） 一', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["宿昔相思苦，今宵良會稀。","欲持留客被，一願拂君衣。"]', '["宿昔相思苦，今宵良會稀。","欲持留客被，一願拂君衣。"]', '诗', 'shi', '', NULL, '陳蔡女鬼與長孫紹祖歌（題擬） 一 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('948e2125-90b9-4d7f-9b8a-f18eae18c9c6', '陳蔡女鬼與長孫紹祖歌（題擬） 二', '陳蔡女鬼與长孫紹祖歌（題擬） 二', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["星漢縱復斜，風霜悽已切。","薄陳君不御，誰知思欲絕。","（見《太平廣記》卷三二六引《志怪錄》）（按：六朝人所著小說以《志怪》爲書名者有多種，魯迅輯入《古小說鈎沉》，不錄此條。","長孫爲塞北胡姓，似不應見於南朝小說中，宋朱翌《猗覺寮雜記》卷上引張薦《靈怪集》，有東蔡女鬼與裴紹祖詩二句：「橫陳君不御，惟知思不絕。","」疑《廣記》所注書名有誤。","）。"]', '["星漢縱复斜，风霜悽已切。","薄陳君不御，誰知思欲絕。","（见《太平廣記》卷三二六引《志怪錄》）（按：六朝人所著小说以《志怪》爲书名者有多種，魯迅輯入《古小说鈎沉》，不錄此條。","长孫爲塞北胡姓，似不應见於南朝小说中，宋朱翌《猗覺寮杂記》卷上引張薦《靈怪集》，有东蔡女鬼與裴紹祖诗二句：「橫陳君不御，惟知思不絕。","」疑《廣記》所注书名有誤。","）。"]', '诗', 'shi', '', NULL, '陳蔡女鬼與長孫紹祖歌（題擬） 二 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a7a3563f-1e3c-4cf0-a5f3-603fb2c2d24d', '滕庭俊自歎吟詩', '滕庭俊自歎吟诗', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["爲客多苦辛（一作「辛苦」），日暮無主人。"]', '["爲客多苦辛（一作「辛苦」），日暮無主人。"]', '诗', 'shi', '', NULL, '滕庭俊自歎吟詩 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9bf1a5ea-d2bb-47ea-8fdd-eee760bc283b', '滕庭俊遇麻大和且耶作詩（題擬）', '滕庭俊遇麻大和且耶作诗（題擬）', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["田文稱好客，凡養幾多人。","如欠馮諼在，今希廁下賓。","（以上二題見《太平廣記》卷四七四引牛僧孺《玄怪錄》）（按：麻大、和且耶爲大蒼蠅、禿掃帚。","《全唐詩》卷八六七已收二怪詩及故事梗概。","）。"]', '["田文稱好客，凡養幾多人。","如欠馮諼在，今希廁下賓。","（以上二題见《太平廣記》卷四七四引牛僧孺《玄怪錄》）（按：麻大、和且耶爲大蒼蠅、禿掃帚。","《全唐诗》卷八六七已收二怪诗及故事梗概。","）。"]', '诗', 'shi', '', NULL, '滕庭俊遇麻大和且耶作詩（題擬） 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f52784f0-a2bd-4b1e-91a9-c197a25a55f3', '柳歸舜聞君山鸚鵡所唱歌詩（題） 一', '柳归舜闻君山鸚鵡所唱歌诗（題） 一', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["戴蟬兒，分明傳與君王語。","建章殿裏未得歸，朱箔金缸雙鳳舞。","（唱歌者云此曲是漢武鉤弋夫人常所唱）。"]', '["戴蟬兒，分明傳與君王語。","建章殿裏未得归，朱箔金缸雙鳳舞。","（唱歌者云此曲是漢武鉤弋夫人常所唱）。"]', '诗', 'shi', '', NULL, '柳歸舜聞君山鸚鵡所唱歌詩（題） 一 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f335fad0-6233-4e4a-a109-5828a32dbb13', '柳歸舜聞君山鸚鵡所唱歌詩（題） 二', '柳归舜闻君山鸚鵡所唱歌诗（題） 二', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["昔請司馬相如（此句疑衍「司」字），爲作《長門賦》，徒使費百金，君王終不顧。","（阿蘇兒云此爲阿嬌深宮下涙唱者。","）。"]', '["昔請司马相如（此句疑衍「司」字），爲作《长门賦》，徒使費百金，君王終不顧。","（阿蘇兒云此爲阿嬌深宮下涙唱者。","）。"]', '诗', 'shi', '', NULL, '柳歸舜聞君山鸚鵡所唱歌詩（題） 二 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a7948dad-8a75-440e-88d9-eb6fd96e57b5', '柳歸舜聞君山鸚鵡所唱歌詩（題） 三', '柳归舜闻君山鸚鵡所唱歌诗（題） 三', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["顧鄙賤，奉恩私。","願吾君，萬歲期。","（武遊郎云此爲李夫人隨漢武帝時歌。","）。"]', '["顧鄙賤，奉恩私。","願吾君，万歲期。","（武游郎云此爲李夫人隨漢武帝时歌。","）。"]', '诗', 'shi', '', NULL, '柳歸舜聞君山鸚鵡所唱歌詩（題） 三 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f4fd1b6f-b03d-4dc3-ac50-84d1a44e20d1', '柳歸舜聞君山鸚鵡所唱歌詩（題） 四', '柳归舜闻君山鸚鵡所唱歌诗（題） 四', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["露接朝陽生，海波翻水晶。","玉樓間寥廓，天地相照明。","此時下棲止，投跡依舊楹。","顧余復何忝，自（一作「日」）侍羣仙行。","（鳳花臺云此爲昨過蓬萊玉樓所作詩。","以上四首，均見程毅中點校本《玄怪錄》卷二，《太平廣記》卷十八引作《續玄怪錄》。","）（〖1〗《玄怪錄》：吳興柳歸舜，隋開皇九年自巴陵泛舟，遇風吹至君山，因維舟登岸，行數里，忽道旁有一大石，石中央又生一樹，有鸚鵡數千，翱翔其間，相呼姓字，有名阿蘇兒、武遊郎、鳳花臺等名者。","相互唱歌吟詩，又與歸舜相問對。","後歸舜得二道士指點，方達分所。","後再尋訪，不復見也。","〖節錄大意〗）。"]', '["露接朝陽生，海波翻水晶。","玉楼间寥廓，天地相照明。","此时下棲止，投跡依旧楹。","顧余复何忝，自（一作「日」）侍羣仙行。","（鳳花台云此爲昨過蓬萊玉楼所作诗。","以上四首，均见程毅中点校本《玄怪錄》卷二，《太平廣記》卷十八引作《續玄怪錄》。","）（〖1〗《玄怪錄》：吳兴柳归舜，隋开皇九年自巴陵泛舟，遇风吹至君山，因維舟登岸，行數里，忽道旁有一大石，石中央又生一樹，有鸚鵡數千，翱翔其间，相呼姓字，有名阿蘇兒、武游郎、鳳花台等名者。","相互唱歌吟诗，又與归舜相问对。","後归舜得二道士指点，方達分所。","後再尋訪，不复见也。","〖節錄大意〗）。"]', '诗', 'shi', '', NULL, '柳歸舜聞君山鸚鵡所唱歌詩（題） 四 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1daf7ff8-41bc-4105-b9bf-fc4ad9782ee5', '顧總見劉楨卒後詩題目曰從駕遊幽麗（一作「厲」）宮却憶平生西園文會因寄修文府正郎蔡伯喈（題擬）', '顧總见劉楨卒後诗題目曰從駕游幽丽（一作「厲」）宮却憶平生西园文會因寄修文府正郎蔡伯喈（題擬）', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["在漢絕綱紀，溟瀆多騰[湍]（濡）。","煌煌魏世祖，拯溺靜波瀾。","天紀已垂定，邦人亦保完。","大開相公府，掇拾盡幽蘭。","始從衆君子，日侍[賢]（冥）主歡。","[文]（天）皇在共宮，烝孝踰問安。","監撫多餘閑，園囿恣遊觀。","末臣戴簪筆，翊聖從和鸞（一作「鑾」）。","月出行殿涼，珍[木]（水）清露漙。","天文信輝麗，鏗鏘[振]（枕）琅玕。","被[命]（中）仰[爲]（微）和，[顧己誠所難]（顧征成所難）。","弱質不自持，危脆朽萎殘。","豈意十餘年，陵寢梧[楸]（潄）寒。","今朝坤明國，[再]（弄）顧簪蟬冠。","侍遊于離宮，高躡浮雲端。","却憶西跳時，生死暫悲酸。","君昔漢公卿，未央冠羣賢。","倘若念平生，覽此同愴然。"]', '["在漢絕綱紀，溟瀆多腾[湍]（濡）。","煌煌魏世祖，拯溺静波瀾。","天紀已垂定，邦人亦保完。","大开相公府，掇拾尽幽蘭。","始從衆君子，日侍[賢]（冥）主歡。","[文]（天）皇在共宮，烝孝踰问安。","監撫多餘闲，园囿恣游观。","末臣戴簪笔，翊聖從和鸾（一作「鑾」）。","月出行殿涼，珍[木]（水）清露漙。","天文信輝丽，鏗鏘[振]（枕）琅玕。","被[命]（中）仰[爲]（微）和，[顧己誠所难]（顧征成所难）。","弱質不自持，危脆朽萎殘。","豈意十餘年，陵寢梧[楸]（潄）寒。","今朝坤明国，[再]（弄）顧簪蟬冠。","侍游于離宮，高躡浮云端。","却憶西跳时，生死暫悲酸。","君昔漢公卿，未央冠羣賢。","倘若念平生，覽此同愴然。"]', '诗', 'shi', '', NULL, '顧總見劉楨卒後詩題目曰從駕遊幽麗（一作「厲」）宮却憶平生西園文會因寄修文府正郎蔡伯喈（題擬） 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('11f11e47-5bbd-49eb-8cf9-bcd303b860a7', '徐幹對顧總誦劉楨小娘子嬌羞奉憶詩（題擬）', '徐幹对顧總誦劉楨小娘子嬌羞奉憶诗（題擬）', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["憶爺[爺]，拋女不歸家，不能作侍中，爲小吏，就辛苦，棄榮華，願爺想念早相見，與兒買李市甘瓜。","。"]', '["憶爺[爺]，拋女不归家，不能作侍中，爲小吏，就辛苦，棄榮华，願爺想念早相见，與兒買李市甘瓜。","。"]', '诗', 'shi', '', NULL, '徐幹對顧總誦劉楨小娘子嬌羞奉憶詩（題擬） 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7a7d2d63-de8a-47b3-acda-db830585db16', '總聞詩涕泗交下爲一章寄嬌羞娘子（題擬）', '總闻诗涕泗交下爲一章寄嬌羞娘子（題擬）', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["憶兒貌，念兒心，望兒不見涙沾襟。","時殊世異難相見，棄謝此生當訪尋。","（以上三首均見程毅中校點本《玄怪錄》卷二。","異文及改動均係程氏據《太平廣記》卷三二七校改。","（〖1〗《玄怪錄》云：梁天監元年，顧總爲縣吏，數被鞭捶，因逃墟墓間。","遇二黃衣，自稱爲王粲、徐幹，謂總生前是劉楨，並出楨卒後所爲詩。","幹復述楨女嬌羞娘憶父詞，總感而作一章以寄。","既別，持楨卒後詩見縣宰，宰待以賓禮。","後不知總所在。","〖節錄大概〗）。"]', '["憶兒貌，念兒心，望兒不见涙沾襟。","时殊世異难相见，棄謝此生當訪尋。","（以上三首均见程毅中校点本《玄怪錄》卷二。","異文及改动均係程氏據《太平廣記》卷三二七校改。","（〖1〗《玄怪錄》云：梁天監元年，顧總爲縣吏，數被鞭捶，因逃墟墓间。","遇二黄衣，自稱爲王粲、徐幹，謂總生前是劉楨，並出楨卒後所爲诗。","幹复述楨女嬌羞娘憶父词，總感而作一章以寄。","既別，持楨卒後诗见縣宰，宰待以賓禮。","後不知總所在。","〖節錄大概〗）。"]', '诗', 'shi', '', NULL, '總聞詩涕泗交下爲一章寄嬌羞娘子（題擬） 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2da01daf-0ba8-457e-bff9-7815d0a200d5', '袁誇郎遇仙詩 袁誇郎清夜長吟（題擬）', '袁誇郎遇仙诗 袁誇郎清夜长吟（題擬）', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["露濕寒塘草，月映清淮流。"]', '["露濕寒塘草，月映清淮流。"]', '诗', 'shi', '', NULL, '袁誇郎遇仙詩 袁誇郎清夜長吟（題擬） 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('273eb40f-3415-4f7e-8c8a-621a733c93cc', '袁誇郎遇仙詩 翡翠婢詠封郎春詩', '袁誇郎遇仙诗 翡翠婢詠封郎春诗', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["花落也，蛺蝶舞。","人何多疾，吁足憂苦。"]', '["花落也，蛺蝶舞。","人何多疾，吁足憂苦。"]', '诗', 'shi', '', NULL, '袁誇郎遇仙詩 翡翠婢詠封郎春詩 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('50921114-65ed-4032-82bf-9bc579d4b9bb', '袁誇郎遇仙詩 袁誇郎作催妝詩', '袁誇郎遇仙诗 袁誇郎作催妝诗', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["好花本自有春暉，不偶紅妝亂玉姿。","若用何郎面上粉，任將多少借光儀。"]', '["好花本自有春暉，不偶紅妝亂玉姿。","若用何郎面上粉，任將多少借光儀。"]', '诗', 'shi', '', NULL, '袁誇郎遇仙詩 袁誇郎作催妝詩 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9eb81fa9-9e8d-4b6c-b7c4-9d77c410820f', '袁誇郎遇仙詩 誇郎詠花扇詩', '袁誇郎遇仙诗 誇郎詠花扇诗', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["團扇畫方新，金花照錦茵。","那言燈下見，更值月中人。"]', '["團扇畫方新，金花照錦茵。","那言灯下见，更值月中人。"]', '诗', 'shi', '', NULL, '袁誇郎遇仙詩 誇郎詠花扇詩 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f9cb9c82-9f7b-4682-9ef7-98e5e771b653', '袁誇郎遇仙詩 王二十七郎贈袁郎詩', '袁誇郎遇仙诗 王二十七郎贈袁郎诗', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["人家女美大須愁，往往醜郎門外求。"]', '["人家女美大須愁，往往醜郎门外求。"]', '诗', 'shi', '', NULL, '袁誇郎遇仙詩 王二十七郎贈袁郎詩 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9a97f499-2d54-45b9-8082-fb131aab45b2', '袁誇郎遇仙詩 誇郎贈封平仲詩', '袁誇郎遇仙诗 誇郎贈封平仲诗', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["寶匣開玉琴，高梧追煩暑。","商絃一以發，白雲飄然舉。","何必蒼梧東，激情懷怨浦。","（見程毅中校本《玄怪錄》卷四。","（〖1〗《玄怪錄》：陳朱崖太守袁洪兒，小名誇郎，年二十，羅得翠翠鳥，鳥化爲一婢，又結識封郎平仲。","次日往訪封郎，至一處賓館宏敞，窮極瑰寶。","復識王氏兄弟，又與封氏姨成婚。","衆人吟詩鼓琴，誇郎遂無歸思。","奚諸人云他徙，迴顧已無一物。","誇郎數月猶惝恍，終歲乃如故。","〖節錄大意〗）。"]', '["寶匣开玉琴，高梧追煩暑。","商絃一以發，白云飄然舉。","何必蒼梧东，激情懷怨浦。","（见程毅中校本《玄怪錄》卷四。","（〖1〗《玄怪錄》：陳朱崖太守袁洪兒，小名誇郎，年二十，羅得翠翠鸟，鸟化爲一婢，又結識封郎平仲。","次日往訪封郎，至一处賓館宏敞，窮極瑰寶。","复識王氏兄弟，又與封氏姨成婚。","衆人吟诗鼓琴，誇郎遂無归思。","奚諸人云他徙，迴顧已無一物。","誇郎數月猶惝恍，終歲乃如故。","〖節錄大意〗）。"]', '诗', 'shi', '', NULL, '袁誇郎遇仙詩 誇郎贈封平仲詩 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c6031163-673c-44e9-8d28-6ba39a04e6a3', '牛僧孺入薄后廟與諸后妃共吟詩（題擬） 薄太后作詩', '牛僧孺入薄后廟與諸后妃共吟诗（題擬） 薄太后作诗', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["月寢花宮得奉君，至今猶媿管夫人。","漢家舊是笙歌處，煙草幾經秋復春。"]', '["月寢花宮得奉君，至今猶媿管夫人。","漢家旧是笙歌处，煙草幾經秋复春。"]', '诗', 'shi', '', NULL, '牛僧孺入薄后廟與諸后妃共吟詩（題擬） 薄太后作詩 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3318343d-38b7-414c-9815-dc307e5fc64a', '牛僧孺入薄后廟與諸后妃共吟詩（題擬） 王嬙作詩', '牛僧孺入薄后廟與諸后妃共吟诗（題擬） 王嬙作诗', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["雪裡穹廬不見春，漢衣雖舊涙痕（《唐人小說》作「垂」）新。","如今最恨毛延壽，愛把丹青錯畫人。"]', '["雪裡穹廬不见春，漢衣雖旧涙痕（《唐人小说》作「垂」）新。","如今最恨毛延壽，愛把丹青錯畫人。"]', '诗', 'shi', '', NULL, '牛僧孺入薄后廟與諸后妃共吟詩（題擬） 王嬙作詩 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3218de36-9548-4387-8315-f54bd5f7ed77', '牛僧孺入薄后廟與諸后妃共吟詩（題擬） 戚夫人作詩', '牛僧孺入薄后廟與諸后妃共吟诗（題擬） 戚夫人作诗', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["自別漢宮休楚舞，不能粧粉恨君王。","無金豈得迎商叟，吕氏何曾畏木彊。"]', '["自別漢宮休楚舞，不能粧粉恨君王。","無金豈得迎商叟，吕氏何曾畏木彊。"]', '诗', 'shi', '', NULL, '牛僧孺入薄后廟與諸后妃共吟詩（題擬） 戚夫人作詩 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7012fe32-10a0-4f5f-9816-8d2277a119fc', '牛僧孺入薄后廟與諸后妃共吟詩（題擬） 楊太真作詩', '牛僧孺入薄后廟與諸后妃共吟诗（題擬） 楊太真作诗', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["金釵墮地別君王，紅淚流珠滿御牀。","雲雨馬嵬分散後，驪宮不復舞霓裳。","。"]', '["金釵墮地別君王，紅泪流珠满御牀。","云雨马嵬分散後，驪宮不复舞霓裳。","。"]', '诗', 'shi', '', NULL, '牛僧孺入薄后廟與諸后妃共吟詩（題擬） 楊太真作詩 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('938284ed-da48-4ef5-9a91-e2af6e493f3f', '牛僧孺入薄后廟與諸后妃共吟詩（題擬） 潘妃作詩', '牛僧孺入薄后廟與諸后妃共吟诗（題擬） 潘妃作诗', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["秋月春風幾度歸，江山猶是[鄴]（〖業〗從汪辟疆《唐人小說》改）宮非。","東昏舊作蓮花地，空想曾披金縷衣。"]', '["秋月春风幾度归，江山猶是[鄴]（〖業〗從汪辟疆《唐人小说》改）宮非。","东昏旧作蓮花地，空想曾披金縷衣。"]', '诗', 'shi', '', NULL, '牛僧孺入薄后廟與諸后妃共吟詩（題擬） 潘妃作詩 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('07bdb559-4d76-408f-a58c-3a0456bc1fbf', '牛僧孺入薄后廟與諸后妃共吟詩（題擬） 牛僧孺作詩', '牛僧孺入薄后廟與諸后妃共吟诗（題擬） 牛僧孺作诗', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["香風引到大羅天，月地雲階拜洞仙。","共道人間惆悵事，不知人夕是何年。"]', '["香风引到大羅天，月地云階拜洞仙。","共道人间惆悵事，不知人夕是何年。"]', '诗', 'shi', '', NULL, '牛僧孺入薄后廟與諸后妃共吟詩（題擬） 牛僧孺作詩 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('160e430c-af57-4855-ac41-968e92b569d4', '綠珠作詩', '綠珠作诗', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["此日人非昔日人，笛聲空怨趙王倫。","紅殘翠碎花樓下，金谷千年更不春。","見《太平廣記》卷四八九引。","今人汪辟疆《唐人小說》本係據《顧氏文房小說》本校錄，今據以校異文。","（按：《周秦行紀》作者，《太平廣記》署「牛僧孺撰」，後人已證定爲韋瓘作，今從之。","《全唐詩續補遺》卷八將第六首收歸牛僧孺名下，未諦，今重錄之。","）。"]', '["此日人非昔日人，笛声空怨趙王倫。","紅殘翠碎花楼下，金谷千年更不春。","见《太平廣記》卷四八九引。","今人汪辟疆《唐人小说》本係據《顧氏文房小说》本校錄，今據以校異文。","（按：《周秦行紀》作者，《太平廣記》署「牛僧孺撰」，後人已證定爲韋瓘作，今從之。","《全唐诗續補遺》卷八將第六首收归牛僧孺名下，未諦，今重錄之。","）。"]', '诗', 'shi', '', NULL, '綠珠作詩 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('279751c3-71a2-497d-b597-4e83a15f119b', '吳彩鸞作越王山詩（題擬）', '吳彩鸾作越王山诗（題擬）', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["一斑與兩斑，引入越王山。","世數今逃盡，煙蘿得再還。","簫聲宜露滴，鶴翅向雲間。","一粒仙人藥，服之能駐顏。","（見宋陳元靚《歲時廣記》卷三十二引裴鉶《傳奇》）。"]', '["一斑與兩斑，引入越王山。","世數今逃尽，煙蘿得再還。","簫声宜露滴，鹤翅向云间。","一粒仙人藥，服之能駐顏。","（见宋陳元靚《歲时廣記》卷三十二引裴鉶《傳奇》）。"]', '诗', 'shi', '', NULL, '吳彩鸞作越王山詩（題擬） 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c6ae695a-d325-42d9-94a0-27c77d6e8faa', '馬拯聞衡山祝融峰僧寺食堂內土偶吟詩（題擬）', '马拯闻衡山祝融峰僧寺食堂內土偶吟诗（題擬）', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["寅人但溺欄中水，午子須分艮畔金。","若教特進重張弩，過去將軍必損心。","（見《太平廣記》卷四三○引裴鉶《傳奇》）。"]', '["寅人但溺欄中水，午子須分艮畔金。","若教特進重張弩，過去將軍必損心。","（见《太平廣記》卷四三○引裴鉶《傳奇》）。"]', '诗', 'shi', '', NULL, '馬拯聞衡山祝融峰僧寺食堂內土偶吟詩（題擬） 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('07226b09-f14d-47af-aa04-aa6f0d9c7400', '吳清妻受仙詩（其二）', '吳清妻受仙诗（其二）', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["心清境靜聞妙香，憶昔期君隱處當。","一星蓮花山頭飯，黃精仙人掌上經。","（見中華書局排印汪紹楹校本《太平廣記》卷六七引盧肇《逸史》）（按：吳清妻受仙詩共四首，《全唐詩》卷八六三皆收入，但第二首缺首十字。","談刻本《太平廣記》所缺同。","汪紹楹先生據清黃晟刻本爲補足之，今據以重錄。","）。"]', '["心清境静闻妙香，憶昔期君隐处當。","一星蓮花山头飯，黄精仙人掌上經。","（见中华书局排印汪紹楹校本《太平廣記》卷六七引盧肇《逸史》）（按：吳清妻受仙诗共四首，《全唐诗》卷八六三皆收入，但第二首缺首十字。","談刻本《太平廣記》所缺同。","汪紹楹先生據清黄晟刻本爲補足之，今據以重錄。","）。"]', '诗', 'shi', '', NULL, '吳清妻受仙詩（其二） 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3fa4ac88-fd3a-48f5-a862-3a00fa72ce7b', '嵩山女臨去贈任生詩（題擬）', '嵩山女臨去贈任生诗（題擬）', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["阮郎迷不悟，何處伸情愫（《神仙感遇傳》作「何要申情愫」）。","明日海山春，彩舟却歸去。","（見《增修詩話總龜前集》卷四五引盧肇《遺史》，校以《雲笈七籤》卷一一三引《神仙感遇傳》）（按：《全唐詩》卷八六三收嵩山女詩意相近的另一首詩收入。","今另錄出。","）。"]', '["阮郎迷不悟，何处伸情愫（《神仙感遇傳》作「何要申情愫」）。","明日海山春，彩舟却归去。","（见《增修诗話總龟前集》卷四五引盧肇《遺史》，校以《云笈七籤》卷一一三引《神仙感遇傳》）（按：《全唐诗》卷八六三收嵩山女诗意相近的另一首诗收入。","今另錄出。","）。"]', '诗', 'shi', '', NULL, '嵩山女臨去贈任生詩（題擬） 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('09e2d59a-6689-425d-b4d0-b3fc932e80b2', '沈警遇仙張女郎廟詩（題擬） 沈警奉使秦隴途過張女郎廟獨酌水具祝詞', '沈警遇仙張女郎廟诗（題擬） 沈警奉使秦隴途過張女郎廟独酌水具祝词', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["酌彼寒泉水，紅芳掇喦谷。","雖致之非遙，而薦之隨俗。","丹誠成此，神其感錄。"]', '["酌彼寒泉水，紅芳掇喦谷。","雖致之非遙，而薦之隨俗。","丹誠成此，神其感錄。"]', '诗', 'shi', '', NULL, '沈警遇仙張女郎廟詩（題擬） 沈警奉使秦隴途過張女郎廟獨酌水具祝詞 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('98635a73-6204-4006-bb77-d4699714605d', '沈警遇仙張女郎廟詩（題擬） 既暮宿傳舍憑軒望月作鳳將鶵含嬌曲', '沈警遇仙張女郎廟诗（題擬） 既暮宿傳舍憑軒望月作鳳將鶵含嬌曲', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["命嘯無人嘯，含嬌何處嬌？徘徊花上月，空度可憐宵。"]', '["命嘯無人嘯，含嬌何处嬌？徘徊花上月，空度可怜宵。"]', '诗', 'shi', '', NULL, '沈警遇仙張女郎廟詩（題擬） 既暮宿傳舍憑軒望月作鳳將鶵含嬌曲 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e28367ba-1bc2-42d4-8646-01ef1d3d11a3', '沈警遇仙張女郎廟詩（題擬） 又續爲歌', '沈警遇仙張女郎廟诗（題擬） 又續爲歌', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["靡靡春風至，微微春露輕。","可惜關山月，還成無用明。","。"]', '["靡靡春风至，微微春露轻。","可惜关山月，還成無用明。","。"]', '诗', 'shi', '', NULL, '沈警遇仙張女郎廟詩（題擬） 又續爲歌 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3eeea7aa-1b71-4d90-b242-31558dd83901', '沈警遇仙張女郎廟詩（題擬） 吟畢聞簾外歎賞之聲復云', '沈警遇仙張女郎廟诗（題擬） 吟畢闻簾外歎賞之声复云', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '[]', '[]', '诗', 'shi', '', NULL, '沈警遇仙張女郎廟詩（題擬） 吟畢聞簾外歎賞之聲復云 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6c0f07e1-9241-4f91-a272-f6ffe763e0e2', '沈警遇仙張女郎廟詩（題擬） 張氏大女郎歌', '沈警遇仙張女郎廟诗（題擬） 張氏大女郎歌', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["人神相合兮後會難，邂逅相遇兮暫爲歡。","星漢移兮夜將闌，心未極兮且盤桓。"]', '["人神相合兮後會难，邂逅相遇兮暫爲歡。","星漢移兮夜將闌，心未極兮且盤桓。"]', '诗', 'shi', '', NULL, '沈警遇仙張女郎廟詩（題擬） 張氏大女郎歌 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b8e6a7d7-587b-4587-bdae-41a381d941d8', '沈警遇仙張女郎廟詩（題擬） 小女郎歌', '沈警遇仙張女郎廟诗（題擬） 小女郎歌', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["洞簫響兮風生流，清夜闌兮管絃遒。","長相思兮衡山曲，心斷絕兮秦隴頭。"]', '["洞簫响兮风生流，清夜闌兮管絃遒。","长相思兮衡山曲，心斷絕兮秦隴头。"]', '诗', 'shi', '', NULL, '沈警遇仙張女郎廟詩（題擬） 小女郎歌 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c50e3126-3b13-4b58-b723-88e0acc6fba9', '沈警遇仙張女郎廟詩（題擬） 又題', '沈警遇仙張女郎廟诗（題擬） 又題', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["隴上雲車不復居，湘川斑竹淚沾餘。","誰念衡山煙霧裏，空看鴈足不傳書。"]', '["隴上云车不复居，湘川斑竹泪沾餘。","誰念衡山煙霧裏，空看鴈足不傳书。"]', '诗', 'shi', '', NULL, '沈警遇仙張女郎廟詩（題擬） 又題 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e71c6b04-efa0-4090-923a-62e036d6c8a0', '沈警遇仙張女郎廟詩（題擬） 沈警歌', '沈警遇仙張女郎廟诗（題擬） 沈警歌', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["義熙曾歷許多年，張碩凡得幾時憐？何意今人不及昔，暫來相見更無緣。"]', '["義熙曾歷許多年，張碩凡得幾时怜？何意今人不及昔，暫来相见更無緣。"]', '诗', 'shi', '', NULL, '沈警遇仙張女郎廟詩（題擬） 沈警歌 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a0f1652a-bc81-48ff-9380-50ba675debfa', '沈警遇仙張女郎廟詩（題擬） 沈警與張氏二女臨別又歌', '沈警遇仙張女郎廟诗（題擬） 沈警與張氏二女臨別又歌', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["直恁行人心不平，那宜萬里阻關情。","只今隴上分流水，更泛從來嗚咽聲。"]', '["直恁行人心不平，那宜万里阻关情。","只今隴上分流水，更泛從来嗚咽声。"]', '诗', 'shi', '', NULL, '沈警遇仙張女郎廟詩（題擬） 沈警與張氏二女臨別又歌 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eefba29a-e382-42bf-8a0c-b85b3012d76d', '沈警遇仙張女郎廟詩（題擬） 小女郎贈警金合歡結歌', '沈警遇仙張女郎廟诗（題擬） 小女郎贈警金合歡結歌', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["結心纏萬縷，結縷幾千廻。","結怨無窮極，結心終不開。"]', '["結心纏万縷，結縷幾千廻。","結怨無窮極，結心終不开。"]', '诗', 'shi', '', NULL, '沈警遇仙張女郎廟詩（題擬） 小女郎贈警金合歡結歌 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5861d479-ec21-4558-861c-431974786e03', '沈警遇仙張女郎廟詩（題擬） 大女郎贈警瑤鏡子歌', '沈警遇仙張女郎廟诗（題擬） 大女郎贈警瑤镜子歌', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["憶昔窺瑤鏡，相望看明月。","彼此俱照人，莫令光彩滅。","。"]', '["憶昔窺瑤镜，相望看明月。","彼此俱照人，莫令光彩滅。","。"]', '诗', 'shi', '', NULL, '沈警遇仙張女郎廟詩（題擬） 大女郎贈警瑤鏡子歌 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a751913f-6b65-41d9-96ae-a17cf0d8f6db', '沈警遇仙張女郎廟詩（題擬） 警使回至廟中得小女郎書書末有篇云', '沈警遇仙張女郎廟诗（題擬） 警使回至廟中得小女郎书书末有篇云', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["飛書報沈郎，尋已到衡陽。","若存金石契，風月兩相望。","（見《太平廣記》卷三二六引陳翰《異聞錄》）（〖1〗今人程毅中《〈異聞集〉考》云：「記中沈警詩『徘徊花上月，空度可憐宵』兩句，《詩人玉屑》卷十二引作沈亞之詩，疑本篇爲沈亞之作，但《沈下賢文集》不載。","」按：《異聞錄》云：沈警，字玄機，吳興武康人。","爲梁東宮常侍，名著當時。","後荆楚陷沒，入周爲上柱國，奉使秦隴，途過張女郎廟，得遇羣仙。","）。"]', '["飞书報沈郎，尋已到衡陽。","若存金石契，风月兩相望。","（见《太平廣記》卷三二六引陳翰《異闻錄》）（〖1〗今人程毅中《〈異闻集〉考》云：「記中沈警诗『徘徊花上月，空度可怜宵』兩句，《诗人玉屑》卷十二引作沈亞之诗，疑本篇爲沈亞之作，但《沈下賢文集》不載。","」按：《異闻錄》云：沈警，字玄機，吳兴武康人。","爲梁东宮常侍，名著當时。","後荆楚陷沒，入周爲上柱国，奉使秦隴，途過張女郎廟，得遇羣仙。","）。"]', '诗', 'shi', '', NULL, '沈警遇仙張女郎廟詩（題擬） 警使回至廟中得小女郎書書末有篇云 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2bf737f7-4922-4acf-8981-1820765c8b50', '趙阿奴魚背字（題擬）', '趙阿奴鱼背字（題擬）', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["三曾到楊府，五轉歸馬湖。","身上千斤肉，今還趙阿奴。","（見何光遠《鑑誡錄》卷十《魚還肉》）（〖1〗《鑑誡錄》云：「天復初，任可芝任戎州刺史日，有魚人趙阿奴，善釣大魚。","……其年秋，忽獲一絡子魚，果重千斤，背上自然有字，其文金色，觀者感傷。","趙阿奴因此從軍，遂改釣業。","其大魚背上字云〖略〗。","」）。"]', '["三曾到楊府，五轉归马湖。","身上千斤肉，今還趙阿奴。","（见何光远《鑑誡錄》卷十《鱼還肉》）（〖1〗《鑑誡錄》云：「天复初，任可芝任戎州刺史日，有鱼人趙阿奴，善釣大鱼。","……其年秋，忽獲一絡子鱼，果重千斤，背上自然有字，其文金色，观者感傷。","趙阿奴因此從軍，遂改釣業。","其大鱼背上字云〖略〗。","」）。"]', '诗', 'shi', '', NULL, '趙阿奴魚背字（題擬） 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7354bd36-a9e2-4532-bbb9-fee61dd6317b', '盧攜夢人贈句（題擬）', '盧携梦人贈句（題擬）', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["若問登庸日，庭椿不染風。","（見馮贄《雲仙雜記》卷五引《鳳池編》）（〖1〗《鳳池編》云：「盧攜夢人贈句曰〖略〗。","初不解其言，後數年攜拜相，庭下古椿一株，雖狂風驟雨，不濕不搖。","」）。"]', '["若问登庸日，庭椿不染风。","（见馮贄《云仙杂記》卷五引《鳳池編》）（〖1〗《鳳池編》云：「盧携梦人贈句曰〖略〗。","初不解其言，後數年携拜相，庭下古椿一株，雖狂风驟雨，不濕不搖。","」）。"]', '诗', 'shi', '', NULL, '盧攜夢人贈句（題擬） 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8a59398a-facf-4978-86ab-212152b0c4a9', '楊國忠聞屏風女歌', '楊国忠闻屏风女歌', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["三朵芙蓉是我流，大楊造得小楊收。","（見樂史《太真外傳》卷上）。"]', '["三朵芙蓉是我流，大楊造得小楊收。","（见乐史《太真外傳》卷上）。"]', '诗', 'shi', '', NULL, '楊國忠聞屏風女歌 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1794e65b-0e34-4ee0-bb5d-8748f05943bf', '句曲父老爲三茅君歌（題擬）', '句曲父老爲三茅君歌（題擬）', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["茅山連金陵，江湖據下流。","三君乘白鶴，各治一山頭。","召雨澤旱田，陸地亦復收。","妻子保堂堂，使我無百憂。","白鶴翔青天，何時復來遊？","（見《然而卓異記》卷二十引《總仙記》）（按：《太平廣記》卷五引《洞仙記》「茅濛」條，與《總仙記》此條前半合，知樂史當有所本。","此詩見該條後半，未見更早記載。","）。"]', '["茅山連金陵，江湖據下流。","三君乘白鹤，各治一山头。","召雨澤旱田，陸地亦复收。","妻子保堂堂，使我無百憂。","白鹤翔青天，何时复来游？","（见《然而卓異記》卷二十引《總仙記》）（按：《太平廣記》卷五引《洞仙記》「茅濛」條，與《總仙記》此條前半合，知乐史當有所本。","此诗见該條後半，未见更早記載。","）。"]', '诗', 'shi', '', NULL, '句曲父老爲三茅君歌（題擬） 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0d4a4f76-a8a2-46f6-a3b5-1aa72f917fc5', '青蘿帳女贈穆師言雙瑠璃杯詩（題參《萬首唐人絕句》卷六九擬）', '青蘿帳女贈穆師言雙瑠璃杯诗（題參《万首唐人絕句》卷六九擬）', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["良宵織女會牽牛，瓊液成雙預獻酬。","枝葉相連無替改，願同松竹保千秋。","（《燈下閑談》卷上《榕樹精靈》）。"]', '["良宵织女會牽牛，瓊液成雙預獻酬。","枝葉相連無替改，願同松竹保千秋。","（《灯下闲談》卷上《榕樹精靈》）。"]', '诗', 'shi', '', NULL, '青蘿帳女贈穆師言雙瑠璃杯詩（題參《萬首唐人絕句》卷六九擬） 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('294b9e79-fefe-4b9d-a3b8-b405bf605619', '眇目道士命牋毫書詩（題擬）', '眇目道士命牋毫书诗（題擬）', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["鵲羽橋成星斗連，何須攜室下遙天。","來逢蓬蓽當諸夜，共綴詞華染素牋。","霓帔豈勞施粉藻，寶冠猶更貼花鈿。","人間限滿離塵土，即俟瑤階廁列仙。","（《燈下閑談》卷上《桃花障子》）。"]', '["鵲羽橋成星斗連，何須携室下遙天。","来逢蓬蓽當諸夜，共綴词华染素牋。","霓帔豈勞施粉藻，寶冠猶更貼花鈿。","人间限满離塵土，即俟瑤階廁列仙。","（《灯下闲談》卷上《桃花障子》）。"]', '诗', 'shi', '', NULL, '眇目道士命牋毫書詩（題擬） 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('46984a95-8057-47b4-8578-5d863cab0826', '美少年繼作（題擬）', '美少年繼作（題擬）', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["乘鸞跨鳳下崑崙，正值三星影入門。","銀燭高低攢寶帳，綵牋交互勸瑤尊。","藥靈許向人間說，《易》妙期於象外論。","休憶當年陪孟德，繞梁爭看酒杯翻。","（同前）。"]', '["乘鸾跨鳳下崑崙，正值三星影入门。","銀燭高低攢寶帳，綵牋交互勸瑤尊。","藥靈許向人间说，《易》妙期於象外論。","休憶當年陪孟德，繞梁爭看酒杯翻。","（同前）。"]', '诗', 'shi', '', NULL, '美少年繼作（題擬） 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0f9c6c4f-7abc-40ec-b600-28abffd5ec61', '青城白裘叟贈楊內侍二十八字詩（題擬）', '青城白裘叟贈楊內侍二十八字诗（題擬）', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["五色雲英生海月，能飲南方赤龍血。","生冷宮中住雌雄，紫金臺上凝霜雪。","（《燈下閑說》卷上《棄官遇仙》）。"]', '["五色云英生海月，能饮南方赤龙血。","生冷宮中住雌雄，紫金台上凝霜雪。","（《灯下闲说》卷上《棄官遇仙》）。"]', '诗', 'shi', '', NULL, '青城白裘叟贈楊內侍二十八字詩（題擬） 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b0bc1873-deb6-4ead-b600-76d3268634fb', '湘妃廟席上妲己賦詩（題擬）', '湘妃廟席上妲己賦诗（題擬）', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["歡樂平生自縱心，武王兵起勢難任。","自茲宗社傾危後，方悟當時酷暴深。","（《燈下閑談》卷下《湘妃神會》）。"]', '["歡乐平生自縱心，武王兵起勢难任。","自茲宗社傾危後，方悟當时酷暴深。","（《灯下闲談》卷下《湘妃神會》）。"]', '诗', 'shi', '', NULL, '湘妃廟席上妲己賦詩（題擬） 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d88f7e42-1374-400b-a5d4-9784381d5784', '泰山獵人石室遇仙聞董雙成奏《雲和》笙詞', '泰山獵人石室遇仙闻董雙成奏《云和》笙词', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["淅瀝復悠溶，諸天樂所宗。","愔愔形類鳳，冉冉勢從龍。","片觸峻嶒碎，聲飄列缺重。","不辭歌一曲，此會信難逢。","（《燈下閑談》卷下《獵猪遇仙》）。"]', '["淅瀝复悠溶，諸天乐所宗。","愔愔形類鳳，冉冉勢從龙。","片觸峻嶒碎，声飄列缺重。","不辞歌一曲，此會信难逢。","（《灯下闲談》卷下《獵猪遇仙》）。"]', '诗', 'shi', '', NULL, '泰山獵人石室遇仙聞董雙成奏《雲和》笙詞 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('43be979e-c090-4056-aeee-20379e03839b', '羅浮松續賈松句（題擬）', '羅浮松續賈松句（題擬）', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["白髮不由己。","（賈松。","）黃金留待誰？","（松作人語。","見《燈下閑談》卷上《松作人語》。","）（〖1〗《燈下閑談》云：「松乃諾之，遂同入羅浮，三年守真丹竃，藥既無成，吟且不廢。","因夜靠松瞑目，吟曰：『白髮不由己。","』如是數四，至於中夜。","忽聞松上應聲曰：『黃金留待誰？","」按：賈松，字夢得，乾寧中游宜春，與齊己、虛中等遊。","光化四年登進士第，名列第八人。","後至宜春與鄭谷遊。","）。"]', '["白髮不由己。","（賈松。","）黄金留待誰？","（松作人語。","见《灯下闲談》卷上《松作人語》。","）（〖1〗《灯下闲談》云：「松乃諾之，遂同入羅浮，三年守真丹竃，藥既無成，吟且不廢。","因夜靠松瞑目，吟曰：『白髮不由己。","』如是數四，至於中夜。","忽闻松上應声曰：『黄金留待誰？","」按：賈松，字梦得，乾寧中游宜春，與齊己、虛中等游。","光化四年登進士第，名列第八人。","後至宜春與鄭谷游。","）。"]', '诗', 'shi', '', NULL, '羅浮松續賈松句（題擬） 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9a8ed4d0-776d-44bf-9a8a-f1cecef57967', '日華月華君贈鄭冠卿詩（題擬） 一', '日华月华君贈鄭冠卿诗（題擬） 一', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["倏忽而來蹔少留，凡間風月已三秋。","趨名競利何時了，害物傷人早晚休。","禍極累成爲世謗，貴榮過却（《仙迹記》作「榮過恩却」）與身讎。","君看虎戰龍爭者（《仙迹記》作「處」），幾樹白楊飄隴頭。"]', '["倏忽而来蹔少留，凡间风月已三秋。","趨名競利何时了，害物傷人早晚休。","禍極累成爲世謗，貴榮過却（《仙迹記》作「榮過恩却」）與身讎。","君看虎戰龙爭者（《仙迹記》作「处」），幾樹白楊飄隴头。"]', '诗', 'shi', '', NULL, '日華月華君贈鄭冠卿詩（題擬） 一 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0908543f-7363-4ebb-94a6-f2da9967e9e7', '日華月華君贈鄭冠卿詩（題擬） 二', '日华月华君贈鄭冠卿诗（題擬） 二', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["名利教疏便可疏，俗情時態莫踟躕。","人寰律歷千迴換，僊洞光陰數息餘。","應（《仙迹記作「頃」》）信令威曾化鶴，亦（《仙迹記》作「今」）知莊叟美（《仙迹記》作「羨」）游魚。","不緣過去行方便，那得今來（《仙迹記》、《碧虛銘》作「朝」）會碧虛。","（見《燈下閑談》卷下《代名納稅》。","又見桂林市文管局編《桂林石刻》錄桂林七星洞磨崖宋尹穡紹興五年撰《仙迹記》、《粵西金石略》卷九錄范成大《碧虛銘》錄「不緣」二句。","《全唐詩》卷八六二僅收「不緣」二句，似即出《碧虛銘》。","）（按：《燈下閑談》一書，舊題宋江洵著，實誤。","據拙考應爲五代間人著，作者姓名已佚，約生於唐末，而書成則在後唐天成以後。","）。"]', '["名利教疏便可疏，俗情时態莫踟躕。","人寰律歷千迴換，僊洞光陰數息餘。","應（《仙迹記作「頃」》）信令威曾化鹤，亦（《仙迹記》作「今」）知莊叟美（《仙迹記》作「羨」）游鱼。","不緣過去行方便，那得今来（《仙迹記》、《碧虛銘》作「朝」）會碧虛。","（见《灯下闲談》卷下《代名納稅》。","又见桂林市文管局編《桂林石刻》錄桂林七星洞磨崖宋尹穡紹兴五年撰《仙迹記》、《粵西金石略》卷九錄范成大《碧虛銘》錄「不緣」二句。","《全唐诗》卷八六二僅收「不緣」二句，似即出《碧虛銘》。","）（按：《灯下闲談》一书，旧題宋江洵著，實誤。","據拙考應爲五代间人著，作者姓名已佚，約生於唐末，而书成則在後唐天成以後。","）。"]', '诗', 'shi', '', NULL, '日華月華君贈鄭冠卿詩（題擬） 二 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f3441fb1-f00c-4777-8e4b-b5b762ad3961', '王母贈魏夫人歌一章（幷序）', '王母贈魏夫人歌一章（幷序）', '514627d9-1ffa-406b-b0f2-469e6edbd30b', '唐', '["駕我八景輿，歘然入玉清。","龍裙拂霄漢，虎旂攝朱兵。","逍遙玄津際，萬流無暫停。","哀此去留會，劫盡天地傾。","當盡無中景，不死亦無生。","體彼自然道，寂觀合太冥。","南嶽挺真翰，玉映曜穎精。","有任靡期事，虛心自受靈。","嘉會絳河內，相與樂未央。"]', '["駕我八景輿，歘然入玉清。","龙裙拂霄漢，虎旂攝朱兵。","逍遙玄津際，万流無暫停。","哀此去留會，劫尽天地傾。","當尽無中景，不死亦無生。","體彼自然道，寂观合太冥。","南嶽挺真翰，玉映曜穎精。","有任靡期事，虛心自受靈。","嘉會絳河內，相與乐未央。"]', '诗', 'shi', '', NULL, '王母贈魏夫人歌一章（幷序） 項宗 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d5b0369e-1d49-4116-9fa7-f2ef8edc6c07', '雙禮珠彈雲璈而答歌一章', '雙禮珠彈云璈而答歌一章', '514627d9-1ffa-406b-b0f2-469e6edbd30b', '唐', '["玉清出九天，神館飛霞外。","霄臺煥嵯峨，靈夏秀蔚翳。","五雲興翠華，八風扇綠氣。","仰吟消魔詠，俯研智與慧。","萬真啓晨景，唱期絳房會。","挺穎德音子，神映乃拂沛。","天嶽凌空構，洞臺深幽邃。","遊海悟井隘，履真覺世穢。","儛輪宴重空，筌魚自然廢。","廻我大椿羅，長謝朝生世。"]', '["玉清出九天，神館飞霞外。","霄台煥嵯峨，靈夏秀蔚翳。","五云兴翠华，八风扇綠氣。","仰吟消魔詠，俯研智與慧。","万真啓晨景，唱期絳房會。","挺穎德音子，神映乃拂沛。","天嶽凌空構，洞台深幽邃。","游海悟井隘，履真覺世穢。","儛輪宴重空，筌鱼自然廢。","廻我大椿羅，长謝朝生世。"]', '诗', 'shi', '', NULL, '雙禮珠彈雲璈而答歌一章 項宗 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e2a3b1f9-f54b-456a-83ac-286a417047cb', '高仙盼遊洞靈之曲一章（幷序）', '高仙盼游洞靈之曲一章（幷序）', '514627d9-1ffa-406b-b0f2-469e6edbd30b', '唐', '["玉室煥東霞，紫輦浮絳宸。","華臺何盼目，北宴飛天元。","清浄太無中，眇眇躡景遷。","吟詠大洞章，唱此三九篇。","曲寢大漠內，神王方寸間，寂室思靈暉，何事苦山林。","須臾變衰翁，廻爲孩中顏。"]', '["玉室煥东霞，紫輦浮絳宸。","华台何盼目，北宴飞天元。","清浄太無中，眇眇躡景遷。","吟詠大洞章，唱此三九篇。","曲寢大漠內，神王方寸间，寂室思靈暉，何事苦山林。","須臾变衰翁，廻爲孩中顏。"]', '诗', 'shi', '', NULL, '高仙盼遊洞靈之曲一章（幷序） 項宗 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d978ca1b-6d00-4ecd-ad41-1ad9cf2054f3', '四真人降魏夫人歌共五章（幷序）', '四真人降魏夫人歌共五章（幷序）', '514627d9-1ffa-406b-b0f2-469e6edbd30b', '唐', '["丹明煥上清，八風鼓太霞。","廻我神霄輦，遂造玉嶺阿。","咄嗟天地外，九圍皆吾家。","上採日中精，下飲黃月華。","靈觀空無中，鵬路無間邪。","顧見魏賢安，濁氣傷爾和。","勤研玄中思，道成更相過。"]', '["丹明煥上清，八风鼓太霞。","廻我神霄輦，遂造玉嶺阿。","咄嗟天地外，九圍皆吾家。","上採日中精，下饮黄月华。","靈观空無中，鵬路無间邪。","顧见魏賢安，濁氣傷爾和。","勤研玄中思，道成更相過。"]', '诗', 'shi', '', NULL, '四真人降魏夫人歌共五章（幷序） 項宗 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e46d517d-c2a7-4575-87e5-53bd87df24e3', '四真人降魏夫人歌共五章（幷序） 方諸青童歌一章', '四真人降魏夫人歌共五章（幷序） 方諸青童歌一章', '514627d9-1ffa-406b-b0f2-469e6edbd30b', '唐', '["太霞扇晨暉，九氣無常形。","玄轡飛霄外，八景乘高清。","手把玉皇袂，攜我晨中生。","盼觀七曜房，朗朗亦冥冥。","超哉魏氏子，有心復有情。","玄挺自嘉會，金書東華名。","賢安密所研，相期暘谷汧。"]', '["太霞扇晨暉，九氣無常形。","玄轡飞霄外，八景乘高清。","手把玉皇袂，携我晨中生。","盼观七曜房，朗朗亦冥冥。","超哉魏氏子，有心复有情。","玄挺自嘉會，金书东华名。","賢安密所研，相期暘谷汧。"]', '诗', 'shi', '', NULL, '四真人降魏夫人歌共五章（幷序） 方諸青童歌一章 項宗 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('faafe114-d60b-48ef-aeda-cacabd38d0f1', '四真人降魏夫人歌共五章（幷序） 次扶桑神王歌一章', '四真人降魏夫人歌共五章（幷序） 次扶桑神王歌一章', '514627d9-1ffa-406b-b0f2-469e6edbd30b', '唐', '["晨啓太帝室，超越匏瓜水。","碧海飛翠波，連岑赤嶽峙。","浮輪雲濤際，九龍同轡起。","虎旂欝霞津，靈風翻然而理。","華存久樂道，遂致高神擬。","拔徙三緣外感會乃方始。","相期陽洛宮，道成攜魏子。"]', '["晨啓太帝室，超越匏瓜水。","碧海飞翠波，連岑赤嶽峙。","浮輪云濤際，九龙同轡起。","虎旂欝霞津，靈风翻然而理。","华存久乐道，遂致高神擬。","拔徙三緣外感會乃方始。","相期陽洛宮，道成携魏子。"]', '诗', 'shi', '', NULL, '四真人降魏夫人歌共五章（幷序） 次扶桑神王歌一章 項宗 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c81fb5cc-e62c-4caf-851c-68ee739a29ae', '四真人降魏夫人歌共五章（幷序） 一', '四真人降魏夫人歌共五章（幷序） 一', '514627d9-1ffa-406b-b0f2-469e6edbd30b', '唐', '["駕歘控清虛，徘徊西華館。","瓊林既神杪，虎旂逐煙散，慧風振丹旍，明燭朗八煥。","解襟庸房裏，神鈴鳴蒨粲。","棲景若林柯，九絃玄中彈。","遺我積世憂，釋此千年歎。","怡盼無極已，終夜復待旦。"]', '["駕歘控清虛，徘徊西华館。","瓊林既神杪，虎旂逐煙散，慧风振丹旍，明燭朗八煥。","解襟庸房裏，神鈴鳴蒨粲。","棲景若林柯，九絃玄中彈。","遺我積世憂，釋此千年歎。","怡盼無極已，終夜复待旦。"]', '诗', 'shi', '', NULL, '四真人降魏夫人歌共五章（幷序） 一 項宗 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7ee9fb83-d5d5-4446-a2b0-e8f2e3b2b47d', '四真人降魏夫人歌共五章（幷序） 二', '四真人降魏夫人歌共五章（幷序） 二', '514627d9-1ffa-406b-b0f2-469e6edbd30b', '唐', '["紫霞儛玄空，神風無綱領。","歘然滿八區，祝爾豁虛靜。","八窗無常朗，有冥亦有炅。","洞觀三丹田，寂寂生形景。","凝神挻相遇，雲姿卓鑠整。","愧無郢石運，蓋彼自然穎。","勤密攝生道，泄替結災眚。","靈期自有時，攜袂乃俱上。","（以上均見《雲笈七籤》卷九六。","）（按：以上諸詩，《雲笈七籤》未云出處，今考應出《南嶽魏夫人傳》。","檢顏真卿《文忠集》卷九《晉紫虛元職工領上真司命南嶽夫人魏夫人仙壇碑銘》云：「于是西王母擊節而歌。","歌畢，馮雙禮珠彈雲璈而答歌，餘真人各歌。","」《太平廣記》卷五八《魏夫人》條引《集仙錄》及《本傳》云：「于是四真吟唱，各命玉女，彈琴擊鐘吹簫，合節而發歌。","……是時太極真人命北寒玉女宋聯消，彈九氣之璈，青童命東華玉女煙景珠，擊西盈之鐘。","暘谷神王命神林玉女賈屈廷，吹鳳唳之簫，青虛真人命飛玄玉女鮮于虛，拊九合玉節。","太極真人發《排空之歌》，青童吟『太霞』之曲，神王諷『晨啓』之章，清虛詠『駕飈』之詞。","……王母擊節而，三元夫人彈雲璈而答歌，餘真各歌。","」魏夫人，傳爲西晉時人，陶弘景《真誥》已載其事，惟較簡略。","晉范邈撰《南真傳》，今不存。","《太平廣記》所錄《本傳》，據陳國符先生《道藏源流考》考證，應即《新唐書·藝文志》著錄之項宗《紫虛元君魏夫人內傳》之節文。","參以顏《碑》所云，其說可信。","項宗，陳考爲唐人。","《雲笈七籤》所據，當即項宗之書，《太平廣記》刪去諸詩，猶錄存之，較可寶惜。","）。"]', '["紫霞儛玄空，神风無綱領。","歘然满八區，祝爾豁虛静。","八窗無常朗，有冥亦有炅。","洞观三丹田，寂寂生形景。","凝神挻相遇，云姿卓鑠整。","愧無郢石運，蓋彼自然穎。","勤密攝生道，泄替結災眚。","靈期自有时，携袂乃俱上。","（以上均见《云笈七籤》卷九六。","）（按：以上諸诗，《云笈七籤》未云出处，今考應出《南嶽魏夫人傳》。","檢顏真卿《文忠集》卷九《晉紫虛元職工領上真司命南嶽夫人魏夫人仙壇碑銘》云：「于是西王母擊節而歌。","歌畢，馮雙禮珠彈云璈而答歌，餘真人各歌。","」《太平廣記》卷五八《魏夫人》條引《集仙錄》及《本傳》云：「于是四真吟唱，各命玉女，彈琴擊鐘吹簫，合節而發歌。","……是时太極真人命北寒玉女宋聯消，彈九氣之璈，青童命东华玉女煙景珠，擊西盈之鐘。","暘谷神王命神林玉女賈屈廷，吹鳳唳之簫，青虛真人命飞玄玉女鲜于虛，拊九合玉節。","太極真人發《排空之歌》，青童吟『太霞』之曲，神王諷『晨啓』之章，清虛詠『駕飈』之词。","……王母擊節而，三元夫人彈云璈而答歌，餘真各歌。","」魏夫人，傳爲西晉时人，陶弘景《真誥》已載其事，惟較簡略。","晉范邈撰《南真傳》，今不存。","《太平廣記》所錄《本傳》，據陳国符先生《道藏源流考》考證，應即《新唐书·藝文志》著錄之項宗《紫虛元君魏夫人內傳》之節文。","參以顏《碑》所云，其说可信。","項宗，陳考爲唐人。","《云笈七籤》所據，當即項宗之书，《太平廣記》刪去諸诗，猶錄存之，較可寶惜。","）。"]', '诗', 'shi', '', NULL, '四真人降魏夫人歌共五章（幷序） 二 項宗 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('63d98979-1da1-4225-97f2-d3bbcb49e25c', '申光遜夢張沆手出小佛塔上詩（題擬）', '申光遜梦張沆手出小佛塔上诗（題擬）', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["今生不見故人面，明月高高上翠樓。","（見《舊五代史》卷一三一《張沆傳》）（〖1〗《舊五代史》云：「有士人申光遜者，與沆友善。","沆未病時，夢沆手出小佛塔示光遜，視其上有詩十四字云〖略〗。","光遜）（既寤，心惡之，俄聞沆卒。","」張沆卒於廣順二年秋。","）。"]', '["今生不见故人面，明月高高上翠楼。","（见《旧五代史》卷一三一《張沆傳》）（〖1〗《旧五代史》云：「有士人申光遜者，與沆友善。","沆未病时，梦沆手出小佛塔示光遜，視其上有诗十四字云〖略〗。","光遜）（既寤，心惡之，俄闻沆卒。","」張沆卒於廣順二年秋。","）。"]', '诗', 'shi', '', NULL, '申光遜夢張沆手出小佛塔上詩（題擬） 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('12b49371-7122-441d-ab2e-6ffd0c6279da', '錢仁伉聞牡丹空中吁歎之辭（題擬）', '錢仁伉闻牡丹空中吁歎之辞（題擬）', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["一花三百朶，含笑向春風。","明年三月裏，朶朶斷腸紅。","（見《增修詩話總龜》卷四八引《洞微志》）（〖1〗《洞微志》：「錢仁伉，尚父之孫也。","爲元帥府中書檢校司徒，與中軍都虞候金沼鄰居。","沼所居堂東，植牡丹藿一本，着花三百朶，其色如血，加之金含稜。","每瓶子頂上有碎金絲，如自然蛺蝶之狀。","一城以爲殊異。","每歲花開張宴，仁伉預焉。","開寶七年春三月花纔一兩朶開。","仁伉一夕洪飲擊劍，裎服中單，背負大籃，左手攜鋤，腰插六匕首，踰墻而過沼，中外無知者。","鋤取牡丹置籃中，乃平其地。","空中聞有吁歎之聲，細微若遊蜂音，辭曰〖略〗。","仁伉異之，移植於亭後。","明日，沼覺失花，爲非人力所及。","來年花盛開乃宴加沼，沼一見無語，得疾以歸。","至夜憤悶不已，以刀決腸而卒。","腸皆寸寸斷，果符空中之語。","」）。"]', '["一花三百朶，含笑向春风。","明年三月裏，朶朶斷腸紅。","（见《增修诗話總龟》卷四八引《洞微志》）（〖1〗《洞微志》：「錢仁伉，尚父之孫也。","爲元帥府中书檢校司徒，與中軍都虞候金沼鄰居。","沼所居堂东，植牡丹藿一本，着花三百朶，其色如血，加之金含稜。","每瓶子頂上有碎金絲，如自然蛺蝶之狀。","一城以爲殊異。","每歲花开張宴，仁伉預焉。","开寶七年春三月花纔一兩朶开。","仁伉一夕洪饮擊劍，裎服中單，背負大籃，左手携鋤，腰插六匕首，踰墻而過沼，中外無知者。","鋤取牡丹置籃中，乃平其地。","空中闻有吁歎之声，細微若游蜂音，辞曰〖略〗。","仁伉異之，移植於亭後。","明日，沼覺失花，爲非人力所及。","来年花盛开乃宴加沼，沼一见無語，得疾以归。","至夜憤悶不已，以刀決腸而卒。","腸皆寸寸斷，果符空中之語。","」）。"]', '诗', 'shi', '', NULL, '錢仁伉聞牡丹空中吁歎之辭（題擬） 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('92d4dfb8-7993-463c-ae7b-36bfac6bfc08', '大曆間五臺山翁贈無著偈（題擬）', '大曆间五台山翁贈無著偈（題擬）', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["一念淨心是菩提，勝造恒沙七寶塔。","寶塔究盡碎爲塵，一念淨心成正覺。","（《宋高僧傳》卷二十《唐代州五臺山華嚴寺無著傳》）。"]', '["一念淨心是菩提，勝造恒沙七寶塔。","寶塔究尽碎爲塵，一念淨心成正覺。","（《宋高僧傳》卷二十《唐代州五台山华嚴寺無著傳》）。"]', '诗', 'shi', '', NULL, '大曆間五臺山翁贈無著偈（題擬） 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fd879459-d0df-4105-aca4-4a3af8bb4ac1', '大曆間五臺山童子贈無著偈（題擬）', '大曆间五台山童子贈無著偈（題擬）', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["面上無瞋供養具，口裏無瞋吐妙香。","心裏無瞋是珍寶，無染無垢是真常。","（同前）（按：《五燈會元》卷九《無著文喜禪師》云此偈爲杭州無著文喜禪師大中初至五臺山華嚴寺見童子說偈。","）。"]', '["面上無瞋供養具，口裏無瞋吐妙香。","心裏無瞋是珍寶，無染無垢是真常。","（同前）（按：《五灯會元》卷九《無著文喜禪師》云此偈爲杭州無著文喜禪師大中初至五台山华嚴寺见童子说偈。","）。"]', '诗', 'shi', '', NULL, '大曆間五臺山童子贈無著偈（題擬） 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d212a263-502d-44ca-baa3-d529294c6936', '咸通三年文喜在洪州見文殊現身說偈（題擬）', '咸通三年文喜在洪州见文殊現身说偈（題擬）', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["苦匏連根苦，甜瓜徹蔕甜。","修行三大劫，却被老僧嫌。","（《五燈會元》卷九、《西湖游覽志餘》卷十四。","）。"]', '["苦匏連根苦，甜瓜徹蔕甜。","修行三大劫，却被老僧嫌。","（《五灯會元》卷九、《西湖游覽志餘》卷十四。","）。"]', '诗', 'shi', '', NULL, '咸通三年文喜在洪州見文殊現身說偈（題擬） 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e96f0f08-1153-4266-bb6b-9a475721f91e', '于則夢汧陽神紫相公謝供茶贈詩（題擬）', '于則梦汧陽神紫相公謝供茶贈诗（題擬）', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["降酒先生風韻高，攪銀公子更清豪。","碎身粉骨功成後，小碾當銜馬脚槽。","（《說郛》卷六一引《清異錄》）。"]', '["降酒先生风韻高，攪銀公子更清豪。","碎身粉骨功成後，小碾當銜马脚槽。","（《说郛》卷六一引《清異錄》）。"]', '诗', 'shi', '', NULL, '于則夢汧陽神紫相公謝供茶贈詩（題擬） 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d901e050-d93a-4e4d-a725-5fcf1da0d0e6', '蒲津朱衣人獻范仁恕詩', '蒲津朱衣人獻范仁恕诗', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["欄馬遇孫陽，超光力自強。","北林花正發，西江彩筆香。","萬彙須經手，千年事更長。","感君施大惠，從此佐五皇。","（《新編分門古今類事》卷六引《脞說》。","范仁恕爲前、後蜀時人。","）。"]', '["欄马遇孫陽，超光力自強。","北林花正發，西江彩笔香。","万彙須經手，千年事更长。","感君施大惠，從此佐五皇。","（《新編分门古今類事》卷六引《脞说》。","范仁恕爲前、後蜀时人。","）。"]', '诗', 'shi', '', NULL, '蒲津朱衣人獻范仁恕詩 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2a73e8d3-d8d9-4e93-8aeb-a62fbe4f4802', '九嶷邢仙翁詩', '九嶷邢仙翁诗', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["虛皇天詔下仙家，不久星潢借客槎。","壁上風雲三尺劍，牀前龍虎一鑪砂。","行乘海嶼千年鶴，坐折壸宮四序花。","爲愛《陰符》問元義，更隨綵仗入煙霞。","（《三洞羣仙錄》卷十六引《談選》。","云邢仙翁自唐僖宗時隱九嶷山，宋時尚在世。","）。"]', '["虛皇天詔下仙家，不久星潢借客槎。","壁上风云三尺劍，牀前龙虎一鑪砂。","行乘海嶼千年鹤，坐折壸宮四序花。","爲愛《陰符》问元義，更隨綵仗入煙霞。","（《三洞羣仙錄》卷十六引《談選》。","云邢仙翁自唐僖宗时隐九嶷山，宋时尚在世。","）。"]', '诗', 'shi', '', NULL, '九嶷邢仙翁詩 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a91b158b-5a6c-4d46-bd2b-b7a4ec37cc27', '潯陽漁父歌', '潯陽漁父歌', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["竹竿籊籊，河水悠悠。","相忘爲樂，貪餌含鈎。","非夷非惠，聊以忘憂。","（同前卷四引《五代逸史》，云潯陽太守孫愐見之。","）。"]', '["竹竿籊籊，河水悠悠。","相忘爲乐，貪餌含鈎。","非夷非惠，聊以忘憂。","（同前卷四引《五代逸史》，云潯陽太守孫愐见之。","）。"]', '诗', 'shi', '', NULL, '潯陽漁父歌 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('66baf4bd-4467-49da-bd23-ddbb01589236', '僧伽卒後顯形長慶元年夜半於泗州牧蘇公寢室前歌（題擬）', '僧伽卒後显形长慶元年夜半於泗州牧蘇公寢室前歌（題擬）', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["淮南淮北，自此福焉。","自東自西，無不熟矣。","（《宋高僧傳》卷十八《廣漠泗州普光王寺僧伽傳》）（按：僧伽卒於中宗景龍四年，年八十三。","）。"]', '["淮南淮北，自此福焉。","自东自西，無不熟矣。","（《宋高僧傳》卷十八《廣漠泗州普光王寺僧伽傳》）（按：僧伽卒於中宗景龙四年，年八十三。","）。"]', '诗', 'shi', '', NULL, '僧伽卒後顯形長慶元年夜半於泗州牧蘇公寢室前歌（題擬） 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('89f31add-5ab0-464f-9812-fb0bcab46225', '崔球夢妻作詩（題擬）', '崔球梦妻作诗（題擬）', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["數日相望極，須知意思迷。","夢魂不怕險，飛過大江西。","（見《增修詩話總龜前集》卷三五引李頎《古今詩話》）（〖1〗《古今詩話》云：「池陽崔球爲太學生，苦學不歸。","一日，晝夢到其家，見其妻正寫字呼之，不應，與之言，不答，眡其所書，乃詩也，曰〖略〗。","既覺，歷歷記之。","數日書至，其妻寄此詩，一字不差。","驗其寫詩日，乃球得夢之日也。","」）。"]', '["數日相望極，須知意思迷。","梦魂不怕險，飞過大江西。","（见《增修诗話總龟前集》卷三五引李頎《古今诗話》）（〖1〗《古今诗話》云：「池陽崔球爲太学生，苦学不归。","一日，晝梦到其家，见其妻正寫字呼之，不應，與之言，不答，眡其所书，乃诗也，曰〖略〗。","既覺，歷歷記之。","數日书至，其妻寄此诗，一字不差。","驗其寫诗日，乃球得梦之日也。","」）。"]', '诗', 'shi', '', NULL, '崔球夢妻作詩（題擬） 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b252a93d-2fe1-42db-a97b-8d26eaa2191b', '邢鳳挑女仙詩', '邢鳳挑女仙诗', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["意態精神畫亦難，不知何事出仙壇。","此君堂上雲深處，應與蕭郎駕彩鸞。","（見《綠窗新話》卷上《邢鳳遇西湖女仙》）（按：此條原注出「商芸《小說》」，顯誤。","邢鳳事，見《沈下賢文集》卷四、《博異志》、《酉陽雜俎》卷十四及《太平廣記》卷二八二引《異聞錄》。","《綠窗新話》所載，疑出宋人續擬。","）。"]', '["意態精神畫亦难，不知何事出仙壇。","此君堂上云深处，應與蕭郎駕彩鸾。","（见《綠窗新話》卷上《邢鳳遇西湖女仙》）（按：此條原注出「商芸《小说》」，显誤。","邢鳳事，见《沈下賢文集》卷四、《博異志》、《酉陽杂俎》卷十四及《太平廣記》卷二八二引《異闻錄》。","《綠窗新話》所載，疑出宋人續擬。","）。"]', '诗', 'shi', '', NULL, '邢鳳挑女仙詩 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5e978d0c-b903-43cd-92c4-365dc36683d2', '李知遙臨化聞空中說偈', '李知遙臨化闻空中说偈', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["報汝李知遙，成功果自招。","引君生淨土，將爾上金橋。","（見《大正新修大藏經》四七冊宋王日休《龍舒增廣淨土文集》卷五。","）（按：李知遙，唐長安人，善淨土教。","）。"]', '["報汝李知遙，成功果自招。","引君生淨土，將爾上金橋。","（见《大正新修大藏經》四七冊宋王日休《龙舒增廣淨土文集》卷五。","）（按：李知遙，唐长安人，善淨土教。","）。"]', '诗', 'shi', '', NULL, '李知遙臨化聞空中說偈 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7ba08e7e-96e6-4b60-b701-a6159dfe73c5', '青童君別趙旭詩', '青童君別趙旭诗', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["與君宿世有仙緣，衾枕交歡豈偶然。","十載爲期君記取，洞明山上鶴沖天。"]', '["與君宿世有仙緣，衾枕交歡豈偶然。","十載爲期君記取，洞明山上鹤沖天。"]', '诗', 'shi', '', NULL, '青童君別趙旭詩 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f36754b4-d9ae-4250-a423-31ae7bfb8138', '趙旭酬青童君詩', '趙旭酬青童君诗', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["凡庸弱質感天仙，歡合交情僅一年。","十載爲期專在念，莫忘歷歷枕前言。","。"]', '["凡庸弱質感天仙，歡合交情僅一年。","十載爲期專在念，莫忘歷歷枕前言。","。"]', '诗', 'shi', '', NULL, '趙旭酬青童君詩 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('de55ef5c-670f-4ec2-8536-5dabf1121172', '後十三年有人於益州見趙旭形容短小如八九歲小兒模樣行歌於市曰', '後十三年有人於益州见趙旭形容短小如八九歲小兒模樣行歌於市曰', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["塵緣盡兮仙緣來，清風冷然入我懷。","青童仙君事已諧，洞明山上瑞雲埋。","九月九日黃花開，仙人招我上天階，凌空雙鶴何快哉。","（見羅燁《醉翁談錄》己集卷二《趙旭得青童君爲妻》）（按：《太平廣記》卷六五引《通幽錄》載趙旭與青童往來故事，錄詩一首，《全唐詩》卷八六三收入。","《醉翁談錄》所載故事，較《通幽記》爲詳，不注出處。","有二種可能：其一，《廣記》所收爲節本。","其二，宋人在《通幽記》基礎上增益。","同書全錄唐人傳奇之文甚衆。","今尚難遽作論斷。","）。"]', '["塵緣尽兮仙緣来，清风冷然入我懷。","青童仙君事已諧，洞明山上瑞云埋。","九月九日黄花开，仙人招我上天階，凌空雙鹤何快哉。","（见羅燁《醉翁談錄》己集卷二《趙旭得青童君爲妻》）（按：《太平廣記》卷六五引《通幽錄》載趙旭與青童往来故事，錄诗一首，《全唐诗》卷八六三收入。","《醉翁談錄》所載故事，較《通幽記》爲詳，不注出处。","有二種可能：其一，《廣記》所收爲節本。","其二，宋人在《通幽記》基礎上增益。","同书全錄唐人傳奇之文甚衆。","今尚难遽作論斷。","）。"]', '诗', 'shi', '', NULL, '後十三年有人於益州見趙旭形容短小如八九歲小兒模樣行歌於市曰 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('789c9662-eb85-40d8-9a29-c8e18ebaa3b2', '賈真人壁間留詩（題擬）', '賈真人壁间留诗（題擬）', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["此後不知誰有分，壁間留得上天梯。","（見《輿地紀勝》卷一八六《巴州》）（〖1〗《輿地紀勝》：「賈真人，唐人，居難江之紫極宮，白晝登仙，留詩壁間云〖略〗。","」）。"]', '["此後不知誰有分，壁间留得上天梯。","（见《輿地紀勝》卷一八六《巴州》）（〖1〗《輿地紀勝》：「賈真人，唐人，居难江之紫極宮，白晝登仙，留诗壁间云〖略〗。","」）。"]', '诗', 'shi', '', NULL, '賈真人壁間留詩（題擬） 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('81f743fa-923a-45f6-a2b9-4f4f87e8284d', '陳七子題臙脂巖詩', '陳七子題臙脂巖诗', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["朝遊秦地暮嶓臺，暫向人間獨往來。","家在碧潭深處住，從教清淺化蓬萊。","（見同書卷一九○《洋州》）（〖1〗《輿地紀勝》：「陳七子，號休復。","《興元記》謂正元中居褒城，然非定居也。","嘗有人遇之於嶓臺山，山高而秀，不與衆峯雜，勢如聳臺，上有臙脂巖、水簾洞、石焙拂焙竹、燒藥爐、燒藥臺，下有清河水碧。","七子嘗題詩於臙脂巖曰〖略〗。","」）。"]', '["朝游秦地暮嶓台，暫向人间独往来。","家在碧潭深处住，從教清淺化蓬萊。","（见同书卷一九○《洋州》）（〖1〗《輿地紀勝》：「陳七子，號休复。","《兴元記》謂正元中居褒城，然非定居也。","嘗有人遇之於嶓台山，山高而秀，不與衆峯杂，勢如聳台，上有臙脂巖、水簾洞、石焙拂焙竹、燒藥爐、燒藥台，下有清河水碧。","七子嘗題诗於臙脂巖曰〖略〗。","」）。"]', '诗', 'shi', '', NULL, '陳七子題臙脂巖詩 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e0a45fff-24a5-4ed6-8a05-c78b27ce23e9', '唐時有人入觀源洞見石室壁間穉川詩', '唐时有人入观源洞见石室壁间穉川诗', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["松門石徑茸芳草，落花滿院香沉沉。","（見《羅浮志》卷四引南宋人鄭介《續葛仙詩序》引）（按：葛洪字稚川，東晉人。","此二句不可能爲其所作。","）。"]', '["松门石徑茸芳草，落花满院香沉沉。","（见《羅浮志》卷四引南宋人鄭介《續葛仙诗序》引）（按：葛洪字稚川，东晉人。","此二句不可能爲其所作。","）。"]', '诗', 'shi', '', NULL, '唐時有人入觀源洞見石室壁間穉川詩 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c5fa91b3-caba-4ebc-a746-028595d851c2', '詠千歲竇掌和尚（題擬）', '詠千歲竇掌和尚（題擬）', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["勞勞玉齒寒，似迸巖泉急。","有景中夜坐，堦前神鬼泣。","（《嘉泰普燈錄》卷二四、《五燈會元》卷二。","）。"]', '["勞勞玉齒寒，似迸巖泉急。","有景中夜坐，堦前神鬼泣。","（《嘉泰普灯錄》卷二四、《五灯會元》卷二。","）。"]', '诗', 'shi', '', NULL, '詠千歲竇掌和尚（題擬） 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d1504c4d-6e12-466f-a726-aa4e82a60c77', '千歲竇寶掌和尚逰吳偈（題擬）', '千歲竇寶掌和尚逰吳偈（題擬）', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["梁城遇導師，參禪了心地。","飄零二浙游，更盡佳山水。","（同前）。"]', '["梁城遇導師，參禪了心地。","飄零二浙游，更尽佳山水。","（同前）。"]', '诗', 'shi', '', NULL, '千歲竇寶掌和尚逰吳偈（題擬） 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('33eb6e06-36f9-4d57-baf3-e6ba3613ecf5', '千歲寶掌和尚返飛來峰棲石竇題句（題擬）', '千歲寶掌和尚返飞来峰棲石竇題句（題擬）', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["行盡支那四百州，此中偏稱道人遊。","（同前）。"]', '["行尽支那四百州，此中偏稱道人游。","（同前）。"]', '诗', 'shi', '', NULL, '千歲寶掌和尚返飛來峰棲石竇題句（題擬） 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8e8d48da-6f19-454a-baa0-2626c9b11017', '千歲寶掌和尚題朗禪師壁', '千歲寶掌和尚題朗禪師壁', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["白犬御書至，青猿洗鉢回。","（同前）。"]', '["白犬御书至，青猿洗鉢回。","（同前）。"]', '诗', 'shi', '', NULL, '千歲寶掌和尚題朗禪師壁 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c81eb529-b3a9-4450-8c7d-a9102ec72086', '千歲寶掌和尚臨滅示徒慧雲偈', '千歲寶掌和尚臨滅示徒慧云偈', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["本來無生死，今亦示生死。","我得去住心，他生復來此。","（同前）（按：二書云千歲寶掌和尚爲中印度人，生於周威烈王十二年。","魏晉時東遊至中國，時已六百餘歲。","梁時曾晤達摩而開悟。","復遍歷江浙名山，貞觀十五年返飛來。","顯慶二年卒，他們一千七十二。","其事顯然出于附會，唐人著作及較早的幾部燈錄亦不載，似只能視爲小說家言，姑錄附此。","）。"]', '["本来無生死，今亦示生死。","我得去住心，他生复来此。","（同前）（按：二书云千歲寶掌和尚爲中印度人，生於周威烈王十二年。","魏晉时东游至中国，时已六百餘歲。","梁时曾晤達摩而开悟。","复遍歷江浙名山，貞观十五年返飞来。","显慶二年卒，他們一千七十二。","其事显然出于附會，唐人著作及較早的幾部灯錄亦不載，似只能視爲小说家言，姑錄附此。","）。"]', '诗', 'shi', '', NULL, '千歲寶掌和尚臨滅示徒慧雲偈 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('135d7e19-6ac8-4193-a9ce-247f2392932d', '徐登詩句', '徐登诗句', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["鳳立煙霄迥，桃香碧澗逢。","（見《全閩詩話》卷十一）（〖1〗《全閩詩話》云，徐登，「神仙，兄弟姊妹七人，隱於閩國西嶽名山。","乾封時來於絶頂，儀封二年化於潭上。","」儀封，當爲「儀鳳」之誤。","）。"]', '["鳳立煙霄迥，桃香碧澗逢。","（见《全閩诗話》卷十一）（〖1〗《全閩诗話》云，徐登，「神仙，兄弟姊妹七人，隐於閩国西嶽名山。","乾封时来於絶頂，儀封二年化於潭上。","」儀封，當爲「儀鳳」之誤。","）。"]', '诗', 'shi', '', NULL, '徐登詩句 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('afcfd522-42eb-4b7a-b2ac-a036309cb4fd', '陸禹臣贈吳生詩二首 一', '陸禹臣贈吳生诗二首 一', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["世俗風波險，人情巧智長。","要知安分處，修性本真常。"]', '["世俗风波險，人情巧智长。","要知安分处，修性本真常。"]', '诗', 'shi', '', NULL, '陸禹臣贈吳生詩二首 一 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c0fd57c1-d2de-4580-bda3-7a92a319be45', '陸禹臣贈吳生詩二首 二', '陸禹臣贈吳生诗二首 二', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["露下瑤簪滋，雲生石室寒。","星壇鸞鶴舞，丹竃虎龍蟠。","塵世人情窄，壸中景界寬。","憑君高著眼，物外試迴觀。","（見鄭方坤《五代詩話》卷九引《廣遠府志》。","）（按：《全唐詩》卷八六一收後詩之前四句。","）。"]', '["露下瑤簪滋，云生石室寒。","星壇鸾鹤舞，丹竃虎龙蟠。","塵世人情窄，壸中景界寬。","憑君高著眼，物外試迴观。","（见鄭方坤《五代诗話》卷九引《廣远府志》。","）（按：《全唐诗》卷八六一收後诗之前四句。","）。"]', '诗', 'shi', '', NULL, '陸禹臣贈吳生詩二首 二 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8d976e86-4002-48ba-9d7e-d78d65e6b981', '南嶽仙題金牛石壁', '南嶽仙題金牛石壁', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["手持黃鶴來，脚踏金牛背。","塵世無人知，白雲久相待。","（見《沅湘耆舊集》卷十三。","（按：宋以後著作中託名唐代神仙詩，爲數甚夥，尤以呂巖詩爲最多，就余所見，數在千首以上，今皆不取。","）。"]', '["手持黄鹤来，脚踏金牛背。","塵世無人知，白云久相待。","（见《沅湘耆旧集》卷十三。","（按：宋以後著作中託名唐代神仙诗，爲數甚夥，尤以呂巖诗爲最多，就余所见，數在千首以上，今皆不取。","）。"]', '诗', 'shi', '', NULL, '南嶽仙題金牛石壁 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('739636a2-ba8c-4c51-8d48-5fa56eb20b7a', '鳳凰臺獸相和歌（題擬） 一', '鳳凰台獸相和歌（題擬） 一', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["深閨寒鎖難成夢，那得同衾共繍牀。","一自與郎江上別，霜天更自覺宵長。","（婦人歌。","）。"]', '["深閨寒鎖难成梦，那得同衾共繍牀。","一自與郎江上別，霜天更自覺宵长。","（婦人歌。","）。"]', '诗', 'shi', '', NULL, '鳳凰臺獸相和歌（題擬） 一 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1ca69b70-af1d-4dab-8755-b37efa967ef2', '鳳凰臺獸相和歌（題擬） 二', '鳳凰台獸相和歌（題擬） 二', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["纖阿斂照窗風起，漸覺霜寒逼玉牀。","幽恨從來無早暮，不知宵漏向人長。","（男人和。","）。"]', '["纖阿斂照窗风起，漸覺霜寒逼玉牀。","幽恨從来無早暮，不知宵漏向人长。","（男人和。","）。"]', '诗', 'shi', '', NULL, '鳳凰臺獸相和歌（題擬） 二 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4d8a3d6f-a0a8-43e8-8d3c-733f9a668333', '鳳凰臺獸相和歌（題擬） 三', '鳳凰台獸相和歌（題擬） 三', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["愁聽黃鶯喚友聲，空閨曙色夢初驚。","窗前總有花牋紙，難寄妾心字字明。","（又歌）。"]', '["愁听黄鶯喚友声，空閨曙色梦初驚。","窗前總有花牋紙，难寄妾心字字明。","（又歌）。"]', '诗', 'shi', '', NULL, '鳳凰臺獸相和歌（題擬） 三 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('92de5c61-601f-4e43-8d44-e43ed302cc73', '鳳凰臺獸相和歌（題擬） 四', '鳳凰台獸相和歌（題擬） 四', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["遙知把筆怯禽聲，密語書來屢自驚。","若道花牋傳不盡，幽情含處已分明。","（又和。","）。"]', '["遙知把笔怯禽声，密語书来屢自驚。","若道花牋傳不尽，幽情含处已分明。","（又和。","）。"]', '诗', 'shi', '', NULL, '鳳凰臺獸相和歌（題擬） 四 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('be15d144-c56e-4b7b-a604-35ca2c5be275', '鳳凰臺獸相和歌（題擬） 五', '鳳凰台獸相和歌（題擬） 五', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["寂靜璇閨度歲華，並頭蓮葉又如錢。","愁人獨處那堪此，安得君來共枕眠。","（又歌。","）。"]', '["寂静璇閨度歲华，並头蓮葉又如錢。","愁人独处那堪此，安得君来共枕眠。","（又歌。","）。"]', '诗', 'shi', '', NULL, '鳳凰臺獸相和歌（題擬） 五 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1b7a50c9-fe03-428b-b2b7-75f13bc8fafe', '鳳凰臺獸相和歌（題擬） 六', '鳳凰台獸相和歌（題擬） 六', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["愁多四月日如年，金錯囊無買醉錢。","滿地落花愁不寐，非關明月夜遲眠。","（又和。","）。"]', '["愁多四月日如年，金錯囊無買醉錢。","满地落花愁不寐，非关明月夜遲眠。","（又和。","）。"]', '诗', 'shi', '', NULL, '鳳凰臺獸相和歌（題擬） 六 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('09160239-e51a-4ec7-b8c4-3b71b3c433f0', '鳳凰臺獸相和歌（題擬） 七', '鳳凰台獸相和歌（題擬） 七', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["卧病匡牀香屢添，夜深猶有一絲煙。","懷君無計能成夢，更恨砧聲到枕邊。","（又歌。","）。"]', '["卧病匡牀香屢添，夜深猶有一絲煙。","懷君無計能成梦，更恨砧声到枕邊。","（又歌。","）。"]', '诗', 'shi', '', NULL, '鳳凰臺獸相和歌（題擬） 七 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3768b53f-dbe5-4b41-aef0-f9b1562eabd7', '鳳凰臺獸相和歌（題擬） 八', '鳳凰台獸相和歌（題擬） 八', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["寒燈未滅夜愁添，輕帳低垂薄似煙。","忘却閨中病無寐，空教魂夢到君邊。","（又和。","見元林坤《誠齋雜記》卷下，元伊世珍《琅環記》卷上引《誠齋雜記》。","）（〖1〗《誠齋雜記》云：「唐大歷中，有人獨行到鳳凰臺，望見一男子與一婦人相和而歌，聲澈雲際。","」「歌罷，其人迫而視之，乃二獸焉，一類猪而體特高，蔚有文綵，一類龍而小，遍體純黃色。","其人驚而走。","行者問之因語其故，共往觀之，寂然無所見，惟竹書一束在地。","」）。"]', '["寒灯未滅夜愁添，轻帳低垂薄似煙。","忘却閨中病無寐，空教魂梦到君邊。","（又和。","见元林坤《誠斋杂記》卷下，元伊世珍《琅环記》卷上引《誠斋杂記》。","）（〖1〗《誠斋杂記》云：「唐大歷中，有人独行到鳳凰台，望见一男子與一婦人相和而歌，声澈云際。","」「歌罷，其人迫而視之，乃二獸焉，一類猪而體特高，蔚有文綵，一類龙而小，遍體純黄色。","其人驚而走。","行者问之因語其故，共往观之，寂然無所见，惟竹书一束在地。","」）。"]', '诗', 'shi', '', NULL, '鳳凰臺獸相和歌（題擬） 八 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f7dc2f43-ea3a-4138-b39b-67eb9af3cc70', '載初元年沙州歌謠（幷序○題擬。以下歌）', '載初元年沙州歌謠（幷序○題擬。以下歌）', 'a002968d-fb03-407c-9a25-eae63a182674', '唐', '["於昭武王，承天剪商。","誰其下武？聖母神皇。","穆斯九族，綏彼四方。","遵以禮儀，調以陰陽，三農五穀，萬[庾]（庚）千箱。","載興文教，載構明堂。","八窻四闥，上圓下方。","多士濟濟，流水洋洋。","明堂文興，百工時揆。","庶人子來，●鼓不勝。","肅肅在上，無幽不察，無遠不相。","千齡所鐘，萬國攸向。","俗被仁禮，家懷孝讓。","帝德廣運，聖壽遐延。","明明在下，於昭於天。","本枝百代，福祚萬年。","惟彼洛邑，聖母營之；惟彼河水，神皇清之；穆穆帝子，聖母生之；浩浩海瀆，神皇平之。","福兮祐兮，在聖母兮；盛兮昌兮，在神皇兮。","聖母皇皇，撫臨四方。","東西南北，無思不服。","禿髮狂瞽，侵我西土。","皇赫斯怒，爰整其旅。","荒徼之外，各安其所。","穆穆聖君，受天之祐。","聖皇爲誰？神皇聖母。","於萬斯（伯二六九五卷作「斯萬」）年，受天之祐。","永淳之季，皇昇玉京。","如喪其考，人不聊生。","裴、徐作釁，淮海波驚。","皇皇聖母，定[縱]（從）服橫。","綏以大德，威以[佳]（往）兵。","神謀獨運，天鑒孔明。","危邦載靜，亂俗還平。","河圖洛書，龜背龍脅。","聖母臨人，永昌帝業。","既營大室，爰構明堂，如天之堰，如地之方。","句含五色，吐納三光，傍洞八牖，中制九房。","百神薦趾，膺乾之統，得坤之經。","子來之作，不日而成。","不得有得，[□□]非名。","如天之壽，於萬斯齡。","黄山海水，蒲海沙場。","地隣蕃服，家接渾鄉。","昔年寇盜，禾麥調傷。","四人[擾擾]（優優），百姓遑遑。","聖人哀念，賜以惟良。","既撫既育，或引或將。","昔靡單袴，今日重裳。","春蘭秋菊，無絕斯芳。","（見羅振玉《鳴沙石室佚書》影印敦煌寫卷《沙州[都督府]圖經》，即伯二○○五卷。","校以伯二六九五卷，此卷末署「《沙州都督府圖經》卷第三」。","）（按：原詩題作《歌謠》，在《圖經》中自成一目。","末云：「右唐載初元年四月，風俗使于百姓問採得前件歌謠，具狀上讫。","」今據以擬題。","）。"]', '["於昭武王，承天剪商。","誰其下武？聖母神皇。","穆斯九族，綏彼四方。","遵以禮儀，調以陰陽，三農五穀，万[庾]（庚）千箱。","載兴文教，載構明堂。","八窻四闥，上圓下方。","多士濟濟，流水洋洋。","明堂文兴，百工时揆。","庶人子来，●鼓不勝。","肅肅在上，無幽不察，無远不相。","千齡所鐘，万国攸向。","俗被仁禮，家懷孝讓。","帝德廣運，聖壽遐延。","明明在下，於昭於天。","本枝百代，福祚万年。","惟彼洛邑，聖母營之；惟彼河水，神皇清之；穆穆帝子，聖母生之；浩浩海瀆，神皇平之。","福兮祐兮，在聖母兮；盛兮昌兮，在神皇兮。","聖母皇皇，撫臨四方。","东西南北，無思不服。","禿髮狂瞽，侵我西土。","皇赫斯怒，爰整其旅。","荒徼之外，各安其所。","穆穆聖君，受天之祐。","聖皇爲誰？神皇聖母。","於万斯（伯二六九五卷作「斯万」）年，受天之祐。","永淳之季，皇昇玉京。","如喪其考，人不聊生。","裴、徐作釁，淮海波驚。","皇皇聖母，定[縱]（從）服橫。","綏以大德，威以[佳]（往）兵。","神謀独運，天鑒孔明。","危邦載静，亂俗還平。","河圖洛书，龟背龙脅。","聖母臨人，永昌帝業。","既營大室，爰構明堂，如天之堰，如地之方。","句含五色，吐納三光，傍洞八牖，中制九房。","百神薦趾，膺乾之統，得坤之經。","子来之作，不日而成。","不得有得，[□□]非名。","如天之壽，於万斯齡。","黄山海水，蒲海沙場。","地隣蕃服，家接渾乡。","昔年寇盜，禾麦調傷。","四人[擾擾]（優優），百姓遑遑。","聖人哀念，賜以惟良。","既撫既育，或引或將。","昔靡單袴，今日重裳。","春蘭秋菊，無絕斯芳。","（见羅振玉《鳴沙石室佚书》影印敦煌寫卷《沙州[都督府]圖經》，即伯二○○五卷。","校以伯二六九五卷，此卷末署「《沙州都督府圖經》卷第三」。","）（按：原诗題作《歌謠》，在《圖經》中自成一目。","末云：「右唐載初元年四月，风俗使于百姓问採得前件歌謠，具狀上讫。","」今據以擬題。","）。"]', '诗', 'shi', '', NULL, '載初元年沙州歌謠（幷序○題擬。以下歌） 佚名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0748324d-e674-423f-bad6-2a636c11250e', '鄴下百姓爲張嘉祐歌（題從《古謠諺》卷八一）', '鄴下百姓爲張嘉祐歌（題從《古謠諺》卷八一）', 'a002968d-fb03-407c-9a25-eae63a182674', '唐', '["張公張公清且明，蝗蟲避境（闕）成，正（《金石萃編》作「巫」）晴（闕）雨（闕）晴。","（見《全唐文》卷三九六尉遲士良《周太師蜀國公碑陰記》，據《金石萃編》卷八二參校。","）（按：張嘉祐，事跡附《舊唐書》卷九九兄《嘉貞傳》。","）。"]', '["張公張公清且明，蝗蟲避境（闕）成，正（《金石萃編》作「巫」）晴（闕）雨（闕）晴。","（见《全唐文》卷三九六尉遲士良《周太師蜀国公碑陰記》，據《金石萃編》卷八二參校。","）（按：張嘉祐，事跡附《旧唐书》卷九九兄《嘉貞傳》。","）。"]', '诗', 'shi', '', NULL, '鄴下百姓爲張嘉祐歌（題從《古謠諺》卷八一） 佚名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bf1037c9-1ac7-46ae-93f5-aa1ae7034e89', '蜀州民爲鄭知賢歌（題擬）', '蜀州民爲鄭知賢歌（題擬）', 'a002968d-fb03-407c-9a25-eae63a182674', '唐', '["州有長史，一隅歡喜，調吏如琴，養民如子。","（《千唐誌齋藏誌》聖曆二年《周中大夫行蜀州長史上柱國鄭公〖知賢〗墓誌銘》）。"]', '["州有长史，一隅歡喜，調吏如琴，養民如子。","（《千唐誌斋藏誌》聖曆二年《周中大夫行蜀州长史上柱国鄭公〖知賢〗墓誌銘》）。"]', '诗', 'shi', '', NULL, '蜀州民爲鄭知賢歌（題擬） 佚名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3674d020-d095-44f4-a28d-398ff4186c2f', '選人爲崔沔王丘歌（題擬）', '選人爲崔沔王丘歌（題擬）', 'a002968d-fb03-407c-9a25-eae63a182674', '唐', '["沔人澄明澈底清，丘山介直連天峻。","（見三長物齋刊本《顏魯公文集》卷五《通議大夫守太子賓客東都副留守雲騎尉贈尚書左僕射博陵崔孝公宅陋室銘記》引）（記云：「明我〖開元十四年〗，入朝，分掌十銓，公與王丘爲選人所歌曰〖略〗。","時人韙之。","」按：《全唐詩》卷八七六女作時人語，二句互乙，文字有數處不同，故重錄之。","）。"]', '["沔人澄明澈底清，丘山介直連天峻。","（见三长物斋刊本《顏魯公文集》卷五《通議大夫守太子賓客东都副留守云騎尉贈尚书左僕射博陵崔孝公宅陋室銘記》引）（記云：「明我〖开元十四年〗，入朝，分掌十銓，公與王丘爲選人所歌曰〖略〗。","时人韙之。","」按：《全唐诗》卷八七六女作时人語，二句互乙，文字有數处不同，故重錄之。","）。"]', '诗', 'shi', '', NULL, '選人爲崔沔王丘歌（題擬） 佚名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5fd26289-6d85-4445-9097-c120068af4c1', '揚州民爲杜亞誦（題擬） 一', '揚州民爲杜亞誦（題擬） 一', 'a002968d-fb03-407c-9a25-eae63a182674', '唐', '["膴膴原田，自今發始，歲其豐年。","（野人誦）。"]', '["膴膴原田，自今發始，歲其豐年。","（野人誦）。"]', '诗', 'shi', '', NULL, '揚州民爲杜亞誦（題擬） 一 佚名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5babddc6-de74-4793-a3a5-6a180371a63c', '揚州民爲杜亞誦（題擬） 二', '揚州民爲杜亞誦（題擬） 二', 'a002968d-fb03-407c-9a25-eae63a182674', '唐', '["沔彼流水，我邦是紀，鍾美不知。","（都人誦。","均見《文苑英華》卷八一二梁肅《通愛敬陂水門記》引）（按：貞元四年，杜亞爲揚州牧，疏濬邘溝，通愛敬陂，事峻，甚便農商，州民爲之作誦。","梁肅文述其事甚詳，茲不具錄。","）。"]', '["沔彼流水，我邦是紀，鍾美不知。","（都人誦。","均见《文苑英华》卷八一二梁肅《通愛敬陂水门記》引）（按：貞元四年，杜亞爲揚州牧，疏濬邘溝，通愛敬陂，事峻，甚便農商，州民爲之作誦。","梁肅文述其事甚詳，茲不具錄。","）。"]', '诗', 'shi', '', NULL, '揚州民爲杜亞誦（題擬） 二 佚名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8996dd30-2b2d-4b2f-bc31-ce2d1d09ca6e', '濃州人爲刺史歌（題從《古謠諺》卷二七）', '濃州人爲刺史歌（題從《古謠諺》卷二七）', 'a002968d-fb03-407c-9a25-eae63a182674', '唐', '["可憐地上樓，百姓不知修。","上有清使君，下有清江流。","（見《全唐文》卷六一九戎昱《濃州新城頌序》引）。"]', '["可怜地上楼，百姓不知修。","上有清使君，下有清江流。","（见《全唐文》卷六一九戎昱《濃州新城頌序》引）。"]', '诗', 'shi', '', NULL, '濃州人爲刺史歌（題從《古謠諺》卷二七） 佚名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4d04f1cd-24eb-40a4-a4d1-5c1d8b43b20b', '清源郡人爲薛昱歌（題從《古謠諺》卷二七）', '清源郡人爲薛昱歌（題從《古謠諺》卷二七）', 'a002968d-fb03-407c-9a25-eae63a182674', '唐', '["郡號清源，官有清德。","（《嘉慶一統志》卷二六四）（〖1〗《嘉慶一統志》：「唐薛昱，天寶中爲清源太守，郡人哀曰〖歌略〗。","」）。"]', '["郡號清源，官有清德。","（《嘉慶一統志》卷二六四）（〖1〗《嘉慶一統志》：「唐薛昱，天寶中爲清源太守，郡人哀曰〖歌略〗。","」）。"]', '诗', 'shi', '', NULL, '清源郡人爲薛昱歌（題從《古謠諺》卷二七） 佚名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4c879c5b-29bf-45aa-b3e6-0874cac8e672', '河南民爲河南尹某公歌（題從《古謠諺》卷八一擬）', '河南民爲河南尹某公歌（題從《古謠諺》卷八一擬）', 'a002968d-fb03-407c-9a25-eae63a182674', '唐', '["天災流行兮代有，下民昏墊兮時數。","命無以遠兮諒自嗟，豈將天怒，我尹之慰恤兮，實解予之愁苦。","夫得耕兮婦織，日出得作兮日入得息。","此固我君之憂民兮，俾我尹之來即。"]', '["天災流行兮代有，下民昏墊兮时數。","命無以远兮諒自嗟，豈將天怒，我尹之慰恤兮，實解予之愁苦。","夫得耕兮婦织，日出得作兮日入得息。","此固我君之憂民兮，俾我尹之来即。"]', '诗', 'shi', '', NULL, '河南民爲河南尹某公歌（題從《古謠諺》卷八一擬） 佚名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f00476ba-4052-485f-8a97-b5ea5f6f85e1', '又歌', '又歌', 'a002968d-fb03-407c-9a25-eae63a182674', '唐', '["明明在上兮天子聖，四方取則兮我公令。","疲民蘇息兮公之政，一日將去兮，誰泎我之性命。","（均見《全唐文》卷五一○李方郁《修中嶽廟記》引）（〖1〗《修中嶽廟記》：「上四年，用大司計侍郎爲丞相。","其明年，以我相秉樞機，我公掌綸誥，宜爲避嫌，遂自閤下拜河南尹。","將辭，上悄然謂公曰：『前時洛水爲災，洛民大潰，四走無遠，至有沒死者，豈勝其寃耶。","而公今去，我無東顧之患矣。","』公既至理事，先以恤民爲寄，活生瘞死，大開廩庾，賑貧乏，飽饑膓，暖寒體，極於畿甸。","而又蠲逋租，省徭賦，俾安穩其起居，勤強其事業。","故遠邇之民，相賀而歌曰〖略〗。","又歌曰〖略〗。","」杜文瀾《古謠諺》卷八一云：「案《全唐文》稱李方郁爲建中時人。","今考建中爲德宗年號，而建中之號僅有四年，其明年則爲興元元年，文內敘述，又與時事不其相符。","惟據連枝臺座之語，知尹河南者爲時相之昆弟耳。","俟考。","」）。"]', '["明明在上兮天子聖，四方取則兮我公令。","疲民蘇息兮公之政，一日將去兮，誰泎我之性命。","（均见《全唐文》卷五一○李方郁《修中嶽廟記》引）（〖1〗《修中嶽廟記》：「上四年，用大司計侍郎爲丞相。","其明年，以我相秉樞機，我公掌綸誥，宜爲避嫌，遂自閤下拜河南尹。","將辞，上悄然謂公曰：『前时洛水爲災，洛民大潰，四走無远，至有沒死者，豈勝其寃耶。","而公今去，我無东顧之患矣。","』公既至理事，先以恤民爲寄，活生瘞死，大开廩庾，賑貧乏，飽饑膓，暖寒體，極於畿甸。","而又蠲逋租，省徭賦，俾安穩其起居，勤強其事業。","故远邇之民，相賀而歌曰〖略〗。","又歌曰〖略〗。","」杜文瀾《古謠諺》卷八一云：「案《全唐文》稱李方郁爲建中时人。","今考建中爲德宗年號，而建中之號僅有四年，其明年則爲兴元元年，文內敘述，又與时事不其相符。","惟據連枝台座之語，知尹河南者爲时相之昆弟耳。","俟考。","」）。"]', '诗', 'shi', '', NULL, '又歌 佚名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6cce54cc-b783-4dad-a4b2-7593c386e65c', '長道縣人爲王田二公歌', '长道縣人爲王田二公歌', 'a002968d-fb03-407c-9a25-eae63a182674', '唐', '["二公更事，闔境之庇。","二公其休，誰其爲嗣。","（見《文苑英華》卷七九三于邵《田司馬傳》引）（〖1〗《田司馬傳》：「司馬姓田氏，名某，字某。","……知長道縣事，……在公之勤，歲寒不易，嘉聲美政，益震於曩時。","……時特進鴻臚卿兼刺史太原王公，勞於取人，逸於用人，前後褒貶，無有不當。","田公雖讓德有餘，而王公混日不足，遂舉攝司馬仍知縣事。","……故人歌之曰〖略〗。","」）。"]', '["二公更事，闔境之庇。","二公其休，誰其爲嗣。","（见《文苑英华》卷七九三于邵《田司马傳》引）（〖1〗《田司马傳》：「司马姓田氏，名某，字某。","……知长道縣事，……在公之勤，歲寒不易，嘉声美政，益震於曩时。","……时特進鴻臚卿兼刺史太原王公，勞於取人，逸於用人，前後褒貶，無有不當。","田公雖讓德有餘，而王公混日不足，遂舉攝司马仍知縣事。","……故人歌之曰〖略〗。","」）。"]', '诗', 'shi', '', NULL, '長道縣人爲王田二公歌 佚名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('26e16ce0-4213-4841-a367-90dbe14e7ab5', '吉州民爲刺史張儇歌（題擬）', '吉州民爲刺史張儇歌（題擬）', 'a002968d-fb03-407c-9a25-eae63a182674', '唐', '["昔吏𧦧𧦧，今吏詹詹，公能馭之，鉛（一作「雄」）亦爲銛，跖（一作「路」）亦爲亷。","始泄而（一作「紲始」）苦，終優以恬。","昔民嗷嗷，今民咍咍，公能植（一作「撫」）之，鰥寡有怡。","流亡既來，徭役先具，汙茨盡開。","響覆官倉，倉無斗糧，公來幾時，積粟埋梁。","響閱官庫，庫無尺繒，公來幾時，山積層層。","瑞露溶溶，降味公松，瑞蓮漪漪，合蔕公池。","公有異政，神之祚之，民歌路謠（一作「陲」），冀聞京師。","天子明聖（一作「堂」），恩光遠而。","（見杜文瀾《古謠諺》卷七六引《皇甫持正集》卷五《吉州刺史廳壁記》引，注一作者爲《四部叢刊》本《皇甫持正集》之異文。","張儇之名，據同人《廬陵縣令廳壁記》補。","）。"]', '["昔吏𧦧𧦧，今吏詹詹，公能馭之，鉛（一作「雄」）亦爲銛，跖（一作「路」）亦爲亷。","始泄而（一作「紲始」）苦，終優以恬。","昔民嗷嗷，今民咍咍，公能植（一作「撫」）之，鰥寡有怡。","流亡既来，徭役先具，汙茨尽开。","响覆官倉，倉無斗糧，公来幾时，積粟埋梁。","响閱官庫，庫無尺繒，公来幾时，山積層層。","瑞露溶溶，降味公松，瑞蓮漪漪，合蔕公池。","公有異政，神之祚之，民歌路謠（一作「陲」），冀闻京師。","天子明聖（一作「堂」），恩光远而。","（见杜文瀾《古謠諺》卷七六引《皇甫持正集》卷五《吉州刺史廳壁記》引，注一作者爲《四部叢刊》本《皇甫持正集》之異文。","張儇之名，據同人《廬陵縣令廳壁記》補。","）。"]', '诗', 'shi', '', NULL, '吉州民爲刺史張儇歌（題擬） 佚名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d9d4a722-0ba7-4e25-ac2e-ef9064c6f236', '果州百姓爲史謙恕歌（題從《古謠諺》卷五三）', '果州百姓爲史謙恕歌（題從《古謠諺》卷五三）', 'a002968d-fb03-407c-9a25-eae63a182674', '唐', '["使君來何晚，昔日無儲今有飯。","（《海錄碎事》卷十二）（〖1〗《海錄碎事》：史謙恕爲果州刺史，百姓歌之曰〖歌略〗。","）。"]', '["使君来何晚，昔日無儲今有飯。","（《海錄碎事》卷十二）（〖1〗《海錄碎事》：史謙恕爲果州刺史，百姓歌之曰〖歌略〗。","）。"]', '诗', 'shi', '', NULL, '果州百姓爲史謙恕歌（題從《古謠諺》卷五三） 佚名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('014372ed-9302-43b4-b3fe-57ce309aded9', '杭州民誦刺史房孺復（題擬）', '杭州民誦刺史房孺复（題擬）', 'a002968d-fb03-407c-9a25-eae63a182674', '唐', '["雖有饑饉，必有豐年。","大盜既去，我公來臻。","（見李觀《李元菜肴文集》卷四《上杭州房使君書》引）。"]', '["雖有饑饉，必有豐年。","大盜既去，我公来臻。","（见李观《李元菜肴文集》卷四《上杭州房使君书》引）。"]', '诗', 'shi', '', NULL, '杭州民誦刺史房孺復（題擬） 佚名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('57f3aabb-3eb6-4283-9c76-4d447e7f3030', '載筆氏晝百辟之詞', '載笔氏晝百辟之词', 'a002968d-fb03-407c-9a25-eae63a182674', '唐', '["鬱鬱紛紛，維慶霄之雲。","古有堯舜，幸得以爲君。"]', '["鬱鬱紛紛，維慶霄之云。","古有堯舜，幸得以爲君。"]', '诗', 'shi', '', NULL, '載筆氏晝百辟之詞 佚名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('61eba76b-16e5-4178-a6be-50899a8079ad', '象胥氏譯四夷之歌', '象胥氏譯四夷之歌', 'a002968d-fb03-407c-9a25-eae63a182674', '唐', '["煒煒煌煌，天子之祥。","唐有神聖，莫敢不來王。","（均見《元氏長慶集》卷二七《郊天日五色祥雲賦》引）。"]', '["煒煒煌煌，天子之祥。","唐有神聖，莫敢不来王。","（均见《元氏长慶集》卷二七《郊天日五色祥云賦》引）。"]', '诗', 'shi', '', NULL, '象胥氏譯四夷之歌 佚名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1507773a-98fd-425b-b434-68a334933ef8', '道州民爲刺史薛伯高毀鼻亭神歌（題擬）', '道州民爲刺史薛伯高毀鼻亭神歌（題擬）', 'a002968d-fb03-407c-9a25-eae63a182674', '唐', '["我有耉老，公燠其饑。","我有病癃，公起其羸。","髫童之囂，公實智之，鰥孤孔艱，公實遂之。","孰尊惡德，遠矣自古。","孰羨（一作「恣」）淫昏，俾我斯瞽。","千歲之冥，公闢其戶。","我子洎孫。","（見柳宗元《柳河東集》卷二八《道州毀鼻亭神記》引）。"]', '["我有耉老，公燠其饑。","我有病癃，公起其羸。","髫童之囂，公實智之，鰥孤孔艱，公實遂之。","孰尊惡德，远矣自古。","孰羨（一作「恣」）淫昏，俾我斯瞽。","千歲之冥，公闢其戶。","我子洎孫。","（见柳宗元《柳河东集》卷二八《道州毀鼻亭神記》引）。"]', '诗', 'shi', '', NULL, '道州民爲刺史薛伯高毀鼻亭神歌（題擬） 佚名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7d6dccaf-2959-45dd-8318-c4f8140918bb', '劉明德墓誌銘末附歌', '劉明德墓誌銘末附歌', 'a002968d-fb03-407c-9a25-eae63a182674', '唐', '["哀哉哲人，於何是美。","言滿山川，名揚閭□（疑爲「里」字）。","上敬而恭，下問不耻。","直而能謙，和而有禮。","奈何龍劍，俱沉逝水。","風樹蕭蕭，荒墳纍纍。","曾閔攀號，哀情摧毀。","中外痛咽兮苦深，腸斷絕兮不能已已。","（見《山右石刻叢編》卷八《唐故校尉守左武衛涇州四門府折衝都尉員外置同正員賜紫金魚袋上柱國劉府君墓誌銘》。","劉明德字節望，長慶二年卒）。"]', '["哀哉哲人，於何是美。","言满山川，名揚閭□（疑爲「里」字）。","上敬而恭，下问不耻。","直而能謙，和而有禮。","奈何龙劍，俱沉逝水。","风樹蕭蕭，荒墳纍纍。","曾閔攀號，哀情摧毀。","中外痛咽兮苦深，腸斷絕兮不能已已。","（见《山右石刻叢編》卷八《唐故校尉守左武衛涇州四门府折衝都尉員外置同正員賜紫金鱼袋上柱国劉府君墓誌銘》。","劉明德字節望，长慶二年卒）。"]', '诗', 'shi', '', NULL, '劉明德墓誌銘末附歌 佚名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dd8a34a7-c7fc-46c6-ac62-78f0a408f445', '鍾陵郡民爲節度使紇干臮歌（題擬）', '鍾陵郡民爲節度使紇干臮歌（題擬）', 'a002968d-fb03-407c-9a25-eae63a182674', '唐', '["自公之來，闔境讙咍。","飲公之化，若乳嬰孩。","（見《文苑英華》卷八一○韋慤《重修滕王閣記》引）（按：記云大中執徐歲「故我雁門公按節廉問」。","檢《唐方鎮年表》卷五，大中二年紇干臮鎮江西。","臮封雁門公。","）。"]', '["自公之来，闔境讙咍。","饮公之化，若乳嬰孩。","（见《文苑英华》卷八一○韋慤《重修滕王閣記》引）（按：記云大中執徐歲「故我雁门公按節廉问」。","檢《唐方鎮年表》卷五，大中二年紇干臮鎮江西。","臮封雁门公。","）。"]', '诗', 'shi', '', NULL, '鍾陵郡民爲節度使紇干臮歌（題擬） 佚名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0ce69488-9e3d-4bf0-a893-b6b34a8b2a67', '高平野老爲文斤歌（題從《古謠諺》擬）', '高平野老爲文斤歌（題從《古謠諺》擬）', 'a002968d-fb03-407c-9a25-eae63a182674', '唐', '["我聖君兮德巍巍，擇良牧兮治邊陲。","感神功兮雲雨施，稼穡如梁兮又如茨。","無階達天真兮，咸願立乎豐碑。","（見《全唐文》卷七一三潘滔《文公祠記》引）（按：文斤爲區晉高平令，其隱居地後稱文仙山。","元和三年大旱，州縣爲文斤立碑而獲雨，野老相對佇鍤而歌此歌。","詳見潘記。","同治《湖南通志》卷二十《山川》收作尚顏《邵州甘雨歌》，未詳有他據否，今不取。","）。"]', '["我聖君兮德巍巍，擇良牧兮治邊陲。","感神功兮云雨施，稼穡如梁兮又如茨。","無階達天真兮，咸願立乎豐碑。","（见《全唐文》卷七一三潘滔《文公祠記》引）（按：文斤爲區晉高平令，其隐居地後稱文仙山。","元和三年大旱，州縣爲文斤立碑而獲雨，野老相对佇鍤而歌此歌。","詳见潘記。","同治《湖南通志》卷二十《山川》收作尚顏《邵州甘雨歌》，未詳有他據否，今不取。","）。"]', '诗', 'shi', '', NULL, '高平野老爲文斤歌（題從《古謠諺》擬） 佚名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('32dea83a-13e9-46f1-a9f4-b360a3c06a4f', '咸通中小兒歌（題擬）', '咸通中小兒歌（題擬）', 'a002968d-fb03-407c-9a25-eae63a182674', '唐', '["得節不得節，不過十二月。","（見司馬光《資治通鑑考異》卷二十三）。"]', '["得節不得節，不過十二月。","（见司马光《資治通鑑考異》卷二十三）。"]', '诗', 'shi', '', NULL, '咸通中小兒歌（題擬） 佚名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6af9363a-3cfb-4071-aebf-75fc2529e0b3', '吳高祖時華姥山童子歌（題撥）', '吳高祖时华姥山童子歌（題撥）', 'a002968d-fb03-407c-9a25-eae63a182674', '唐', '["靈菌長，金刀響。","（見元劉大彬《茅山志》卷十一、《十國春秋》卷十四《劉得常傳》）。"]', '["靈菌长，金刀响。","（见元劉大彬《茅山志》卷十一、《十国春秋》卷十四《劉得常傳》）。"]', '诗', 'shi', '', NULL, '吳高祖時華姥山童子歌（題撥） 佚名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4a768b18-3e34-43bc-a493-cdaf6c23e0f6', '華亭君歌', '华亭君歌', 'a002968d-fb03-407c-9a25-eae63a182674', '唐', '["華亭君，來幾時，免我疾苦療我饑。","（《檇李詩繫》卷四二）（〖1〗《檇李詩繫》：「唐末，瑯琊張聿爲嘉興軍華亭令。","有以干乞至境上者，聞民此歌，不謁而去。","」）。"]', '["华亭君，来幾时，免我疾苦療我饑。","（《檇李诗繫》卷四二）（〖1〗《檇李诗繫》：「唐末，瑯琊張聿爲嘉兴軍华亭令。","有以干乞至境上者，闻民此歌，不謁而去。","」）。"]', '诗', 'shi', '', NULL, '華亭君歌 佚名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('38b39dcc-a48c-414e-9fea-26a6cf9b2d6c', '眉州民爲張琳歌（題擬）', '眉州民爲張琳歌（題擬）', 'a002968d-fb03-407c-9a25-eae63a182674', '唐', '["前有章仇後張公，疏決水利秔稻豐。","南陽杜詩不可同，何不用之代天工。","（見《十國春秋》卷四十《張琳傳》引）。"]', '["前有章仇後張公，疏決水利秔稻豐。","南陽杜诗不可同，何不用之代天工。","（见《十国春秋》卷四十《張琳傳》引）。"]', '诗', 'shi', '', NULL, '眉州民爲張琳歌（題擬） 佚名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('092e5a33-6f30-4a85-84f8-b693ca0ba743', '周季年東漢國大雪盛唱（題擬）', '周季年东漢国大雪盛唱（題擬）', 'a002968d-fb03-407c-9a25-eae63a182674', '唐', '["生怕赤真人，都來一夜春。","（見《說郛》卷六一《清異錄》）。"]', '["生怕赤真人，都来一夜春。","（见《说郛》卷六一《清異錄》）。"]', '诗', 'shi', '', NULL, '周季年東漢國大雪盛唱（題擬） 佚名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9effd62d-ed3a-47b9-9ddd-dac90a63e8b7', '閩人爲鄭家八虎歌（題擬）', '閩人爲鄭家八虎歌（題擬）', 'a002968d-fb03-407c-9a25-eae63a182674', '唐', '["賈彪之虎兮往代，荀爽八龍兮典載，名不朽兮人不逢，人不逢兮名空在。","滎陽八虎今成羣，見之避之走紛紛。","（見宋趙與泌、黃巖孫纂《仙溪志》卷四，注出《藝文志》、《九國志》、《獨〖疑有誤〗實錄》及《郡志》）（按：唐末詩人鄭良士有子八人，皆善文學，時稱鄭家八虎，爲作歌。","）。"]', '["賈彪之虎兮往代，荀爽八龙兮典載，名不朽兮人不逢，人不逢兮名空在。","滎陽八虎今成羣，见之避之走紛紛。","（见宋趙與泌、黄巖孫纂《仙溪志》卷四，注出《藝文志》、《九国志》、《独〖疑有誤〗實錄》及《郡志》）（按：唐末诗人鄭良士有子八人，皆善文学，时稱鄭家八虎，爲作歌。","）。"]', '诗', 'shi', '', NULL, '閩人爲鄭家八虎歌（題擬） 佚名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7121b1d1-56f5-468f-a64c-0cc172ba00e6', '紇真山神泉歌', '紇真山神泉歌', 'a002968d-fb03-407c-9a25-eae63a182674', '唐', '["紇真山頭有神井，入地千尺絕骨冷。","（見《太平寰宇記》卷五十一《朔州》）。"]', '["紇真山头有神井，入地千尺絕骨冷。","（见《太平寰宇記》卷五十一《朔州》）。"]', '诗', 'shi', '', NULL, '紇真山神泉歌 佚名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7bbf70f8-bb5b-4bef-9324-f5163c3d0cf0', '秦中兒童戲歌', '秦中兒童戲歌', 'a002968d-fb03-407c-9a25-eae63a182674', '唐', '["顛當顛當牢守門，蠮螉寇汝無處奔。","（見《西陽雜俎前集》卷十七）（按：《全唐詩》卷八七六收此歌不全，今重錄。","）。"]', '["顛當顛當牢守门，蠮螉寇汝無处奔。","（见《西陽杂俎前集》卷十七）（按：《全唐诗》卷八七六收此歌不全，今重錄。","）。"]', '诗', 'shi', '', NULL, '秦中兒童戲歌 佚名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7bc149bf-c34a-4db4-a3f9-bbb07ece7c5d', '武德二年江東童謠（以下謠）', '武德二年江东童謠（以下謠）', 'a002968d-fb03-407c-9a25-eae63a182674', '唐', '["江水何泠泠，楊柳何青青。","人今正好樂，已復戍彭城。","（見唐趙蕤《長短經》卷四《霸圖》）（〖1〗《長短經》：「大唐武德二年，王充殺越王侗於洛陽，僭稱尊號，隨氏滅矣。","」注云：「今茲三月江東童謠曰〖略〗。","」）。"]', '["江水何泠泠，楊柳何青青。","人今正好乐，已复戍彭城。","（见唐趙蕤《长短經》卷四《霸圖》）（〖1〗《长短經》：「大唐武德二年，王充殺越王侗於洛陽，僭稱尊號，隨氏滅矣。","」注云：「今茲三月江东童謠曰〖略〗。","」）。"]', '诗', 'shi', '', NULL, '武德二年江東童謠（以下謠） 佚名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('33d772c3-28b7-41e8-8dd1-54d05857b001', '隨日童謠', '隨日童謠', 'a002968d-fb03-407c-9a25-eae63a182674', '唐', '["●水竭，武井溢，此中當有聖人出。","（見蔣斧《沙州文錄補》錄倫敦博物館藏敦煌出《大雲經疏》）（〖1〗《大雲經疏》：「又幷州太皇陵側，舊有一井，俗稱武井。","先來有水，後遂乾枯。","隨末以來，微似有水，自國家之後，水便滿井，至於今日，其水大流闊數丈，流水汾水。","故隨日童謠云〖略〗。","即明水流之義，本應神皇，非關人姓劉也。","至劉武周聞人說決之即流，不決即李，武周無識，不解此語，謂是劉姓，遂起逆心。","家破身亡，一何謬誤，豈知黑河武水水之流義也。","」按：《大雲經疏》爲載初元年沙門十人爲武氏纂政而作之僞經。","此首童謠，亦爲武氏而作，雖稱隨日，似未可信從。","今收入。","）。"]', '["●水竭，武井溢，此中當有聖人出。","（见蔣斧《沙州文錄補》錄倫敦博物館藏敦煌出《大云經疏》）（〖1〗《大云經疏》：「又幷州太皇陵側，旧有一井，俗稱武井。","先来有水，後遂乾枯。","隨末以来，微似有水，自国家之後，水便满井，至於今日，其水大流闊數丈，流水汾水。","故隨日童謠云〖略〗。","即明水流之義，本應神皇，非关人姓劉也。","至劉武周闻人说決之即流，不決即李，武周無識，不解此語，謂是劉姓，遂起逆心。","家破身亡，一何謬誤，豈知黑河武水水之流義也。","」按：《大云經疏》爲載初元年沙门十人爲武氏纂政而作之僞經。","此首童謠，亦爲武氏而作，雖稱隨日，似未可信從。","今收入。","）。"]', '诗', 'shi', '', NULL, '隨日童謠 佚名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('170c02b1-56f3-4a4a-95dd-29e6e036cded', '女武王謠（題從《古謠諺》卷十二）', '女武王謠（題從《古謠諺》卷十二）', 'a002968d-fb03-407c-9a25-eae63a182674', '唐', '["當有女武王者。","（《舊唐書》卷六九《李君羨傳》）。"]', '["當有女武王者。","（《旧唐书》卷六九《李君羨傳》）。"]', '诗', 'shi', '', NULL, '女武王謠（題從《古謠諺》卷十二） 佚名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('234bd673-97c7-44ea-acf0-4082afef6f9f', '軍中謠', '軍中謠', 'a002968d-fb03-407c-9a25-eae63a182674', '唐', '["鄧守嘑，百夫避途。","（明黃佐《廣州人物傳》卷三《鄧文進傳》，原注：「用《唐書》、《一統志》參修」。","鄧於唐高祖時仕至韶州刺史）。"]', '["鄧守嘑，百夫避途。","（明黄佐《廣州人物傳》卷三《鄧文進傳》，原注：「用《唐书》、《一統志》參修」。","鄧於唐高祖时仕至韶州刺史）。"]', '诗', 'shi', '', NULL, '軍中謠 佚名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3a2fdc33-4df8-40a1-905a-7bdd71fbe30e', '長安中謠言', '长安中謠言', 'a002968d-fb03-407c-9a25-eae63a182674', '唐', '["見乞兒，與美酒，以免破屋之咎。","（見宋馬永卿《實賓錄》卷十四）。"]', '["见乞兒，與美酒，以免破屋之咎。","（见宋马永卿《實賓錄》卷十四）。"]', '诗', 'shi', '', NULL, '長安中謠言 佚名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('795fc785-a5b8-4097-b161-27a01b7c79d8', '武后時謠（題擬）', '武后时謠（題擬）', 'a002968d-fb03-407c-9a25-eae63a182674', '唐', '["武后臨朝萬萬年。","（見《分門古今類事》卷十四引《紀異錄》）。"]', '["武后臨朝万万年。","（见《分门古今類事》卷十四引《紀異錄》）。"]', '诗', 'shi', '', NULL, '武后時謠（題擬） 佚名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8d31a0a2-5272-4fe2-87ca-dd3411b6262f', '開元末童謠', '开元末童謠', 'a002968d-fb03-407c-9a25-eae63a182674', '唐', '["山下一羣鹿，大鹿來相逐。","嗁殺（一作「死」）澗下羊，却被猪兒觸。","（見宋劉斧《青瑣高議前集》卷六《驪山記》引）。"]', '["山下一羣鹿，大鹿来相逐。","嗁殺（一作「死」）澗下羊，却被猪兒觸。","（见宋劉斧《青瑣高議前集》卷六《驪山記》引）。"]', '诗', 'shi', '', NULL, '開元末童謠 佚名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('efcc82a5-842e-463b-b021-b8487b90826d', '天寶間謠（題擬）', '天寶间謠（題擬）', 'a002968d-fb03-407c-9a25-eae63a182674', '唐', '["揚安史。","（《貴耳集》卷下）（〖1〗《貴耳集》：「天寶間楊貴妃寵盛，安祿山、史思明之作亂，遂有《楊安史》之謠。","」）。"]', '["揚安史。","（《貴耳集》卷下）（〖1〗《貴耳集》：「天寶间楊貴妃寵盛，安祿山、史思明之作亂，遂有《楊安史》之謠。","」）。"]', '诗', 'shi', '', NULL, '天寶間謠（題擬） 佚名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('26306742-1e54-492e-9f93-81278757e2f9', '上元元年淮西童謠', '上元元年淮西童謠', 'a002968d-fb03-407c-9a25-eae63a182674', '唐', '["手執金刀起東方。","（見《資治通鑑》卷二二一）。"]', '["手執金刀起东方。","（见《資治通鑑》卷二二一）。"]', '诗', 'shi', '', NULL, '上元元年淮西童謠 佚名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2d11c00b-853d-4f9e-8cd3-d04f58c808c0', '零陵郡復乳穴謠（題擬）', '零陵郡复乳穴謠（題擬）', 'a002968d-fb03-407c-9a25-eae63a182674', '唐', '["甿之熙熙，崔公之來。","公化所徹，土石蒙烈。","以爲不信，起視乳穴。","（見《柳河東集》卷二十八《零陵郡復乳穴記》）。"]', '["甿之熙熙，崔公之来。","公化所徹，土石蒙烈。","以爲不信，起視乳穴。","（见《柳河东集》卷二十八《零陵郡复乳穴記》）。"]', '诗', 'shi', '', NULL, '零陵郡復乳穴謠（題擬） 佚名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1375ed61-ea85-433a-8d23-2fbc8da97a86', '成都人爲新修福成寺謠（題擬）', '成都人爲新修福成寺謠（題擬）', 'a002968d-fb03-407c-9a25-eae63a182674', '唐', '["昔公去此，福成以燬。","今公重還，福成復完。","民安軍治，亦如此寺。","（見《劉賓客文集》卷四《成都府新修福成寺記》）。"]', '["昔公去此，福成以燬。","今公重還，福成复完。","民安軍治，亦如此寺。","（见《劉賓客文集》卷四《成都府新修福成寺記》）。"]', '诗', 'shi', '', NULL, '成都人爲新修福成寺謠（題擬） 佚名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('26bde701-85b8-4e74-8bc2-909550df88a2', '荆門縣人送裴均入朝謠（題擬）', '荆门縣人送裴均入朝謠（題擬）', 'a002968d-fb03-407c-9a25-eae63a182674', '唐', '["起我堙廢而遠之，徠我蕩析而安之。","昔室于墟，風搖雨濡，自公優柔，郛閈盈兮。","昔飲於洿，夏溷冬枯，自公感通，觱沸生兮。","淑旂之華兮，四牡之騑。","傒公之還兮，觴以祝之。","（見同書卷九《復荆門縣記》引。","）。"]', '["起我堙廢而远之，徠我蕩析而安之。","昔室于墟，风搖雨濡，自公優柔，郛閈盈兮。","昔饮於洿，夏溷冬枯，自公感通，觱沸生兮。","淑旂之华兮，四牡之騑。","傒公之還兮，觴以祝之。","（见同书卷九《复荆门縣記》引。","）。"]', '诗', 'shi', '', NULL, '荆門縣人送裴均入朝謠（題擬） 佚名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2d54c537-2a06-4ad9-bf58-9778b00adcfc', '鍾陵民爲李公謠（題從《古謠諺》卷八一擬）', '鍾陵民爲李公謠（題從《古謠諺》卷八一擬）', 'a002968d-fb03-407c-9a25-eae63a182674', '唐', '["李公不愉，吾何以居。","李公不室，我何以逸。","（見《文苑英華》卷八二四苻載《鍾陵東湖亭記》）。"]', '["李公不愉，吾何以居。","李公不室，我何以逸。","（见《文苑英华》卷八二四苻載《鍾陵东湖亭記》）。"]', '诗', 'shi', '', NULL, '鍾陵民爲李公謠（題從《古謠諺》卷八一擬） 佚名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1b4ed499-8df3-44c0-80be-30b452839a69', '峽路謠（題從《古謠諺》卷五八擬）', '峽路謠（題從《古謠諺》卷五八擬）', 'a002968d-fb03-407c-9a25-eae63a182674', '唐', '["朝發白帝，暮徹江陵。","（見李肇《國史補》卷下）。"]', '["朝發白帝，暮徹江陵。","（见李肇《国史補》卷下）。"]', '诗', 'shi', '', NULL, '峽路謠（題從《古謠諺》卷五八擬） 佚名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4cb13d14-e69b-47a0-893e-29680beb840b', '隴亭童謠', '隴亭童謠', 'a002968d-fb03-407c-9a25-eae63a182674', '唐', '["秦隴無人塞草青，將軍一去泣空營。","漢家天子車巡狩，行到江南又起兵。","（《記纂淵海》卷二十五）。"]', '["秦隴無人塞草青，將軍一去泣空營。","漢家天子车巡狩，行到江南又起兵。","（《記纂淵海》卷二十五）。"]', '诗', 'shi', '', NULL, '隴亭童謠 佚名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('75776ec4-9559-4442-996f-27514ff4a8e5', '撫州民爲千金陂謠（題從《古謠諺》卷八一擬） 一', '撫州民爲千金陂謠（題從《古謠諺》卷八一擬） 一', 'a002968d-fb03-407c-9a25-eae63a182674', '唐', '["公倅景城，民蘇南皮。","南皮斗門，厥績今存。","在昔河流，西走燕魏，民困隄防，日憂理水。","舟楫壅遏，爲弊仍歲。","公作斗門，分水之勢，亦不役民，荷公之制。"]', '["公倅景城，民蘇南皮。","南皮斗门，厥績今存。","在昔河流，西走燕魏，民困隄防，日憂理水。","舟楫壅遏，爲弊仍歲。","公作斗门，分水之勢，亦不役民，荷公之制。"]', '诗', 'shi', '', NULL, '撫州民爲千金陂謠（題從《古謠諺》卷八一擬） 一 佚名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c4c6dd2f-8ed7-48fa-87f4-8c432fe54511', '撫州民爲千金陂謠（題從《古謠諺》卷八一擬） 二', '撫州民爲千金陂謠（題從《古謠諺》卷八一擬） 二', 'a002968d-fb03-407c-9a25-eae63a182674', '唐', '["公作千金，撫民惠深。","陂水沈沈，樂乎人心。","我田不荒，我苗如林。","憂公之去，誰其嗣音？","（見《全唐文》卷八○五栢虔冉《新創千金陂記》引）（按：據記云：「公指咸通間「撫州刺史渤海李公。","」郁賢皓先生《唐刺史考》疑李公爲李寂。","）。"]', '["公作千金，撫民惠深。","陂水沈沈，乐乎人心。","我田不荒，我苗如林。","憂公之去，誰其嗣音？","（见《全唐文》卷八○五栢虔冉《新創千金陂記》引）（按：據記云：「公指咸通间「撫州刺史渤海李公。","」郁賢皓先生《唐刺史考》疑李公爲李寂。","）。"]', '诗', 'shi', '', NULL, '撫州民爲千金陂謠（題從《古謠諺》卷八一擬） 二 佚名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e308d535-4b7e-449e-94d9-24f846b44988', '咸通初洛中謠 一', '咸通初洛中謠 一', 'a002968d-fb03-407c-9a25-eae63a182674', '唐', '["勿雞言，送汝樹上去；勿鴨言，送汝水中去。"]', '["勿雞言，送汝樹上去；勿鴨言，送汝水中去。"]', '诗', 'shi', '', NULL, '咸通初洛中謠 一 佚名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a62ca9da-1495-46eb-beb1-cf8d1e7e7010', '咸通初洛中謠 二', '咸通初洛中謠 二', 'a002968d-fb03-407c-9a25-eae63a182674', '唐', '["勿笑父母不認汝。","（均見《唐語林》卷七）。"]', '["勿笑父母不認汝。","（均见《唐語林》卷七）。"]', '诗', 'shi', '', NULL, '咸通初洛中謠 二 佚名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b99514c8-8a59-4e3c-9cc2-7c1d37d303e4', '諸軍爲唐末帝謠（題擬）', '諸軍爲唐末帝謠（題擬）', 'a002968d-fb03-407c-9a25-eae63a182674', '唐', '["去（《續世說》作「除」）却生菩薩，扶起一條鐵。","（見《舊五代史》卷四六《唐末帝紀上》、《續世說》卷七）（按：《全唐詩》卷八七八收此謠，僅作四言二句，似據《通鑑》卷二七九所錄，今重錄之。","）。"]', '["去（《續世说》作「除」）却生菩薩，扶起一條鐵。","（见《旧五代史》卷四六《唐末帝紀上》、《續世说》卷七）（按：《全唐诗》卷八七八收此謠，僅作四言二句，似據《通鑑》卷二七九所錄，今重錄之。","）。"]', '诗', 'shi', '', NULL, '諸軍爲唐末帝謠（題擬） 佚名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f8b18bc2-d1b4-4a95-aa68-591e4d2a523c', '楊渥時謠言', '楊渥时謠言', 'a002968d-fb03-407c-9a25-eae63a182674', '唐', '["揚老抽嫰鬢，堪作打鐘槌。","（見《知不足齋叢書》本《五國故事》卷上。","）。"]', '["揚老抽嫰鬢，堪作打鐘槌。","（见《知不足斋叢书》本《五国故事》卷上。","）。"]', '诗', 'shi', '', NULL, '楊渥時謠言 佚名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a81c5880-0588-4927-9ce4-211782454649', '淮南市井小兒唱', '淮南市井小兒唱', 'a002968d-fb03-407c-9a25-eae63a182674', '唐', '["檀來也。","（同前）。"]', '["檀来也。","（同前）。"]', '诗', 'shi', '', NULL, '淮南市井小兒唱 佚名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('86420450-9bbd-47dd-bc89-f562dc581cb5', '武義中童謠（題擬）', '武義中童謠（題擬）', 'a002968d-fb03-407c-9a25-eae63a182674', '唐', '["江北桃花作雪飛，江南李樹玉團枝。","李花結子可憐在，不似楊花沒了期。","（見《釣磯立談》）。"]', '["江北桃花作雪飞，江南李樹玉團枝。","李花結子可怜在，不似楊花沒了期。","（见《釣磯立談》）。"]', '诗', 'shi', '', NULL, '武義中童謠（題擬） 佚名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7b43f393-eda5-41f2-9196-0f537cb99017', '吳越文穆王治世子弘樽府時謠言（題擬）', '吳越文穆王治世子弘樽府时謠言（題擬）', 'a002968d-fb03-407c-9a25-eae63a182674', '唐', '["何處有鹿脯？（見《吳越備史》卷二）。"]', '["何处有鹿脯？（见《吳越備史》卷二）。"]', '诗', 'shi', '', NULL, '吳越文穆王治世子弘樽府時謠言（題擬） 佚名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('db32d06c-c28a-4e4d-88e3-0fd2e3962248', '長興中人爲張生鐵謠（題擬）', '长兴中人爲張生鐵謠（題擬）', 'a002968d-fb03-407c-9a25-eae63a182674', '唐', '["生鐵打石頭，直待圓即休。","（見《分門古今類事》卷二引《紀異錄》）。"]', '["生鐵打石头，直待圓即休。","（见《分门古今類事》卷二引《紀異錄》）。"]', '诗', 'shi', '', NULL, '長興中人爲張生鐵謠（題擬） 佚名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('91da715b-20ca-469b-98e7-7ac0b777af70', '湖南童謠', '湖南童謠', 'a002968d-fb03-407c-9a25-eae63a182674', '唐', '["湖南有長街，栽柳不栽槐。","百姓任奔竄，槌芒織草鞵。","（《十國春秋》卷六九《楚廢王世家》）（按：《全唐詩》卷八七八收此謠爲七言四句，此作五言四句，與前不同，故重收之。","）。"]', '["湖南有长街，栽柳不栽槐。","百姓任奔竄，槌芒织草鞵。","（《十国春秋》卷六九《楚廢王世家》）（按：《全唐诗》卷八七八收此謠爲七言四句，此作五言四句，與前不同，故重收之。","）。"]', '诗', 'shi', '', NULL, '湖南童謠 佚名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1239bd49-062c-4c51-b78d-64c883cfbd3a', '益陽土謠', '益陽土謠', 'a002968d-fb03-407c-9a25-eae63a182674', '唐', '["長沙益陽，一時相卬。","（杜光庭《錄異記》卷七）。"]', '["长沙益陽，一时相卬。","（杜光庭《錄異記》卷七）。"]', '诗', 'shi', '', NULL, '益陽土謠 佚名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4929c314-2563-494b-b606-b6a9558ae953', '盧光稠未舉南康時謠', '盧光稠未舉南康时謠', 'a002968d-fb03-407c-9a25-eae63a182674', '唐', '["盧破黎頭出，李子始花開。","潭深魚正聚，楊柳兩邊栽。","（《九國志》卷二《譚全播傳》）。"]', '["盧破黎头出，李子始花开。","潭深鱼正聚，楊柳兩邊栽。","（《九国志》卷二《譚全播傳》）。"]', '诗', 'shi', '', NULL, '盧光稠未舉南康時謠 佚名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9de12fdf-bce4-46bc-97c3-2b1c7b038f4e', '穀城石人腹讖文', '穀城石人腹讖文', 'a002968d-fb03-407c-9a25-eae63a182674', '唐', '["摩兜鞬，真勿言。","（見宋蘇頌《蘇魏公集》卷五《累年告老恩旨未俞……》詩注引，幷云：「唐劉洎少嘗遇異人，謂之曰：『君當佐太平得富貴，然宜慎兜鞬之戒。","』洎後爲侍中，以議論不常獲譴。","」劉洎，唐太宗時人）。"]', '["摩兜鞬，真勿言。","（见宋蘇頌《蘇魏公集》卷五《累年告老恩旨未俞……》诗注引，幷云：「唐劉洎少嘗遇異人，謂之曰：『君當佐太平得富貴，然宜慎兜鞬之戒。","』洎後爲侍中，以議論不常獲譴。","」劉洎，唐太宗时人）。"]', '诗', 'shi', '', NULL, '穀城石人腹讖文 佚名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1b7d46e0-45e1-4bec-b3a8-3f2acee166c0', '白雲先生張約言葬失其地讖', '白云先生張約言葬失其地讖', 'a002968d-fb03-407c-9a25-eae63a182674', '唐', '["安龍頭，枕龍角。","不三年，自消鑠。","（《新編分門古今類事》卷十七引《摭遺》）。"]', '["安龙头，枕龙角。","不三年，自消鑠。","（《新編分门古今類事》卷十七引《摭遺》）。"]', '诗', 'shi', '', NULL, '白雲先生張約言葬失其地讖 佚名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('86f7ad8b-fd1c-4919-9b8d-1ea4a4404adc', '崔巽遺言', '崔巽遺言', 'a002968d-fb03-407c-9a25-eae63a182674', '唐', '["安龍頭，枕龍耳。","不三年，萬乘至。","（同前）（按：《摭遺》云唐明皇獵於溫泉，見一山上有新墳，張約隨行，云葬失其地，引數語。","詢樵者，知爲崔巽墓。","巽子告以遵父遺言葬此。","詔蠲巽子終身徭役。","）。"]', '["安龙头，枕龙耳。","不三年，万乘至。","（同前）（按：《摭遺》云唐明皇獵於溫泉，见一山上有新墳，張約隨行，云葬失其地，引數語。","詢樵者，知爲崔巽墓。","巽子告以遵父遺言葬此。","詔蠲巽子終身徭役。","）。"]', '诗', 'shi', '', NULL, '崔巽遺言 佚名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9a2252fc-c3e6-4d29-bce1-f6d2c8732b55', '安慶緒將敗時讖 一', '安慶緒將敗时讖 一', 'a002968d-fb03-407c-9a25-eae63a182674', '唐', '["渡河野狐尾獨速，明年死在十八日。"]', '["渡河野狐尾独速，明年死在十八日。"]', '诗', 'shi', '', NULL, '安慶緒將敗時讖 一 佚名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e35c9606-476f-4af5-a632-a100e59f5eff', '安慶緒將敗時讖 二', '安慶緒將敗时讖 二', 'a002968d-fb03-407c-9a25-eae63a182674', '唐', '["胡絕其後，死在合河口。","（均見《安祿山事跡》卷下）。"]', '["胡絕其後，死在合河口。","（均见《安祿山事跡》卷下）。"]', '诗', 'shi', '', NULL, '安慶緒將敗時讖 二 佚名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f3a352a4-590c-45bc-98fe-fa1fd6790f0a', '錫山銘二首 一', '錫山銘二首 一', 'a002968d-fb03-407c-9a25-eae63a182674', '唐', '["有錫兵，天下爭。","無錫寧，天下清。"]', '["有錫兵，天下爭。","無錫寧，天下清。"]', '诗', 'shi', '', NULL, '錫山銘二首 一 佚名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ddd56bdf-f93f-4d49-973a-71a41d810da0', '錫山銘二首 二', '錫山銘二首 二', 'a002968d-fb03-407c-9a25-eae63a182674', '唐', '["有錫沴，無錫乂，天下濟。","（元《無錫縣志》卷四陸羽《慧山寺記》後附，作者署「後世無名人」，原題作「唐錫山銘」）。"]', '["有錫沴，無錫乂，天下濟。","（元《無錫縣志》卷四陸羽《慧山寺記》後附，作者署「後世無名人」，原題作「唐錫山銘」）。"]', '诗', 'shi', '', NULL, '錫山銘二首 二 佚名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('39064132-d076-450c-8680-d8257d25d02a', '牛僧孺讖', '牛僧孺讖', 'a002968d-fb03-407c-9a25-eae63a182674', '唐', '["首尾三麟六十年，兩角犢子恣狂顛，龍蛇相鬭血成川。","（見《李文饒文集·窮愁志》卷四《周秦行紀論》引）（〖1〗《周秦行紀論》云：「餘嘗聞太牢氏好奇怪其身，險易其行，以其姓應國家受命之讖曰〖略〗。","」三句爲僧孺自撰，抑爲敵黨誣構，尚不詳。","宋陳善《捫虱新語》卷十三云「兩角犢子自全忠姓也」，傳璇琮先生《李德裕年譜》據以認爲此讖「本是晚唐五代人譏朱全忠的言辭被用進這篇《周秦行紀論》中去」。","《後村詩話後集》卷一引朱翌說「夫犢子雙角，殆拆朱字耳」，劉克莊以爲朱泚、朱溫皆「有時而驗」。","）。"]', '["首尾三麟六十年，兩角犢子恣狂顛，龙蛇相鬭血成川。","（见《李文饒文集·窮愁志》卷四《周秦行紀論》引）（〖1〗《周秦行紀論》云：「餘嘗闻太牢氏好奇怪其身，險易其行，以其姓應国家受命之讖曰〖略〗。","」三句爲僧孺自撰，抑爲敵黨誣構，尚不詳。","宋陳善《捫虱新語》卷十三云「兩角犢子自全忠姓也」，傳璇琮先生《李德裕年譜》據以認爲此讖「本是晚唐五代人譏朱全忠的言辞被用進這篇《周秦行紀論》中去」。","《後村诗話後集》卷一引朱翌说「夫犢子雙角，殆拆朱字耳」，劉克莊以爲朱泚、朱溫皆「有时而驗」。","）。"]', '诗', 'shi', '', NULL, '牛僧孺讖 佚名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ed38c2ad-b728-4010-a834-d55d0d09181e', '黃巢將興之讖', '黄巢將兴之讖', 'a002968d-fb03-407c-9a25-eae63a182674', '唐', '["黃蛇獨吼，天下人走。","（見《廣卓異記》卷六）。"]', '["黄蛇独吼，天下人走。","（见《廣卓異記》卷六）。"]', '诗', 'shi', '', NULL, '黃巢將興之讖 佚名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('305e359f-891c-4126-a2fa-441a0ef0e3c0', '天復初劉道昌得篆書', '天复初劉道昌得篆书', 'a002968d-fb03-407c-9a25-eae63a182674', '唐', '["八雄爭天下，狫鼠先啾唧。","（自庚子年黃巢見，朱全忠等八人僭號）。","兔子上天牀，（馬建屬兔，又以卯年開國）猿猴三下失。","（朱溫三帝屬猴也）李子生狼藉，（昭宗也）乃牛生叛䍽。","（楊行密王於吳。","斗牛，吳之分也）羣犬嘶首尾，走上中華國。","（即六侵中國也。","見《分門古今類事》卷十四引《賓仙傳》）。"]', '["八雄爭天下，狫鼠先啾唧。","（自庚子年黄巢见，朱全忠等八人僭號）。","兔子上天牀，（马建屬兔，又以卯年开国）猿猴三下失。","（朱溫三帝屬猴也）李子生狼藉，（昭宗也）乃牛生叛䍽。","（楊行密王於吳。","斗牛，吳之分也）羣犬嘶首尾，走上中华国。","（即六侵中国也。","见《分门古今類事》卷十四引《賓仙傳》）。"]', '诗', 'shi', '', NULL, '天復初劉道昌得篆書 佚名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2670b169-f175-40bd-b934-2b99dd328117', '王建時讖', '王建时讖', 'a002968d-fb03-407c-9a25-eae63a182674', '唐', '["數在五樓前。","（見《說郛》卷二十引《洛中紀異錄》）。"]', '["數在五楼前。","（见《说郛》卷二十引《洛中紀異錄》）。"]', '诗', 'shi', '', NULL, '王建時讖 佚名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a354e84b-1dd2-4cc3-9a72-93222a8e6733', '天目山讖', '天目山讖', 'a002968d-fb03-407c-9a25-eae63a182674', '唐', '["天目山前兩乳長，龍飛鳳舞到錢塘。","海門一點巽山小，五百年間出帝王。","（見宋錢儼《吳越備史》卷一、元劉一清《清塘遺事》卷一）（〖1〗《吳越備史》云此出郭璞《臨安地志》，然此首平仄工穩，非郭璞之時所宜有，當出唐末人依託爲錢氏開國之讖。","《銭塘遺事》：「臨安都城，其山肇自天目，讖云〖略〗。","錢氏有國世，臣事中朝，不欲其說之著，更其末云『異姓王』，以遷就之。","高宗駐蹕，其說始驗。","」）。"]', '["天目山前兩乳长，龙飞鳳舞到錢塘。","海门一点巽山小，五百年间出帝王。","（见宋錢儼《吳越備史》卷一、元劉一清《清塘遺事》卷一）（〖1〗《吳越備史》云此出郭璞《臨安地志》，然此首平仄工穩，非郭璞之时所宜有，當出唐末人依託爲錢氏开国之讖。","《銭塘遺事》：「臨安都城，其山肇自天目，讖云〖略〗。","錢氏有国世，臣事中朝，不欲其说之著，更其末云『異姓王』，以遷就之。","高宗駐蹕，其说始驗。","」）。"]', '诗', 'shi', '', NULL, '天目山讖 佚名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('15c209e7-100b-446e-8513-6eaab3c493e3', '莆陽古讖', '莆陽古讖', 'a002968d-fb03-407c-9a25-eae63a182674', '唐', '["自湖腰欲斷，莆陽朱紫半。","水遶壺公山，此時大好看。","（見宋李俊甫《莆陽比事》卷一）（〖1〗原注云：「《搜神秘覽》云：『壺公山欲斷，莆陽朱紫半。","』訛矣。","」）。"]', '["自湖腰欲斷，莆陽朱紫半。","水遶壺公山，此时大好看。","（见宋李俊甫《莆陽比事》卷一）（〖1〗原注云：「《搜神秘覽》云：『壺公山欲斷，莆陽朱紫半。","』訛矣。","」）。"]', '诗', 'shi', '', NULL, '莆陽古讖 佚名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e2cfd2b7-3a1e-49be-bb00-90e36af64b61', '宋齊丘引南唐開國讖（題擬）', '宋齊丘引南唐开国讖（題擬）', 'a002968d-fb03-407c-9a25-eae63a182674', '唐', '["密密作，唐唐得。","（《新編分門古今類事》卷二十引《紀異錄》）（按：《紀異錄》載宋齊丘勸徐知誥即位語云：「又讖曰『密密作』，楊行密開托之初也。","『唐唐得』，非公而誰？","天命定矣，願公速副民望。","」）。"]', '["密密作，唐唐得。","（《新編分门古今類事》卷二十引《紀異錄》）（按：《紀異錄》載宋齊丘勸徐知誥即位語云：「又讖曰『密密作』，楊行密开托之初也。","『唐唐得』，非公而誰？","天命定矣，願公速副民望。","」）。"]', '诗', 'shi', '', NULL, '宋齊丘引南唐開國讖（題擬） 佚名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9630e1b4-9577-4111-ab5b-e399d0241c66', '廣順末京師讖', '廣順末京師讖', 'a002968d-fb03-407c-9a25-eae63a182674', '唐', '["小兒剃元首。","（《說郛》卷二十引秦再思《洛中記異錄》）（按：《洛中記異錄》言此爲「新君之兆也。","未幾世宗嗣位，即替元首也。","」《類說》卷十二引《紀異錄》作「識者曰」，「元首」作「光首」。","）。"]', '["小兒剃元首。","（《说郛》卷二十引秦再思《洛中記異錄》）（按：《洛中記異錄》言此爲「新君之兆也。","未幾世宗嗣位，即替元首也。","」《類说》卷十二引《紀異錄》作「識者曰」，「元首」作「光首」。","）。"]', '诗', 'shi', '', NULL, '廣順末京師讖 佚名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a307eb68-3b69-433a-b0d2-c0489e5588e8', '壺公山古讖', '壺公山古讖', 'a002968d-fb03-407c-9a25-eae63a182674', '唐', '["市連義井歲時半，水遶壺公文物盛。","（見《輿地紀勝》卷一三五《泉州》）。"]', '["市連義井歲时半，水遶壺公文物盛。","（见《輿地紀勝》卷一三五《泉州》）。"]', '诗', 'shi', '', NULL, '壺公山古讖 佚名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0165e247-9b15-409d-a0d7-f84e5516774e', '唐商客王昌瑾得古鏡銘', '唐商客王昌瑾得古镜銘', 'a002968d-fb03-407c-9a25-eae63a182674', '唐', '["三水中，四維下，上帝降子于辰馬。","先操鷄，後搏鴨，此謂運滿一三甲。","暗登天，明理地，遇子年中興大事。","混踪跡，沌名姓，混沌誰知慎與聖。","振法雷，揮神電，于巳年中二龍見。","一則藏身青木中，一則現形黑金東。","智者現，愚者盲，興雲注雨與人征。","或見盛，或視衰，盛衰爲滅惡塵滓。","此一龍，子三四，遞代相承元甲子。","此四維，定滅醜，越海來降須待酉。","此文若見于明王，國泰人安帝永昌。","（《高麗史》卷一。","時當後梁貞明中）。"]', '["三水中，四維下，上帝降子于辰马。","先操鷄，後搏鴨，此謂運满一三甲。","暗登天，明理地，遇子年中兴大事。","混踪跡，沌名姓，混沌誰知慎與聖。","振法雷，揮神電，于巳年中二龙见。","一則藏身青木中，一則現形黑金东。","智者現，愚者盲，兴云注雨與人征。","或见盛，或視衰，盛衰爲滅惡塵滓。","此一龙，子三四，遞代相承元甲子。","此四維，定滅醜，越海来降須待酉。","此文若见于明王，国泰人安帝永昌。","（《高丽史》卷一。","时當後梁貞明中）。"]', '诗', 'shi', '', NULL, '唐商客王昌瑾得古鏡銘 佚名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('92805604-13a6-434d-84ff-1f6f4cdc1173', '患目鼻人互嘲（題擬。以下嘲謔）', '患目鼻人互嘲（題擬。以下嘲謔）', 'a002968d-fb03-407c-9a25-eae63a182674', '唐', '["眼能日月盈，爲有陳根委。","（齆人先詠側眼人）不別似蘭斯，都由鴈門紫。","（患眼人績下句。","見《太平廣記》卷二五七《啓顏錄》）。"]', '["眼能日月盈，爲有陳根委。","（齆人先詠側眼人）不別似蘭斯，都由鴈门紫。","（患眼人績下句。","见《太平廣記》卷二五七《啓顏錄》）。"]', '诗', 'shi', '', NULL, '患目鼻人互嘲（題擬。以下嘲謔） 佚名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f496a23b-58e3-45c0-a7e4-5a2c0a355bd3', '謔高渙', '謔高渙', 'a002968d-fb03-407c-9a25-eae63a182674', '唐', '["一百二十箇蜣螂，推一箇屎塊不上。","（見《唐摭言》卷十五）。"]', '["一百二十箇蜣螂，推一箇屎塊不上。","（见《唐摭言》卷十五）。"]', '诗', 'shi', '', NULL, '謔高渙 佚名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8ff01541-08c3-46a9-afac-6966098f4838', '戲杜審權', '戲杜審權', 'a002968d-fb03-407c-9a25-eae63a182674', '唐', '["座主審權，門生處權，可謂權不失權。","（見《南部新書》卷丁）（按：《全唐詩》卷八七六錄此條不全，今重錄。","）。"]', '["座主審權，门生处權，可謂權不失權。","（见《南部新书》卷丁）（按：《全唐诗》卷八七六錄此條不全，今重錄。","）。"]', '诗', 'shi', '', NULL, '戲杜審權 佚名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c1e7887c-aa18-418d-8f25-5711c2cd939e', '楚州好事者題吳堯卿葦棺', '楚州好事者題吳堯卿葦棺', 'a002968d-fb03-407c-9a25-eae63a182674', '唐', '["信物一角，附至阿鼻地獄。","請去斜封，送上閻羅大王。","（見繆荃蓀刊本《廣陵妖亂志》）。"]', '["信物一角，附至阿鼻地獄。","請去斜封，送上閻羅大王。","（见繆荃蓀刊本《廣陵妖亂志》）。"]', '诗', 'shi', '', NULL, '楚州好事者題吳堯卿葦棺 佚名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('530ddcb4-f179-4a29-998b-11d94c9bd068', '教坊伶人獻語', '教坊伶人獻語', 'a002968d-fb03-407c-9a25-eae63a182674', '唐', '["天子不須憂北寇，守貞面上管幽州。","（見《舊五代史》卷一○九《李守貞傳》）（〖1〗《舊五代史》云：「其年〖指開運二年〗夏，契丹寇邊，以守貞爲北面行營都部署。","少主開曲宴於內殿，以寵其行，教坊伶人獻語云〖略〗。","既罷，守貞有自負之色。","」）。"]', '["天子不須憂北寇，守貞面上管幽州。","（见《旧五代史》卷一○九《李守貞傳》）（〖1〗《旧五代史》云：「其年〖指开運二年〗夏，契丹寇邊，以守貞爲北面行營都部署。","少主开曲宴於內殿，以寵其行，教坊伶人獻語云〖略〗。","既罷，守貞有自負之色。","」）。"]', '诗', 'shi', '', NULL, '教坊伶人獻語 佚名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ac352a43-4cf9-4d08-badf-41e8556036c8', '詠和凝范質（題擬）', '詠和凝范質（題擬）', 'a002968d-fb03-407c-9a25-eae63a182674', '唐', '["從此廟堂添故事，登庸衣缽亦相傳。","（見《邵氏聞見錄》卷七、《澠水燕談錄》卷六）（〖1〗《邵氏聞見錄》云：「范魯公質舉進士，和凝爲主文，愛其文賦，凝自以第十三登第，謂魯公曰：『君之文宜冠多士，屈居第十三者，欲君傳老夫衣鉢耳。","』魯公以爲榮。","至先後爲相。","獻詩者曰〖略〗。","』」）。"]', '["從此廟堂添故事，登庸衣缽亦相傳。","（见《邵氏闻见錄》卷七、《澠水燕談錄》卷六）（〖1〗《邵氏闻见錄》云：「范魯公質舉進士，和凝爲主文，愛其文賦，凝自以第十三登第，謂魯公曰：『君之文宜冠多士，屈居第十三者，欲君傳老夫衣鉢耳。","』魯公以爲榮。","至先後爲相。","獻诗者曰〖略〗。","』」）。"]', '诗', 'shi', '', NULL, '詠和凝范質（題擬） 佚名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4c31e01b-b130-4030-a865-c98c5fce433c', '嘲李度登第（題擬）', '嘲李度登第（題擬）', 'a002968d-fb03-407c-9a25-eae63a182674', '唐', '["主司只誦（《增修詩話總龜》卷三七引作「選」）一聯詩。","（見《玉壺清話》卷七）。"]', '["主司只誦（《增修诗話總龟》卷三七引作「選」）一聯诗。","（见《玉壺清話》卷七）。"]', '诗', 'shi', '', NULL, '嘲李度登第（題擬） 佚名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('38c6e9b7-1bf0-4535-ab31-7b58613be60e', '時爲俳偕語詠天', '时爲俳偕語詠天', 'a002968d-fb03-407c-9a25-eae63a182674', '唐', '["高平上監碧翁翁。","（見《說郛》卷六一《清異錄》）（〖1〗《清異錄》：「晉出帝不善詩。","時爲俳偕語詠天曰：〖略〗。","」）。"]', '["高平上監碧翁翁。","（见《说郛》卷六一《清異錄》）（〖1〗《清異錄》：「晉出帝不善诗。","时爲俳偕語詠天曰：〖略〗。","」）。"]', '诗', 'shi', '', NULL, '時爲俳偕語詠天 佚名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2437d9c3-84e3-4033-9006-f6d2ac5ba988', '泰州民刺禇仁規詩', '泰州民刺禇仁規诗', 'a002968d-fb03-407c-9a25-eae63a182674', '唐', '["多求囊白昧蒼蒼，兼取人間第一黃。","（同前）（〖1〗《清異錄》：「僞唐贜臣禇仁規竊祿泰州刺史，惡政不可縷舉。","有智民請吻儒爲二詩，皆隱語，凡寫數千幅，詣金陵粘貼，事乃上聞。","詩曰〖略〗。","黃自隱金銀字。","」）。"]', '["多求囊白昧蒼蒼，兼取人间第一黄。","（同前）（〖1〗《清異錄》：「僞唐贜臣禇仁規竊祿泰州刺史，惡政不可縷舉。","有智民請吻儒爲二诗，皆隐語，凡寫數千幅，詣金陵粘貼，事乃上闻。","诗曰〖略〗。","黄自隐金銀字。","」）。"]', '诗', 'shi', '', NULL, '泰州民刺禇仁規詩 佚名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('66a15dc2-281e-4b3a-8889-d5d5363b86be', '伶倫改詩嘲陳癩子（題擬）', '伶倫改诗嘲陳癩子（題擬）', 'a002968d-fb03-407c-9a25-eae63a182674', '唐', '["三十年來陳癩子，如今始得碧紗幪。","（見《太平廣記》卷二五七引《玉堂閑話》）（〖1〗《玉堂閑話》謂二句爲短李相公詩，實誤。","二句係改王播《題木蘭院》詩。","王詩見《唐摭言》卷七。","）。"]', '["三十年来陳癩子，如今始得碧紗幪。","（见《太平廣記》卷二五七引《玉堂闲話》）（〖1〗《玉堂闲話》謂二句爲短李相公诗，實誤。","二句係改王播《題木蘭院》诗。","王诗见《唐摭言》卷七。","）。"]', '诗', 'shi', '', NULL, '伶倫改詩嘲陳癩子（題擬） 佚名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b2c6838b-fccb-4fdb-8404-5de4a37bbd38', '嘲蝦蟆', '嘲蝦蟆', 'a002968d-fb03-407c-9a25-eae63a182674', '唐', '["一跳八尺，再跳丈六。","從春至夏，裸袒相逐。","天地取作，掉尾肅肅。","（見《歷代笑話集》本唐朱揆《諧噱錄》）。"]', '["一跳八尺，再跳丈六。","從春至夏，裸袒相逐。","天地取作，掉尾肅肅。","（见《歷代笑話集》本唐朱揆《諧噱錄》）。"]', '诗', 'shi', '', NULL, '嘲蝦蟆 佚名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9dada24f-4deb-4dda-8532-c1a476396813', '顏師古引諺', '顏師古引諺', 'a002968d-fb03-407c-9a25-eae63a182674', '唐', '["賊無歷底中道回。","（《匡謬正俗》卷八，云「內應導引爲歷底」）。"]', '["賊無歷底中道回。","（《匡謬正俗》卷八，云「內應導引爲歷底」）。"]', '诗', 'shi', '', NULL, '顏師古引諺 佚名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('09b755b9-3925-4b97-a88f-e86528b08ba6', '華壤英主爲神迥諺（題擬）', '华壤英主爲神迥諺（題擬）', 'a002968d-fb03-407c-9a25-eae63a182674', '唐', '["大論主，釋迦迥，法界多羅一時領。","（見《續高僧傳》卷十三《神迥傳》）。"]', '["大論主，釋迦迥，法界多羅一时領。","（见《續高僧傳》卷十三《神迥傳》）。"]', '诗', 'shi', '', NULL, '華壤英主爲神迥諺（題擬） 佚名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('753afa51-74ad-47f5-9583-f8d8a81ee562', '貞觀時諺（題擬）', '貞观时諺（題擬）', 'a002968d-fb03-407c-9a25-eae63a182674', '唐', '["無知之叟，又指禪師，亂識之夫，共歸明德。","返迷皆有大照，隨妄普翳真科。","（見前書卷二十《僞徹傳》）。"]', '["無知之叟，又指禪師，亂識之夫，共归明德。","返迷皆有大照，隨妄普翳真科。","（见前书卷二十《僞徹傳》）。"]', '诗', 'shi', '', NULL, '貞觀時諺（題擬） 佚名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d3f11145-a67f-4416-942e-fbb3a7331441', '魏徵引諺', '魏徵引諺', 'a002968d-fb03-407c-9a25-eae63a182674', '唐', '["豐年珠玉，儉年穀熟。","（《魏鄭公諫錄》卷三）。"]', '["豐年珠玉，儉年穀熟。","（《魏鄭公諫錄》卷三）。"]', '诗', 'shi', '', NULL, '魏徵引諺 佚名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('73fe9eeb-eb36-44ae-815e-567d6d2399b4', '王勃引諺', '王勃引諺', 'a002968d-fb03-407c-9a25-eae63a182674', '唐', '["禍不入慎家之門。","（見《王子安集》卷十《平臺秘略論》）。"]', '["禍不入慎家之门。","（见《王子安集》卷十《平台秘略論》）。"]', '诗', 'shi', '', NULL, '王勃引諺 佚名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4295214a-8ac1-480d-9514-6aad10e12b1f', '陳子昂引諺', '陳子昂引諺', 'a002968d-fb03-407c-9a25-eae63a182674', '唐', '["欲知其人，觀其所使。","（見《陳拾遺集》卷八《上軍圖利害事》）。"]', '["欲知其人，观其所使。","（见《陳拾遺集》卷八《上軍圖利害事》）。"]', '诗', 'shi', '', NULL, '陳子昂引諺 佚名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eecda89b-182d-4262-8b75-29cc308341a0', '劉知已引今諺', '劉知已引今諺', 'a002968d-fb03-407c-9a25-eae63a182674', '唐', '["季與厥昆，爭知嫂諱。","（見《史通》卷十九《漢書五行志錯誤篇》）。"]', '["季與厥昆，爭知嫂諱。","（见《史通》卷十九《漢书五行志錯誤篇》）。"]', '诗', 'shi', '', NULL, '劉知已引今諺 佚名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('98519f85-6f0d-4943-876a-5e1ae538b4dd', '張鷟引諺 一', '張鷟引諺 一', 'a002968d-fb03-407c-9a25-eae63a182674', '唐', '["官倉喝雀，猶是向公。","（《施注蘇詩》卷二十一引《朝野僉載》引）。"]', '["官倉喝雀，猶是向公。","（《施注蘇诗》卷二十一引《朝野僉載》引）。"]', '诗', 'shi', '', NULL, '張鷟引諺 一 佚名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('04d314d6-8c26-460d-b021-e728d8cb0c39', '張鷟引諺 二', '張鷟引諺 二', 'a002968d-fb03-407c-9a25-eae63a182674', '唐', '["心欲專，鑿石穿。","（《遊仙窟》）。"]', '["心欲專，鑿石穿。","（《游仙窟》）。"]', '诗', 'shi', '', NULL, '張鷟引諺 二 佚名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c411bd6e-124f-4796-9257-760f36d66375', '張說引諺', '張说引諺', 'a002968d-fb03-407c-9a25-eae63a182674', '唐', '["歲在申酉，乞漿得酒。","（見《張燕公集》卷九《請置屯田表》）。"]', '["歲在申酉，乞漿得酒。","（见《張燕公集》卷九《請置屯田表》）。"]', '诗', 'shi', '', NULL, '張說引諺 佚名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ba2223df-53ae-4b08-969a-81be4f202129', '李邕引諺', '李邕引諺', 'a002968d-fb03-407c-9a25-eae63a182674', '唐', '["河南照，天下少。","（見日本《續藏經》第一五○冊收李邕《唐故白馬寺主翻譯惠沼神塔碑》）（按：此諺當即《續高僧傳》所收「河南一遍照，英聲不從召」之語的別一本，詳後。","）。"]', '["河南照，天下少。","（见日本《續藏經》第一五○冊收李邕《唐故白马寺主翻譯惠沼神塔碑》）（按：此諺當即《續高僧傳》所收「河南一遍照，英声不從召」之語的別一本，詳後。","）。"]', '诗', 'shi', '', NULL, '李邕引諺 佚名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6ddf5cb5-5dd8-4674-a149-b5d0c0e9b76b', '李邕妻溫氏引諺', '李邕妻溫氏引諺', 'a002968d-fb03-407c-9a25-eae63a182674', '唐', '["士無賢不肖，入朝見疾。","（見《新唐書》卷二○二《李邕傳》）。"]', '["士無賢不肖，入朝见疾。","（见《新唐书》卷二○二《李邕傳》）。"]', '诗', 'shi', '', NULL, '李邕妻溫氏引諺 佚名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('22ea841c-d773-4698-9a05-f30992f7803f', '崔仁師引諺', '崔仁師引諺', 'a002968d-fb03-407c-9a25-eae63a182674', '唐', '["殺人刖足，亦皆有禮。","（見《新唐書》卷九九《崔仁師傳》）。"]', '["殺人刖足，亦皆有禮。","（见《新唐书》卷九九《崔仁師傳》）。"]', '诗', 'shi', '', NULL, '崔仁師引諺 佚名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('183611b3-07ee-44a6-9b0e-25a6b83272e4', '趙蕤引諺', '趙蕤引諺', 'a002968d-fb03-407c-9a25-eae63a182674', '唐', '["太白入南斗，天子下殿走。","（見《長短經》卷七《懼誡》）。"]', '["太白入南斗，天子下殿走。","（见《长短經》卷七《懼誡》）。"]', '诗', 'shi', '', NULL, '趙蕤引諺 佚名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c4fa4f40-3e79-42df-90a8-ca149cd8721d', '畫松諺語', '畫松諺語', 'a002968d-fb03-407c-9a25-eae63a182674', '唐', '["畫松當如夜叉臂，鸛鵲啄。","（《宣和畫譜》卷十）。"]', '["畫松當如夜叉臂，鸛鵲啄。","（《宣和畫譜》卷十）。"]', '诗', 'shi', '', NULL, '畫松諺語 佚名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('12a2f6de-d43e-42d0-9b07-165198b4aa0c', '李諲引諺', '李諲引諺', 'a002968d-fb03-407c-9a25-eae63a182674', '唐', '["百日斫柴一日燒。","（見《全唐文》卷四○八李諲《妒神頌序》）。"]', '["百日斫柴一日燒。","（见《全唐文》卷四○八李諲《妒神頌序》）。"]', '诗', 'shi', '', NULL, '李諲引諺 佚名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5fbac449-9bc0-4ad1-9851-94a469dd7b59', '張懷瓘引諺', '張懷瓘引諺', 'a002968d-fb03-407c-9a25-eae63a182674', '唐', '["韓《詩》鄭《易》掛著壁。","（見《書斷》卷上、《墨池編》卷七）。"]', '["韓《诗》鄭《易》掛著壁。","（见《书斷》卷上、《墨池編》卷七）。"]', '诗', 'shi', '', NULL, '張懷瓘引諺 佚名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ee0a43b7-c74c-4e22-aaaa-2b19f18fcd19', '李觀引諺', '李观引諺', 'a002968d-fb03-407c-9a25-eae63a182674', '唐', '["溜之細穿石，綆之細斷榦。","（見《李元賓文集》卷五《請修太學書》）。"]', '["溜之細穿石，綆之細斷榦。","（见《李元賓文集》卷五《請修太学书》）。"]', '诗', 'shi', '', NULL, '李觀引諺 佚名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d1ab3a46-c759-4e75-8f1b-d68f467f1d2c', '省躬諺', '省躬諺', 'a002968d-fb03-407c-9a25-eae63a182674', '唐', '["義盡省躬。","（《宋高僧傳》卷十五《唐揚州慧照寺省躬傳》）。"]', '["義尽省躬。","（《宋高僧傳》卷十五《唐揚州慧照寺省躬傳》）。"]', '诗', 'shi', '', NULL, '省躬諺 佚名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e09f732b-5529-44d3-b333-1e2bfa9b336a', '襄陽古諺', '襄陽古諺', 'a002968d-fb03-407c-9a25-eae63a182674', '唐', '["襄陽無西。","（《元和郡縣圖志》卷二十一）。"]', '["襄陽無西。","（《元和郡縣圖志》卷二十一）。"]', '诗', 'shi', '', NULL, '襄陽古諺 佚名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d1d32af4-11aa-426f-aec5-869676d6a262', '邔縣古諺', '邔縣古諺', 'a002968d-fb03-407c-9a25-eae63a182674', '唐', '["邔無東。","（同前）。"]', '["邔無东。","（同前）。"]', '诗', 'shi', '', NULL, '邔縣古諺 佚名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6db65ef4-e072-4d24-bb7b-2a95afce6ed8', '白居易引諺', '白居易引諺', 'a002968d-fb03-407c-9a25-eae63a182674', '唐', '["鄭玄家牛，觸墻成八字。","（見《白氏長慶集》卷二六《雙鸚鵡》詩注引）。"]', '["鄭玄家牛，觸墻成八字。","（见《白氏长慶集》卷二六《雙鸚鵡》诗注引）。"]', '诗', 'shi', '', NULL, '白居易引諺 佚名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('17d8e7aa-db3d-494c-93f7-493659a53e0a', '范攎引諺', '范攎引諺', 'a002968d-fb03-407c-9a25-eae63a182674', '唐', '["徍談巷議，倏有裨於王化。","（《雲溪友議序》）。"]', '["徍談巷議，倏有裨於王化。","（《云溪友議序》）。"]', '诗', 'shi', '', NULL, '范攎引諺 佚名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('08b97768-12af-4756-9054-af97925b1e9d', '王叡引諺', '王叡引諺', 'a002968d-fb03-407c-9a25-eae63a182674', '唐', '["鳥窮則啄，獸窮則角，人窮則詐。","（見《類說》卷二五《炙轂子》引）。"]', '["鸟窮則啄，獸窮則角，人窮則詐。","（见《類说》卷二五《炙轂子》引）。"]', '诗', 'shi', '', NULL, '王叡引諺 佚名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('508f1134-589f-4819-9e18-38a56721a0f3', '《獨異志》引諺', '《独異志》引諺', 'a002968d-fb03-407c-9a25-eae63a182674', '唐', '["驕奢之災，禍非一致。","（《獨異志》卷下）。"]', '["驕奢之災，禍非一致。","（《独異志》卷下）。"]', '诗', 'shi', '', NULL, '《獨異志》引諺 佚名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('641e60a7-386a-4390-8c39-41caca61fd48', '李匡文引諺', '李匡文引諺', 'a002968d-fb03-407c-9a25-eae63a182674', '唐', '["千里井，不及唾。","（見《資暇集》卷下）（按：蘇鶚《蘇氏演義》卷下引杜詩「畏人千里井」注引同。","）。"]', '["千里井，不及唾。","（见《資暇集》卷下）（按：蘇鶚《蘇氏演義》卷下引杜诗「畏人千里井」注引同。","）。"]', '诗', 'shi', '', NULL, '李匡文引諺 佚名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('905ffb74-d7b2-4866-9886-88d349ade000', '稷下諺', '稷下諺', 'a002968d-fb03-407c-9a25-eae63a182674', '唐', '["學識何如觀點書。","（見《資暇集》卷下）。"]', '["学識何如观点书。","（见《資暇集》卷下）。"]', '诗', 'shi', '', NULL, '稷下諺 佚名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5679a880-9275-4b01-8d89-6e5a53aeef9e', '木奴諺', '木奴諺', 'a002968d-fb03-407c-9a25-eae63a182674', '唐', '["木奴千，無凶年。","（見段公路《北戶錄》卷三、《侯鯖錄》卷四，又見《四時纂要》卷三）。"]', '["木奴千，無凶年。","（见段公路《北戶錄》卷三、《侯鯖錄》卷四，又见《四时纂要》卷三）。"]', '诗', 'shi', '', NULL, '木奴諺 佚名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8a79fa93-d6d4-4d13-9321-683c7b2efbf3', '瓊振二州人（題擬）', '瓊振二州人（題擬）', 'a002968d-fb03-407c-9a25-eae63a182674', '唐', '["跳石牛骨碌，好笑又（《武英殿聚珍版叢書》本《嶺表錄異》無「又」字）好哭。","（見《太平御覽》卷九○○引劉恂《嶺表錄異》）。"]', '["跳石牛骨碌，好笑又（《武英殿聚珍版叢书》本《嶺表錄異》無「又」字）好哭。","（见《太平御覽》卷九○○引劉恂《嶺表錄異》）。"]', '诗', 'shi', '', NULL, '瓊振二州人（題擬） 佚名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eeffaba5-6ca0-47f9-a425-57222d349175', '安定郡里諺（題擬）', '安定郡里諺（題擬）', 'a002968d-fb03-407c-9a25-eae63a182674', '唐', '["峴山張蓋雨滂沱。","（《孔帖》卷二作「沛」。","見皇甫枚《三水小牘》卷下）。"]', '["峴山張蓋雨滂沱。","（《孔帖》卷二作「沛」。","见皇甫枚《三水小牘》卷下）。"]', '诗', 'shi', '', NULL, '安定郡里諺（題擬） 佚名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5bc96ed6-4021-48a7-b241-1f2980acb478', '徐知諤引諺', '徐知諤引諺', 'a002968d-fb03-407c-9a25-eae63a182674', '唐', '["人生百歲，七十者稀。","（《玉壺清話》卷九）。"]', '["人生百歲，七十者稀。","（《玉壺清話》卷九）。"]', '诗', 'shi', '', NULL, '徐知諤引諺 佚名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d2fff7f2-3b82-411f-b07b-ffbd0c17f596', '孫光憲引諺', '孫光憲引諺', 'a002968d-fb03-407c-9a25-eae63a182674', '唐', '["好事不出門，惡事行千里。","（《北夢瑣言》卷六，參《古謠諺》卷五十八）。"]', '["好事不出门，惡事行千里。","（《北梦瑣言》卷六，參《古謠諺》卷五十八）。"]', '诗', 'shi', '', NULL, '孫光憲引諺 佚名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a347a8e6-1a4d-49ba-bc6f-6bf783a9e72d', '時人爲張全義諺（題擬）', '时人爲張全義諺（題擬）', 'a002968d-fb03-407c-9a25-eae63a182674', '唐', '["王禱雨，買雨具。","無畏之神耶？齊王之潔誠耶？（見宋張齊賢《洛陽縉紳舊聞記》卷二）。"]', '["王禱雨，買雨具。","無畏之神耶？齊王之潔誠耶？（见宋張齊賢《洛陽縉紳旧闻記》卷二）。"]', '诗', 'shi', '', NULL, '時人爲張全義諺（題擬） 佚名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bf8139e9-46ee-4229-85dc-701407b0e225', '王蜀時人爲高道興諺（題擬）', '王蜀时人爲高道兴諺（題擬）', 'a002968d-fb03-407c-9a25-eae63a182674', '唐', '["高君墜筆亦成畫。","（見宋郭若虛《圖畫見聞志》卷二）。"]', '["高君墜笔亦成畫。","（见宋郭若虛《圖畫见闻志》卷二）。"]', '诗', 'shi', '', NULL, '王蜀時人爲高道興諺（題擬） 佚名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('75ed719c-9310-4dd1-ba13-699978ed8833', '王仁裕引諺 一', '王仁裕引諺 一', 'a002968d-fb03-407c-9a25-eae63a182674', '唐', '["一飲一啄，繫之於分。","（見《太平廣記》卷一五八《玉堂閒話》引）。"]', '["一饮一啄，繫之於分。","（见《太平廣記》卷一五八《玉堂閒話》引）。"]', '诗', 'shi', '', NULL, '王仁裕引諺 一 佚名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('38c0aa32-6f66-43b9-9b4a-12492aad0c4a', '王仁裕引諺 二', '王仁裕引諺 二', 'a002968d-fb03-407c-9a25-eae63a182674', '唐', '["孤雲兩角，去天一握。","（見《類說》卷五四《玉堂閑話》引）（〖1〗《玉堂閑話》云：「興元中，有南路通巴州，其峭巖頂謂之『孤雲兩角』，諺云〖略〗。","」）。"]', '["孤云兩角，去天一握。","（见《類说》卷五四《玉堂闲話》引）（〖1〗《玉堂闲話》云：「兴元中，有南路通巴州，其峭巖頂謂之『孤云兩角』，諺云〖略〗。","」）。"]', '诗', 'shi', '', NULL, '王仁裕引諺 二 佚名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bb0bd478-b7b5-4a42-ada3-f3942f9e1ee7', '楊億引諺', '楊億引諺', 'a002968d-fb03-407c-9a25-eae63a182674', '唐', '["不到長安辜負眼，不到兩浙辜負口。","（見《類說》卷五三引《楊文公談苑》）（按：長安於唐末毀於兵災，此諺應爲其前之作。","）。"]', '["不到长安辜負眼，不到兩浙辜負口。","（见《類说》卷五三引《楊文公談苑》）（按：长安於唐末毀於兵災，此諺應爲其前之作。","）。"]', '诗', 'shi', '', NULL, '楊億引諺 佚名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('61e6f39a-20e3-4db4-b139-c6281bc8f222', '時人爲省中諺（題從《古謠諺》卷五九擬）', '时人爲省中諺（題從《古謠諺》卷五九擬）', 'a002968d-fb03-407c-9a25-eae63a182674', '唐', '["司門都官，屯田水部，入省不數。","（見錢易《南部新書》卷丁）（按：《全唐詩》卷八七六所錄不全。","）。"]', '["司门都官，屯田水部，入省不數。","（见錢易《南部新书》卷丁）（按：《全唐诗》卷八七六所錄不全。","）。"]', '诗', 'shi', '', NULL, '時人爲省中諺（題從《古謠諺》卷五九擬） 佚名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('70d4e671-5be2-493b-87df-4e8e8cf542d0', '贊寧引諺 一', '贊寧引諺 一', 'a002968d-fb03-407c-9a25-eae63a182674', '唐', '["東家種竹，西家種地。"]', '["东家種竹，西家種地。"]', '诗', 'shi', '', NULL, '贊寧引諺 一 佚名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fa7c2ea5-be19-4c17-8ff9-2142bd0a7e37', '贊寧引諺 二', '贊寧引諺 二', 'a002968d-fb03-407c-9a25-eae63a182674', '唐', '["臘月煮筍羹，大人道便是。"]', '["臘月煮筍羹，大人道便是。"]', '诗', 'shi', '', NULL, '贊寧引諺 二 佚名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('31e8c8a4-79c6-4a8d-a3a2-470f9634fbd1', '贊寧引諺 三', '贊寧引諺 三', 'a002968d-fb03-407c-9a25-eae63a182674', '唐', '["恭敬不如從命，受訓莫如從順。","（見《百川學海》本贊寧《筍譜》）。"]', '["恭敬不如從命，受訓莫如從順。","（见《百川学海》本贊寧《筍譜》）。"]', '诗', 'shi', '', NULL, '贊寧引諺 三 佚名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bb1d1983-5489-4638-977b-def8929562db', '贊寧引諺 四', '贊寧引諺 四', 'a002968d-fb03-407c-9a25-eae63a182674', '唐', '["青成藍，藍謝青。","師何常？在明經。","（《宋高僧傳》卷十二《唐福州雪峯廣福院義存傳》）。"]', '["青成藍，藍謝青。","師何常？在明經。","（《宋高僧傳》卷十二《唐福州雪峯廣福院義存傳》）。"]', '诗', 'shi', '', NULL, '贊寧引諺 四 佚名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('edc91501-e63e-428b-aa1a-a69f29189aef', '陶穀引諺', '陶穀引諺', 'a002968d-fb03-407c-9a25-eae63a182674', '唐', '["闌單帶，疊垛衫，肥人也覺瘦嚴巖。","（見《說郛》卷六一《清異錄》）（〖1〗《清異錄》釋云：「蘭單，破裂之狀。","疊垛，補衲蓋掩之多。","」）。"]', '["闌單带，叠垛衫，肥人也覺瘦嚴巖。","（见《说郛》卷六一《清異錄》）（〖1〗《清異錄》釋云：「蘭單，破裂之狀。","叠垛，補衲蓋掩之多。","」）。"]', '诗', 'shi', '', NULL, '陶穀引諺 佚名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d0682912-a9ab-4251-9c27-8fd1c470d0ed', '南鄭縣旱山諺', '南鄭縣旱山諺', 'a002968d-fb03-407c-9a25-eae63a182674', '唐', '["牛頭戴，旱山晦，家中乾穀莫相貸。","（見《太平寰宇記》卷一三三）。"]', '["牛头戴，旱山晦，家中乾穀莫相貸。","（见《太平寰宇記》卷一三三）。"]', '诗', 'shi', '', NULL, '南鄭縣旱山諺 佚名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e578cbed-8675-4366-92da-fd2060c2765c', '鄜州雲巖縣庫利川土諺', '鄜州云巖縣庫利川土諺', 'a002968d-fb03-407c-9a25-eae63a182674', '唐', '["昔有奴賊，居此川內。","（稽胡呼奴爲庫利。","見同書卷三五）（按：《太平寰宇記》爲樂史於宋初所著書。","其所引二諺，應爲唐五代時之作。","）。"]', '["昔有奴賊，居此川內。","（稽胡呼奴爲庫利。","见同书卷三五）（按：《太平寰宇記》爲乐史於宋初所著书。","其所引二諺，應爲唐五代时之作。","）。"]', '诗', 'shi', '', NULL, '鄜州雲巖縣庫利川土諺 佚名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('188f74e4-10d8-4749-8673-0c68c738e88b', '諺', '諺', 'a002968d-fb03-407c-9a25-eae63a182674', '唐', '["憫忠高閣，去天一握。","（《天府廣記》卷三八）。"]', '["憫忠高閣，去天一握。","（《天府廣記》卷三八）。"]', '诗', 'shi', '', NULL, '諺 佚名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f9f44158-3795-4f00-9695-5ebece866f96', '時人爲神照語（題擬。以下語）', '时人爲神照語（題擬。以下語）', 'a002968d-fb03-407c-9a25-eae63a182674', '唐', '["河南一遍照，英聲不徒召。","（見《續高僧傳》卷十三《神照傳》）。"]', '["河南一遍照，英声不徒召。","（见《續高僧傳》卷十三《神照傳》）。"]', '诗', 'shi', '', NULL, '時人爲神照語（題擬。以下語） 佚名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8f2eaf17-c251-491c-ad7d-95992ca48345', '唐史官引語論冀州民俗（題擬）', '唐史官引語論冀州民俗（題擬）', 'a002968d-fb03-407c-9a25-eae63a182674', '唐', '["魏郡清河，天公無奈何。","（《隋書》卷二十五《地理志中》）。"]', '["魏郡清河，天公無奈何。","（《隋书》卷二十五《地理志中》）。"]', '诗', 'shi', '', NULL, '唐史官引語論冀州民俗（題擬） 佚名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fd025a8d-27d8-4c39-96a0-f441a6a044c5', '時人爲玄奘法師兄弟語（題擬）', '时人爲玄奘法師兄弟語（題擬）', 'a002968d-fb03-407c-9a25-eae63a182674', '唐', '["昔聞荀氏八龍，今見陳門雙驥。","（見于志寧《〈大唐西域記〉序》引）。"]', '["昔闻荀氏八龙，今见陳门雙驥。","（见于志寧《〈大唐西域記〉序》引）。"]', '诗', 'shi', '', NULL, '時人爲玄奘法師兄弟語（題擬） 佚名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5be19ffa-f683-46c4-b92b-2910a7e19fd2', '時人爲來虞二氏子語（題從《古謠諺》卷十六）', '时人爲来虞二氏子語（題從《古謠諺》卷十六）', 'a002968d-fb03-407c-9a25-eae63a182674', '唐', '["護兒兒作相，世南男作匠。","（《弘簡錄》卷十三）（按：《新唐書》卷一○五《來濟傳》云此爲許敬宗語。","）。"]', '["護兒兒作相，世南男作匠。","（《弘簡錄》卷十三）（按：《新唐书》卷一○五《来濟傳》云此爲許敬宗語。","）。"]', '诗', 'shi', '', NULL, '時人爲來虞二氏子語（題從《古謠諺》卷十六） 佚名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('18ea8c93-7923-453a-87b7-dbda6778434d', '鸚鵡谷水世語（題從《古謠諺》卷三十二）', '鸚鵡谷水世語（題從《古謠諺》卷三十二）', 'a002968d-fb03-407c-9a25-eae63a182674', '唐', '["此水清，天下平。","（《唐會要》卷二十八）（按：《唐會要》云：「武德元年十二月，新豐鸚鵡谷水清。","世傳云云。","」）。"]', '["此水清，天下平。","（《唐會要》卷二十八）（按：《唐會要》云：「武德元年十二月，新豐鸚鵡谷水清。","世傳云云。","」）。"]', '诗', 'shi', '', NULL, '鸚鵡谷水世語（題從《古謠諺》卷三十二） 佚名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0ec8c78b-9714-4aca-aea3-90b7cbda4229', '中宗時人爲李元恭語（題擬）', '中宗时人爲李元恭語（題擬）', 'a002968d-fb03-407c-9a25-eae63a182674', '唐', '["長寧安樂幷狂顛，既教翻地亦翻天。","賣弄大家猶未足，便使元恭來取錢。","（《冊府元龜》卷六三八《銓選部·貪賄》。","此首及下首承陶敏先生見告）（〖1〗《冊府元龜》云：「李元恭中宗時以大理少卿爲長寧、安樂二公主所引用，令知吏部侍郎，分往東都掌選事，亦以贓汙聞於天下。","故時人爲之語曰〖語略〗。","」）。"]', '["长寧安乐幷狂顛，既教翻地亦翻天。","賣弄大家猶未足，便使元恭来取錢。","（《冊府元龟》卷六三八《銓選部·貪賄》。","此首及下首承陶敏先生见告）（〖1〗《冊府元龟》云：「李元恭中宗时以大理少卿爲长寧、安乐二公主所引用，令知吏部侍郎，分往东都掌選事，亦以贓汙闻於天下。","故时人爲之語曰〖語略〗。","」）。"]', '诗', 'shi', '', NULL, '中宗時人爲李元恭語（題擬） 佚名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8f6b928d-ebc1-4adb-a770-36d3451e8a44', '中宗時（京師）人爲鄭愔語（題擬）', '中宗时（京師）人爲鄭愔語（題擬）', 'a002968d-fb03-407c-9a25-eae63a182674', '唐', '["殺鄭愔，天必陰。","（同前）（〖1〗《冊府元龜》：「鄭愔謟事武三思及韋氏悖逆庶人，歷選吏侍郎。","愔掌選，專以賣官爲務，人多怨讟。","時京師大旱，爲之語曰〖語略〗。","其爲人所惡如此。","」）。"]', '["殺鄭愔，天必陰。","（同前）（〖1〗《冊府元龟》：「鄭愔謟事武三思及韋氏悖逆庶人，歷選吏侍郎。","愔掌選，專以賣官爲務，人多怨讟。","时京師大旱，爲之語曰〖語略〗。","其爲人所惡如此。","」）。"]', '诗', 'shi', '', NULL, '中宗時（京師）人爲鄭愔語（題擬） 佚名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cf664351-8194-4855-8f10-782ec96445b0', '時人爲蘇頲語（題擬）', '时人爲蘇頲語（題擬）', 'a002968d-fb03-407c-9a25-eae63a182674', '唐', '["蘇瓌有子，李嶠無兒。","（見《太平御覽》卷四一四引《朝野僉載》）。"]', '["蘇瓌有子，李嶠無兒。","（见《太平御覽》卷四一四引《朝野僉載》）。"]', '诗', 'shi', '', NULL, '時人爲蘇頲語（題擬） 佚名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('64da1c35-4abc-4cfc-94b8-15438e519d3a', '京中人作二豹咒（題擬）', '京中人作二豹咒（題擬）', 'a002968d-fb03-407c-9a25-eae63a182674', '唐', '["苦違心負教，橫遭三豹。","（見《朝野僉載》卷二）（按：《全唐詩》卷八七六作三言二句，係錄自《新唐書》卷一八六《王旭傳》。","今重錄。","）。"]', '["苦違心負教，橫遭三豹。","（见《朝野僉載》卷二）（按：《全唐诗》卷八七六作三言二句，係錄自《新唐书》卷一八六《王旭傳》。","今重錄。","）。"]', '诗', 'shi', '', NULL, '京中人作二豹咒（題擬） 佚名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2327f154-3652-445e-a445-1a6fcfce30bb', '時人爲韓朝宗語（題擬）', '时人爲韓朝宗語（題擬）', 'a002968d-fb03-407c-9a25-eae63a182674', '唐', '["生不願封萬戶侯，但願一識韓荆州。","（角《李太白全集》卷二十六《與韓荆州書》引。","）。"]', '["生不願封万戶侯，但願一識韓荆州。","（角《李太白全集》卷二十六《與韓荆州书》引。","）。"]', '诗', 'shi', '', NULL, '時人爲韓朝宗語（題擬） 佚名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('68b4412c-23d1-4c7e-9287-25337deaad33', '輕薄者爲進士及第語（題擬） 一', '轻薄者爲進士及第語（題擬） 一', 'a002968d-fb03-407c-9a25-eae63a182674', '唐', '["及第進士，俯視中黃郎；落第進士，揖蒲華長馬。"]', '["及第進士，俯視中黄郎；落第進士，揖蒲华长马。"]', '诗', 'shi', '', NULL, '輕薄者爲進士及第語（題擬） 一 佚名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8787c28e-de9f-4894-99f6-27a0f8da59a1', '輕薄者爲進士及第語（題擬） 二', '轻薄者爲進士及第語（題擬） 二', 'a002968d-fb03-407c-9a25-eae63a182674', '唐', '["進士初及第，頭上七尺焰光。","（見《封氏聞見記》卷三）。"]', '["進士初及第，头上七尺焰光。","（见《封氏闻见記》卷三）。"]', '诗', 'shi', '', NULL, '輕薄者爲進士及第語（題擬） 二 佚名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dcb55202-a4c0-4d5a-a88b-f514736a8739', '世人爲吳道子王陁子言（題從《古謠諺》卷四十）', '世人爲吳道子王陁子言（題從《古謠諺》卷四十）', 'a002968d-fb03-407c-9a25-eae63a182674', '唐', '["陁子頭，道子脚。","（《歷代名畫記》卷三）。"]', '["陁子头，道子脚。","（《歷代名畫記》卷三）。"]', '诗', 'shi', '', NULL, '世人爲吳道子王陁子言（題從《古謠諺》卷四十） 佚名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('047080a1-fb34-498c-aa33-3ca2dcecef64', '徐浩引俗語', '徐浩引俗語', 'a002968d-fb03-407c-9a25-eae63a182674', '唐', '["書無百日工。","（《法書要錄》卷三徐浩《論書》引）。"]', '["书無百日工。","（《法书要錄》卷三徐浩《論书》引）。"]', '诗', 'shi', '', NULL, '徐浩引俗語 佚名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('690277cb-8a3b-4529-9183-ac719312d141', '唐時爲八詩人語（題從《古謠諺》卷十二）', '唐时爲八诗人語（題從《古謠諺》卷十二）', 'a002968d-fb03-407c-9a25-eae63a182674', '唐', '["前有沈宋王杜，後有錢郎劉李。","（《唐才子傳》卷二《劉長卿傳》）。"]', '["前有沈宋王杜，後有錢郎劉李。","（《唐才子傳》卷二《劉长卿傳》）。"]', '诗', 'shi', '', NULL, '唐時爲八詩人語（題從《古謠諺》卷十二） 佚名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('81b4e09c-dacf-4f3a-b518-60bd0920b7ac', '時人爲魏博牙軍語（題擬）', '时人爲魏博牙軍語（題擬）', 'a002968d-fb03-407c-9a25-eae63a182674', '唐', '["長安天子，魏府牙軍。","（《新唐書》卷二一○《藩鎮魏博傳》）。"]', '["长安天子，魏府牙軍。","（《新唐书》卷二一○《藩鎮魏博傳》）。"]', '诗', 'shi', '', NULL, '時人爲魏博牙軍語（題擬） 佚名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f624aa66-66cf-4fe1-b994-fcead78e37df', '陳藏器引俗語', '陳藏器引俗語', 'a002968d-fb03-407c-9a25-eae63a182674', '唐', '["韭是草鍾乳，芡是水硫磺。","（《古謠諺》卷三十八引陳藏器《本草拾遺》）（按：《重修政和經史證類備用本草》卷二十三引陳藏器《本草》作「韭葉是草種乳」。","）。"]', '["韭是草鍾乳，芡是水硫磺。","（《古謠諺》卷三十八引陳藏器《本草拾遺》）（按：《重修政和經史證類備用本草》卷二十三引陳藏器《本草》作「韭葉是草種乳」。","）。"]', '诗', 'shi', '', NULL, '陳藏器引俗語 佚名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('020e98e0-abae-4db9-8fe5-7f8a9f8d8de0', '時人爲陽城鄭剛李周南語（題從《古謠諺》卷五七）', '时人爲陽城鄭剛李周南語（題從《古謠諺》卷五七）', 'a002968d-fb03-407c-9a25-eae63a182674', '唐', '["轉遠轉高，轉近轉卑。","（《唐國史補》卷上）。"]', '["轉远轉高，轉近轉卑。","（《唐国史補》卷上）。"]', '诗', 'shi', '', NULL, '時人爲陽城鄭剛李周南語（題從《古謠諺》卷五七） 佚名 shi');
